window.POO=window.POO||{};window.POO.data=window.POO.data||{};window.POO.data.questions=[{"q":"Las fases genéricas del desarrollo del software son:","o":["Análisis, modelado, codificación y testeo.","Análisis, diseño, codificación, pruebas y mantenimiento.","Diseño, escritura y verificación.","Verificación y validación."],"h":["Son las etapas clásicas del ciclo de vida.","Incluye la fase de construcción del sistema.","La última fase adapta el sistema a nuevos requisitos."],"c":1,"e":"Las etapas principales de cualquier ciclo de vida son: Análisis, Diseño, Codificación, Prueba y Mantenimiento.","d":1,"id":"q001","unit":"UF2406-UD1"},{"q":"¿Cuál de estas es una ventaja del ciclo de vida clásico (en cascada)?","o":["Es fácil arreglar los errores.","Se obtiene el producto al final.","La planificación es sencilla.","Hay muchos indicadores del ritmo de trabajo."],"h":["Es el modelo propuesto por Royce en 1970.","Trabaja en base a documentos formales.","Permite trabajar con empleados de menor cualificación."],"c":2,"e":"El modelo en cascada tiene como ventaja que la planificación del proyecto es sencilla y fácil de hacer, y la calidad es alta si se aplica correctamente.","d":2,"id":"q002","unit":"UF2406-UD1"},{"q":"¿Cuál NO es una ventaja del ciclo de vida en espiral?","o":["Es difícil evaluar los riesgos.","No necesita una definición completa de los requisitos al comienzo.","El riesgo en general es menor.","Es más fácil validar los requisitos."],"h":["Es un modelo evolutivo e iterativo.","Entrega productos desde la primera iteración.","La incertidumbre limita la estimación adecuada."],"c":0,"e":"La dificultad para llevar a cabo una evaluación correcta de los riesgos es un inconveniente del modelo en espiral, no una ventaja.","d":2,"id":"q003","unit":"UF2406-UD1"},{"q":"¿Cuál de las siguientes NO es una técnica de extracción de requisitos?","o":["El modelado de requisitos durante el análisis.","Las entrevistas y Brainstorming.","El Desarrollo Conjunto de Aplicaciones (JAD).","Los prototipos."],"h":["Las técnicas de extracción buscan descubrir necesidades directamente.","El modelado es una fase posterior de representación.","JAD y Brainstorming son técnicas de obtención directa."],"c":0,"e":"El modelado de requisitos es una fase de representación y estructuración, no una técnica de extracción como las entrevistas, JAD, brainstorming o prototipos.","d":2,"id":"q004","unit":"UF2406-UD1"},{"q":"La matriz de trazabilidad:","o":["Se usa para comprobar que los requisitos del proyecto se están cumpliendo.","Nos indica los errores de diseño.","Sirve para que el usuario tenga una buena experiencia de uso.","Indica el número de clases de un proyecto."],"h":["Es un documento en forma de tabla.","Correlaciona dos documentos (ej. requisitos y casos de prueba).","Determina la integridad de la relación entre requisitos."],"c":0,"e":"Una matriz de trazabilidad se utiliza para comprobar si se están cumpliendo los requisitos actuales del proyecto y para rastrear su origen y evolución.","d":2,"id":"q005","unit":"UF2406-UD1"},{"q":"La metodología Métrica:","o":["Es la metodología oficial de las administraciones públicas en España.","Es obligatorio utilizarla en toda España, salvo en el País Vasco y Navarra.","No tiene fase de análisis de requisitos.","No es orientada a objetos."],"h":["Sistematiza todas las actividades del ciclo de vida.","Incluye procesos que no forman parte estrictamente del ciclo de vida (como gestión de configuración).","Tiene en cuenta tecnologías para sistemas distribuidos."],"c":0,"e":"La metodología Métrica es la metodología oficial de desarrollo de aplicaciones de la administración española.","d":1,"id":"q006","unit":"UF2406-UD1"},{"q":"¿Cuáles NO son objetivos de una herramienta CASE?","o":["Facilitar la realización de prototipos.","Eliminar la necesidad de esfuerzo de programación.","Mejorar y estandarizar la documentación.","Facilitar la reutilización de componentes."],"h":["Automatizan tareas del ciclo de vida.","Mejoran la productividad del ingeniero.","No eliminan la necesidad de programar, solo la facilitan y organizan."],"c":1,"e":"Las herramientas CASE facilitan y automatizan tareas, pero no eliminan la necesidad de esfuerzo de programación por parte del desarrollador.","d":2,"id":"q007","unit":"UF2406-UD1"},{"q":"Las herramientas de ingeniería del software:","o":["Trabajan solamente a bajo nivel.","Trabajan a nivel medio de la organización.","Trabajan fundamentalmente a alto nivel.","Modelan la organización a nivel táctico."],"h":["Se centran en análisis, diseño y validación.","Se utilizan en el modelado de procesos de negocio.","Proporcionan una visión global del sistema."],"c":2,"e":"Las herramientas de ingeniería del software actúan fundamentalmente a alto nivel, centrándose sobre todo en las actividades de análisis, diseño y validación del software.","d":2,"id":"q008","unit":"UF2406-UD1"},{"q":"Sobre un IDE (Entorno de Desarrollo Integrado):","o":["Está perfectamente claro qué es un IDE y qué no lo es.","No suelen incorporar un navegador de clases.","No están diseñados para aumentar la productividad de los programadores.","Todas las anteriores son falsas."],"h":["Proporciona servicios integrales (editor, compilador, depurador).","Maximiza la productividad.","El límite exacto de qué es un IDE no está rígidamente definido."],"c":3,"e":"Un IDE sí incorpora navegador de clases, sí está diseñado para aumentar la productividad, y el límite de qué es un IDE no está perfectamente definido. Por tanto, a, b y c son falsas.","d":2,"id":"q009","unit":"UF2406-UD1"},{"q":"Sobre los prototipos:","o":["No deben ser mostrados al usuario final.","Deben centrarse en la arquitectura de sistema en vez de en su aspecto.","No requieren de ninguna herramienta en especial.","Su propósito es que los usuarios finales puedan evaluar las propuestas de los desarrolladores."],"h":["Son versiones reducidas de la aplicación final.","Sirven para obtener y validar requisitos.","Permiten experimentar con el diseño antes de la implementación final."],"c":3,"e":"El propósito de un prototipo es permitir que los usuarios del software puedan evaluar las propuestas de los desarrolladores y experimentar con dichos diseños.","d":1,"id":"q010","unit":"UF2406-UD1"},{"q":"Los tipos de modelos de estimación que hay son:","o":["Modelos de determinación de análisis, modelado, codificación y testeo.","Modelos matemáticos paramétricos, Estimación basada en la experiencia de experto, técnicas orientadas al aprendizaje y modelos dinámicos.","Modelos matemáticos paramétricos, Estimación basada en la experiencia de experto, técnicas orientadas al aprendizaje y modelos de verificación.","Modelos de Verificación y validación."],"h":["Clasificación basada en el enfoque de cálculo.","Incluye enfoques estadísticos y juicios humanos.","Consideran la variación temporal de los costes."],"c":1,"e":"Los cuatro grupos de métodos de estimación son: modelos paramétricos, basados en expertos, orientados al aprendizaje y modelos dinámicos.","d":2,"id":"q011","unit":"UF2406-UD2"},{"q":"¿Cuál de estos NO es un método de estimación?","o":["COCOMO.","Método de PUTNAM.","PERT.","MK II."],"h":["COCOMO y Putnam son modelos paramétricos de esfuerzo.","MK II es un método de puntos de función.","PERT es una técnica de diagramado de red."],"c":2,"e":"PERT es una herramienta de planificación y diagramado de actividades (ruta crítica), no un modelo de estimación de esfuerzo/coste como los otros.","d":3,"id":"q012","unit":"UF2406-UD2"},{"q":"Sobre el método COSMIC, indica la respuesta falsa:","o":["Es difícil evaluar los riesgos en él.","Es un método de evaluación de segunda generación.","Es un método abierto.","Se ajusta a la normativa ISO."],"h":["Se basa en principios fundamentales de ingeniería de software.","Es el primer método ajustado a la norma ISO/IEC 14143/1:2003.","Su documentación es gratuita y abierta."],"c":0,"e":"El método COSMIC es abierto, de segunda generación y se ajusta a la normativa ISO. No es una característica definitoria que sea \"difícil evaluar riesgos\"; de hecho, mejora la precisión de la estimación.","d":3,"id":"q013","unit":"UF2406-UD2"},{"q":"La actividad de planificación o programación de un proyecto, consiste en establecer la estructura temporal de...","o":["Las fases, actividades y tareas del proyecto, en función de los recursos de que se deseen.","Las fases del proyecto, en función de los recursos de que se disponga.","Las fases, actividades y tareas del proyecto, en función de los recursos de que se disponga.","Las fases de programación así como sus, actividades y tareas del proyecto, en función de los recursos de que se disponga."],"h":["Organiza el trabajo en el tiempo.","Considera fases, actividades y tareas de forma integral.","Depende de los recursos disponibles, no de los deseados."],"c":2,"e":"La planificación consiste en establecer la estructura temporal de las fases, actividades y tareas del proyecto, en función de los recursos de que se disponga.","d":1,"id":"q014","unit":"UF2406-UD2"},{"q":"Las actividades del método PERT:","o":["Se representan mediante cajas.","Se representan mediante flechas.","Se representan mediante rombos.","No se indican explícitamente en el diagrama."],"h":["PERT usa diagramas de red.","En la notación descrita en el texto, los nodos son eventos.","Las actividades se representan con cajas que contienen su nombre e información."],"c":0,"e":"Según el documento, en la construcción de diagramas PERT descrita, una actividad se representa por cajas que contienen el nombre de la actividad y alguna información adicional.","d":2,"id":"q015","unit":"UF2406-UD2"},{"q":"El seguimiento y control:","o":["Es fundamental en la gestión de un proyecto.","Se hace mediante el método COCOMO.","No es necesario en proyectos pequeños.","Se realiza mediante herramientas de dimensionamiento."],"h":["Asegura que el proyecto satisface sus objetivos en calidad, coste y tiempo.","Implica recopilar datos reales y contrastarlos con los estimados.","Es una parte fundamental de la Gestión de Proyectos."],"c":0,"e":"El seguimiento y control es una parte fundamental de la Gestión de Proyectos; se ha observado que el éxito de los proyectos radica en un adecuado seguimiento y control del mismo.","d":1,"id":"q016","unit":"UF2406-UD2"},{"q":"El resumen ejecutivo:","o":["Se presenta al comienzo del proyecto/informe.","Se comienza con la planificación.","Se presenta al final de proyecto.","Se presenta al finalizar la fase de diseño."],"h":["Da una visión general concisa.","Aparece al comienzo de un informe de gestión.","Ayuda a decidir si leer todo el informe o centrarse en una parte."],"c":0,"e":"El resumen ejecutivo se presenta al comienzo de un informe de gestión del proyecto para dar al lector una visión general concisa del propósito, resultados y problemas.","d":2,"id":"q017","unit":"UF2406-UD2"},{"q":"En la presentación de un informe:","o":["No hay que añadir la metodología.","Conviene estructurarlo adecuadamente.","Se puede obviar el formato para mayor velocidad.","No es necesario difundirlo entre el equipo."],"h":["Debe ser lo más conciso posible sin sacrificar calidad.","Debe dividirse en categorías claramente etiquetadas.","Hay que revisar errores tipográficos y de formato."],"c":1,"e":"Conviene estructurar el informe adecuadamente, dividir el contenido en categorías y cuidar el formato para guiar la atención de los lectores.","d":1,"id":"q018","unit":"UF2406-UD2"},{"q":"Las técnicas de formato a la hora de elaborar un informe:","o":["No son necesarias para hacer un informe.","Dependen de la organización y no del autor.","Son necesarias para poder presentarlo adecuadamente.","Modelan la organización a nivel táctico."],"h":["Guían la atención de los lectores.","Usan subtítulos y viñetas.","Ahorran tiempo a los lectores que buscan información específica."],"c":2,"e":"Las técnicas de formato son necesarias para presentar el informe adecuadamente, guiando la atención de los lectores con categorías claras, subtítulos y viñetas.","d":1,"id":"q019","unit":"UF2406-UD2"},{"q":"La retroalimentación regular (en el contexto del método Delphi) se refiere a:","o":["El director del proyecto indica quien lo hace bien y quien lo hace mal.","Deben centrarse en los fallos cometidos.","No requieren de reuniones específicas.","Los participantes comentan sus propias previsiones y las de los demás."],"h":["Es una característica clave del método Delphi.","Se anima a los expertos a revisar sus respuestas anteriores.","El grupo converge hacia la respuesta \"correcta\"."],"c":3,"e":"En la retroalimentación regular, los participantes comentan sus propias previsiones y las respuestas de los demás, revisando sus declaraciones anteriores a la luz de las opiniones del grupo.","d":2,"id":"q020","unit":"UF2406-UD2"},{"q":"Un navegador web es:","o":["Es un hardware que se utiliza para acceder a un ordenador.","Es un software que se utiliza para acceder a Internet.","Es un hardware que se utiliza para acceder a Internet.","Es un software para acceder a un ordenador."],"h":["Interpreta información de archivos y sitios web.","Permite visitar páginas y realizar acciones (iniciar sesión, ver multimedia).","Ejemplos: Chrome, Firefox, Edge."],"c":1,"e":"Un navegador web es un software que se utiliza para acceder a Internet, interpretar información de sitios web y permitir al usuario interactuar con ellos.","d":1,"id":"q021","unit":"UF2405-UD1"},{"q":"Se define una arquitectura web como...","o":["Un sistema que da como resultado información a los usuarios, con independencia de donde este ubicada esa información.","Es un sistema que no da como resultado información a los usuarios...","Es una combinación de sistemas que colaboran entre sí para dar como resultado a los usuarios información, con independencia de donde este ubicada la información.","Es una combinación de sistemas que son incapaces de colaborar entre sí..."],"h":["Implica colaboración entre sistemas (cliente, servidor, etc.).","El resultado final es información útil para el usuario.","La ubicación física de la información es transparente para el usuario."],"c":2,"e":"La arquitectura web se define como la combinación de sistemas que colaboran entre sí para dar como resultado información a los usuarios, con independencia de dónde esté ubicada dicha información.","d":1,"id":"q022","unit":"UF2405-UD1"},{"q":"Un servidor web se ejecuta durante:","o":["Todo el día.","365 días al año.","12 horas al día.","Todo el día los 365 días del año."],"h":["Mantiene a la espera de peticiones de clientes.","Almacena y transmite datos de un sitio.","Requiere un funcionamiento continuo y ininterrumpido."],"c":3,"e":"Un servidor web es un tipo de software que se instala y se ejecuta constantemente en un ordenador, todo el día los 365 días del año, manteniéndose a la espera de las peticiones del cliente.","d":1,"id":"q023","unit":"UF2405-UD1"},{"q":"¿Qué elementos forman parte de la arquitectura web básica?","o":["Cliente.","Cliente y servidor.","Servidor.","Ninguno de los anteriores."],"h":["Modelo básico de comunicación en red.","Uno solicita información, el otro responde.","Se conoce como arquitectura Cliente/Servidor."],"c":1,"e":"La arquitectura web básica se compone de un cliente (que solicita) y un servidor (que responde), formando el modelo fundamental Cliente/Servidor.","d":1,"id":"q024","unit":"UF2405-UD1"},{"q":"Ventajas de utilizar un cliente ligero:","o":["Información centralizada, menos coste de hardware, menos coste en administración.","Información centralizada, menos coste de hardware, menos coste en administración, consumo energético.","Información centralizada, menos coste de hardware, menos coste en administración, consumo energético, más seguro.","Información centralizada, menos coste en administración, consumo energético, más seguro."],"h":["El procesamiento pesado está en el servidor.","Requiere menos recursos locales (RAM, disco).","Mayor seguridad al no almacenar datos sensibles localmente."],"c":2,"e":"Las ventajas incluyen: información centralizada, menos coste de hardware, menos coste en administración, menor consumo energético y mayor seguridad.","d":2,"id":"q025","unit":"UF2405-UD1"},{"q":"¿A qué protocolo corresponde la función de transformar y dar significado a los mensajes intercambiados entre el Cliente y el Servidor?","o":["TCP/IP.","FTP.","HTTP.","NEWS."],"h":["Es el protocolo por defecto en la web.","Sus siglas son HyperText Transfer Protocol.","No guarda referencia a conexiones previas (es sin estado)."],"c":2,"e":"El protocolo HTTP es el que va a transformar y dar significado a los mensajes intercambiados entre el cliente (navegador) y el servidor web.","d":1,"id":"q026","unit":"UF2405-UD1"},{"q":"Los lenguajes estructurados son:","o":["XML, ASP, HTTP.","HTML Y CSS.","XML y HTTP.","FTP, XML y CSS."],"h":["Definen la estructura y el contenido de la página.","HTML es el principal lenguaje de marcado estructurado.","El documento los agrupa en esta categoría para la maquetación."],"c":1,"e":"El lenguaje HTML es un lenguaje estructurado utilizado para definir la estructura y el contenido de una página web (y CSS se asocia en el contexto de la pregunta a la presentación estructurada).","d":2,"id":"q027","unit":"UF2405-UD1"},{"q":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente:","o":["HTML, JSP, ASP Y PHP.","ASP, HTML, JAVASCRIPT, PHP y JSP.","FTP, ASP, PHP, JSP y JAVASCRIPT.","FTP, ASP, PHP, JSP y HTML."],"h":["Incluyen lenguajes de scripting y marcado.","El documento lista explícitamente estos cinco como los principales.","FTP es un protocolo de transferencia, no un lenguaje de programación."],"c":1,"e":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente: HTML, ASP, JAVASCRIPT, PHP y JSP.","d":1,"id":"q028","unit":"UF2405-UD1"},{"q":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente (enfoque en servidor/dinámico):","o":["ASP y PHP.","ASP y JAVASCRIPT.","PHP y JAVASCRIPT.","ASP y HTML."],"h":["Son lenguajes de script del lado del servidor muy populares.","Permiten crear páginas dinámicas e interactuar con bases de datos.","El documento los destaca como los principales en su categoría de procesamiento."],"c":0,"e":"Entre las opciones dadas, ASP y PHP son los lenguajes de programación del lado del servidor más utilizados y destacados para el desarrollo web dinámico.","d":2,"id":"q029","unit":"UF2405-UD1"},{"q":"Un objeto es una...","o":["Un estado y una identidad propia.","Un comportamiento.","Una entidad.","Una entidad que tiene un estado, un comportamiento y una identidad propia."],"h":["Concepto fundamental de la Programación Orientada a Objetos (POO).","Representa algo del mundo real (físico o abstracto).","Combina datos (atributos) y funciones (métodos)."],"c":3,"e":"Definimos un objeto como una entidad que tiene un estado, un comportamiento y una identidad propios.","d":1,"id":"q030","unit":"UF2405-UD1"},{"q":"¿Qué es UML?","o":["Un lenguaje de programación estructurado.","Un conjunto de especificaciones que indican cómo construir unos diagramas que sirven para intercambiar información.","Una metodología de desarrollo orientada a objetos.","Un ciclo de vida de desarrollo del software."],"h":["Sus siglas significan Lenguaje de Modelado Unificado.","Es un estándar de modelado visual, no un proceso de desarrollo en sí mismo.","Lo gestiona el Object Management Group (OMG)."],"c":1,"e":"UML es un lenguaje de modelado visual estándar destinado a describir, especificar, diseñar y documentar procesos de negocio y sistemas de software. No es una metodología ni un ciclo de vida, sino un conjunto de especificaciones para diagramas.","d":1,"id":"q031","unit":"UF2406-UD3"},{"q":"Los diagramas de comportamiento en UML:","o":["Muestran el comportamiento dinámico de las clases del sistema.","Muestran cómo se desarrolla un determinado caso de uso.","Muestran el comportamiento dinámico de los objetos del sistema.","Ninguna de las anteriores."],"h":["Se contraponen a los diagramas de estructura.","Describen una serie de cambios en el sistema a lo largo del tiempo.","Ejemplos incluyen diagramas de actividad, de secuencia y de casos de uso."],"c":2,"e":"Los diagramas de comportamiento muestran el comportamiento dinámico de los objetos en un sistema, que puede ser descrito como una serie de cambios en el sistema a lo largo del tiempo.","d":2,"id":"q032","unit":"UF2406-UD3"},{"q":"Una clase abstracta en UML se define como:","o":["Una clase de la que no pueden heredar otras.","Una clase con solo un objeto asociado.","Una clase de la que no se pueden crear objetos.","Ninguna es correcta."],"h":["Existe solo para que otras clases hereden de ella.","Su nombre suele representarse en cursiva en los diagramas.","No tiene instanciación directa."],"c":2,"e":"Una clase abstracta se define como una clase que no se puede instanciar (crear objetos) directamente. Existe para que otras clases hereden de ella y apoyen la reutilización de características.","d":2,"id":"q033","unit":"UF2406-UD3"},{"q":"En UML, la visibilidad de los elementos puede ser:","o":["Pública, de paquete, protegida y privada.","Pública, protegida y privada.","Se usa solamente en clases.","Se indica solo en atributos y métodos."],"h":["Se representa con símbolos como +, ~, #, -.","Permite restringir el uso de un elemento llamado.","Aplica a clases, paquetes, generalizaciones, etc."],"c":0,"e":"UML cuenta con cuatro tipos de visibilidad: pública (+), de paquete (~), protegida (#) y privada (-), que permiten restringir el acceso a los elementos.","d":1,"id":"q034","unit":"UF2406-UD3"},{"q":"Un actor en un diagrama de casos de uso:","o":["Es parte del sistema software modelado.","Representa un elemento externo al sistema.","Solamente se indica mediante un \"hombre de palo\".","Ninguna de las respuestas es correcta."],"h":["Interactúa con el escenario o sistema.","Puede ser un usuario humano, otro sistema o hardware.","Desempeña un rol específico frente al sistema."],"c":1,"e":"Un actor es un clasificador con comportamiento que especifica un papel desempeñado por una entidad externa que interactúa con el escenario (sistema).","d":1,"id":"q035","unit":"UF2406-UD3"},{"q":"En Java, un contenedor de AWT:","o":["Solo puede albergar componentes y no contenedores.","Es a su vez un componente.","Sirve de almacén exclusivo de botones.","Se almacena en una clase JComponente."],"h":["La estructura básica de la librería gira en torno a componentes y contenedores.","Los eventos pueden tratarse tanto en contenedores como en componentes.","Ejemplos son Frame, Panel y Window."],"c":1,"e":"Los contenedores albergan componentes y son componentes a su vez, de forma que los eventos pueden tratarse tanto en contenedores como en componentes.","d":2,"id":"q036","unit":"UF2406-UD4"},{"q":"Según las \"reglas de oro\" de Mantel para el diseño de interfaces, una de ellas es:","o":["Dar el control al usuario.","Utilizar ventanas deslizantes siempre que se pueda.","Todos los botones deben llevar Icono.","Siempre hay que incluir una ayuda on-line."],"h":["Busca reducir la frustración del usuario.","Permite interacción flexible y deshacer acciones.","Las otras dos reglas son reducir la carga de memoria y presentar la información de manera consistente."],"c":0,"e":"Las tres reglas de oro de Mantel son: Dar el control al usuario, Reducir la carga de memoria del usuario, y La información debe desglosarse de manera progresiva (interfaz consistente).","d":2,"id":"q037","unit":"UF2406-UD4"},{"q":"El tiempo de respuesta en una interfaz de usuario:","o":["Lo importante es que su duración sea mínima.","Se caracteriza por dos valores, su duración y su variabilidad.","Ha de tratarse de minimizar su media ponderada.","Ninguna de las respuestas es correcta."],"h":["Si es muy largo, frustra al usuario.","Si es demasiado corto, puede precipitar errores.","Una variabilidad baja permite mantener un ritmo de trabajo constante."],"c":1,"e":"El tiempo de respuesta está caracterizado por dos valores: su duración (media) y su variabilidad (varianza). Una variabilidad baja permite al usuario mantener un ritmo de trabajo constante.","d":2,"id":"q038","unit":"UF2406-UD4"},{"q":"Cuando se produce un evento en la programación guiada por eventos de Java:","o":["Se llama al método \"actionPerformed\" de los oyentes registrados.","El programador debe detectarlos con un esquema if manual.","Se generan tres objetos asociados: el oyente, el evento y la interrupción.","Se recibe un parámetro en el programa principal."],"h":["El modelo de eventos de Java se basa en la delegación.","Un objeto fuente notifica a un objeto oyente.","El oyente implementa una interfaz como ActionListener."],"c":0,"e":"Cada vez que se produce una acción (evento), se genera un objeto de evento (ej. ActionEvent) y se pasa al método correspondiente del listener (oyente) registrado, el cual ejecuta el código dispuesto para ese evento.","d":2,"id":"q039","unit":"UF2406-UD4"},{"q":"Son métodos de la clase TextArea en Java:","o":["getText y setText.","getManyValues y getProportions.","deleteWindows y setWindowsDefault.","Ninguno de los anteriores."],"h":["TextArea proporciona un área para mantener varias líneas de texto.","Permite obtener el contenido actual.","Permite establecer o cambiar el contenido del área de texto."],"c":0,"e":"Los métodos más utilizados de TextArea son getText() para devolver el texto en el área y setText(String s) para establecer o modificar el texto.","d":1,"id":"q040","unit":"UF2406-UD4"},{"q":"La arquitectura Cliente/Servidor básica (de dos capas) se compone de:","o":["Cliente y servidor.","Cliente, servidor de aplicaciones y servidor de datos.","Servidor de aplicación y servidor de datos.","Ninguna de las anteriores es correcta."],"h":["Es la estructura más simple de red.","El cliente solicita y el servidor responde.","No incluye una capa intermedia de lógica de negocio separada físicamente."],"c":0,"e":"La arquitectura Cliente/Servidor genérica o básica se compone solo del Cliente y del Servidor, recibiendo el nombre de arquitectura de dos niveles o dos capas.","d":1,"id":"q041","unit":"UF2405-UD2"},{"q":"Una arquitectura n_capas se compone de:","o":["Cliente, servidor de aplicaciones, servidor de datos.","Cliente y servidor de aplicación.","Cliente, servidor de aplicación, servidor de datos y otros servidores capaces de dar servicios.","Servidor de aplicación, servidor de datos."],"h":["Es una evolución de la arquitectura de tres capas.","Puede incluir servidores adicionales según las necesidades del negocio.","Ejemplos de servidores adicionales: chat, correo electrónico, etc."],"c":2,"e":"La arquitectura n_capas, además de componerse del Cliente, Servidor de aplicación y Servidor de datos, puede llevar otro u otros tipos más de servidores especializados.","d":2,"id":"q042","unit":"UF2405-UD2"},{"q":"¿Qué permite el Middleware en un sistema distribuido?","o":["Permitir la comunicación entre las aplicaciones que están repartidas por una red de ordenadores.","Nunca permitirá la comunicación entre las aplicaciones.","A veces permitirá la comunicación.","Ninguna de las anteriores es correcta."],"h":["Actúa como conductor o intermediario entre sistemas.","Se ejecuta en ambas partes (cliente y servidor).","Evita el uso de tecnologías propietarias para la interconexión."],"c":0,"e":"El middleware actuará como conductor entre sistemas permitiendo que cualquier usuario pueda comunicarse con varias fuentes de información conectadas por una red, siendo el intermediario transparente entre el cliente y el servidor.","d":2,"id":"q043","unit":"UF2405-UD2"},{"q":"El concepto de n-Tier se refiere a:","o":["El número de capas lógicas.","El número de capas lógicas y físicas.","El número de capas y la distribución física de estas.","El número de capas."],"h":["Se contrapone a n-layer (que es solo la organización lógica del código).","Define dónde suceden los procesos físicamente.","Está relacionado con la distribución en diferentes ordenadores o servidores."],"c":2,"e":"El n_Tier es el número de capas y la distribución física de estas, es decir, dónde suceden los procesos y se encuentra el código físicamente en la red.","d":3,"id":"q044","unit":"UF2405-UD2"},{"q":"La estructura lógica del modelo multicapa (de tres capas) se divide en:","o":["Capa de presentación y capa de aplicación o de negocio.","Capa de aplicación o de negocio.","Capa de presentación, capa de aplicación o de negocio y capa de gestión de datos.","Capa de presentación y capa de gestión de datos."],"h":["La primera interactúa con el usuario.","La segunda contiene la lógica y reglas del negocio.","La tercera se encarga del almacenamiento y acceso a los datos."],"c":2,"e":"La estructura lógica de este modelo se divide en tres: Capa de gestión de datos, Capa de aplicación o de negocio, y La capa de Presentación.","d":1,"id":"q045","unit":"UF2405-UD2"},{"q":"¿A qué capa corresponderá la función de almacenamiento de datos?","o":["A la capa de gestión de datos.","A la capa de presentación.","A la capa de aplicación o de negocio.","A la capa de presentación y a la de aplicación o de negocio."],"h":["Es la capa más baja en la jerarquía de tres capas.","Utiliza sistemas gestores de bases de datos como SQL Server u Oracle.","Suministra los datos solicitados por el servidor de aplicación."],"c":0,"e":"La capa de datos (o gestión de datos) corresponderá al almacenamiento de los datos y al acceso a ellos, siendo responsable del tratamiento de gestión y almacenamiento.","d":1,"id":"q046","unit":"UF2405-UD2"},{"q":"¿Qué patrón arquitectónico se utiliza para unificar las aplicaciones web separando la interfaz gráfica del código?","o":["VCA.","MVC.","NCV.","CML."],"h":["Sus siglas significan Modelo-Vista-Controlador.","El Controlador recibe las peticiones del usuario.","El Modelo gestiona la lógica de negocio y los datos."],"c":1,"e":"Para unificar las aplicaciones web se utiliza un patrón arquitectónico llamado Modelo Vista Controlador (MVC), que separa la interfaz gráfica (Vista) del código de programación (Controlador y Modelo).","d":2,"id":"q047","unit":"UF2405-UD2"},{"q":"Una aplicación distribuida está formada por componentes que se dividen según:","o":["Sea del lado del servidor.","Sea del lado del Cliente.","Sea del lado del cliente o del lado del servidor.","Las tres anteriores son correctas (en conjunto definen la división)."],"h":["El lado del cliente realiza las peticiones (ej. navegador).","El lado del servidor espera y responde a las peticiones.","La división abarca ambos lados por definición."],"c":3,"e":"Una aplicación distribuida está formada por un conjunto de distintos componentes que se dividirán según sea del Lado del Cliente o del Lado del servidor, por lo que las opciones que mencionan estos lados son correctas en su conjunto.","d":2,"id":"q048","unit":"UF2405-UD2"},{"q":"¿Cuál será el objetivo principal de separar la capa lógica o de negocio?","o":["Ahorro económico.","Ahorro energético.","Perder flexibilidad.","Ganar flexibilidad."],"h":["Permite almacenar físicamente la capa de negocios de forma independiente.","Facilita la reutilización de la lógica desde distintas capas de presentación.","Permite modificar la capa de datos sin afectar a la presentación."],"c":3,"e":"Separando en capas lógicas la aplicación, se conseguirá flexibilidad a la hora de almacenar físicamente la capa de negocios, ejecutarla en un servidor centralizado y modificarla sin afectar a las otras capas.","d":2,"id":"q049","unit":"UF2405-UD2"},{"q":"Los motores de reglas de negocio son:","o":["Un conjunto de peticiones, reglas y normas del negocio.","Un conjunto de componentes que a partir de un conjunto de reglas detectará cuáles deben de utilizarse.","Un conjunto de reglas.","Un conjunto de reglas y estándares."],"h":["Forman parte de la capa de negocio.","Evalúan condiciones dinámicamente.","Determinan el resultado de aplicar dichas reglas."],"c":1,"e":"Los motores de reglas de negocio son componentes que, a partir de un conjunto de reglas, detectarán qué reglas deberán de utilizarse y cuál será el resultado de aplicarlas.","d":2,"id":"q050","unit":"UF2405-UD2"},{"q":"La arquitectura Cliente/Servidor básica se compone de:","o":["Cliente y servidor.","Cliente, servidor de aplicaciones y servidor de datos.","Servidor de aplicación y servidor de datos.","Ninguna de las anteriores es correcta."],"h":["Es el modelo de red más simple.","No incluye capas intermedias de lógica de negocio separada físicamente.","Consta únicamente de quien pide la información y quien la responde."],"c":0,"e":"La arquitectura Cliente/Servidor genérica o básica se compone únicamente del Cliente y del Servidor, recibiendo el nombre de arquitectura de dos niveles o dos capas.","d":1,"id":"q051","unit":"UF2405-UD2"},{"q":"¿Qué permitirá el Middleware?","o":["Permitirán la comunicación entre las aplicaciones que están repartidas por una red de ordenadores.","Nunca permitirán la comunicación entre las aplicaciones.","A veces permitirán la comunicación.","Ninguna de las anteriores es correcta."],"h":["Actúa como conductor o intermediario entre sistemas.","Se ejecuta en ambas partes (cliente y servidor).","Evita el uso de tecnologías propietarias para la interconexión."],"c":0,"e":"El middleware actuará como conductor entre sistemas permitiendo que cualquier usuario pueda comunicarse con varias fuentes de información conectadas por una red, siendo el intermediario transparente.","d":2,"id":"q052","unit":"UF2405-UD2"},{"q":"La estructura lógica del modelo multicapa se divide en:","o":["Capa de presentación y capa de aplicación o de negocio.","Capa de aplicación o de negocio.","Capa de presentación, capa de aplicación o de negocio y capa de gestión de datos.","Capa de presentación y capa de gestión de datos."],"h":["La primera interactúa con el usuario.","La segunda contiene la lógica y reglas del negocio.","La tercera se encarga del almacenamiento y acceso a los datos."],"c":2,"e":"La estructura lógica de este modelo se divide en tres: Capa de gestión de datos, Capa de aplicación o de negocio, y La capa de Presentación.","d":1,"id":"q053","unit":"UF2405-UD2"},{"q":"Una aplicación distribuida está formada por componentes que se dividen según:","o":["Sea del lado del servidor.","Sea del lado del Cliente.","Sea del lado del cliente o del lado del servidor.","Las tres anteriores son correctas."],"h":["El lado del cliente realiza las peticiones (ej. navegador).","El lado del servidor espera y responde a las peticiones.","La división abarca ambos lados por definición."],"c":3,"e":"Una aplicación distribuida está formada por un conjunto de distintos componentes que se dividirán según sea del Lado del Cliente o del Lado del servidor, por lo que las opciones que mencionan estos lados son correctas en su conjunto.","d":2,"id":"q054","unit":"UF2405-UD2"},{"q":"La base de toda interfaz de usuario es:","o":["Lenguaje ASP.","Lenguaje de marcado HTML.","Lenguaje XML.","Lenguaje C++."],"h":["Es un lenguaje de hipertexto.","Está formado por un conjunto de etiquetas.","Define la estructura y el contenido de una página web."],"c":1,"e":"El fundamento del interfaz de un usuario de una aplicación Web es el Lenguaje HTML (HyperText Markup Language), un lenguaje de marcado derivado de XML.","d":1,"id":"q055","unit":"UF2405-UD3"},{"q":"Los componentes que forman la capa de presentación se dividen en:","o":["Componentes de aplicación.","Componentes de aplicación y componentes de desarrollo.","Componentes de presentación y componentes de procesos.","Componentes de procesos y componentes de desarrollo."],"h":["Unos permiten al usuario interactuar directamente (botones, etiquetas).","Otros se utilizan para interacciones más complejas (frameworks de JavaScript).","Ambos conforman la interfaz visible."],"c":2,"e":"Los componentes que conforman la capa de presentación se dividen en dos: Componentes de presentación (interfaz para interactuar) y Componentes de procesos (para interacciones complejas).","d":1,"id":"q056","unit":"UF2405-UD3"},{"q":"Los lenguajes del lado del cliente corresponderán a:","o":["Los lenguajes que tendrán que transformar los datos para que lo entiendan el navegador web.","Los lenguajes que tendrán que transformar los datos para que lo entiendan el servidor de datos.","Los lenguajes que no tendrán que transformar los datos para que lo entiendan el navegador web.","Los lenguajes que tendrán que transformar los datos para que lo entiendan el servidor de aplicaciones."],"h":["Se ejecutan directamente en el navegador.","No requieren pre- tratamiento en el servidor.","Ejemplos: HTML, JavaScript, CSS."],"c":2,"e":"Los lenguajes del lado del Cliente corresponderán a los lenguajes que no tendrán que transformar los datos para que sean entendibles por el navegador, ya que se realizarán en HTML y no tendrán que ser pre-tratados.","d":2,"id":"q057","unit":"UF2405-UD3"},{"q":"Un Script es...","o":["Un pequeño programa que suele estar fuera del contenido HTML.","Un pequeño programa que suele estar dentro del contenido HTML.","Un pequeño programa que suele estar fuera y fuera del contenido HTML.","No es un programa."],"h":["Se carga cuando se ejecuta la página.","Responde a eventos del usuario.","Aporta dinamismo al documento."],"c":1,"e":"Un script se trata de un programa que suele estar dentro del contenido de HTML. Cuando se ejecuta, se cargarán todas las instrucciones de dicho programa, a esta acción se le denomina evento.","d":1,"id":"q058","unit":"UF2405-UD3"},{"q":"¿Qué es Java Script?","o":["Un lenguaje interpretado.","Un lenguaje orientado a objetos.","Un lenguaje no compilado.","A y b son correctas."],"h":["No necesita un compilador externo, el navegador lo interpreta.","Se basa en objetos para estructurar el código.","Se embebe directamente en el HTML."],"c":3,"e":"JavaScript es un lenguaje de programación orientado a objetos e interpretado, con lo que no necesitará la ayuda de compiladores, siendo el más utilizado como lenguaje de programación del lado del cliente.","d":2,"id":"q059","unit":"UF2405-UD3"},{"q":"Con Java Script se podrá crear:","o":["Efectos especiales para crear contenidos estáticos.","Efectos especiales para crear contenidos dinámicos.","Efectos especiales para crear contenidos dinámicos y dar movimiento a los componentes de la página web.","Efectos especiales para crear contenidos estáticos y dar movimiento a los componentes de la página web."],"h":["Permite validar formularios antes de enviarlos.","Puede modificar el DOM en tiempo real.","Aporta interactividad y movimiento."],"c":2,"e":"Con JavaScript se podrá realizar efectos para poder crear contenidos más dinámicos y también se podrá dar movimiento a los componentes de la página web.","d":2,"id":"q060","unit":"UF2405-UD3"},{"q":"Visual Basic Script solo es compatible con:","o":["Internet Explorer.","Mozilla Firefox.","Opera.","Google Chrome."],"h":["Es una versión reducida de Visual Basic.","Fue desarrollado por Microsoft.","Otros navegadores modernos no lo soportan de forma nativa."],"c":0,"e":"VBScript es una versión reducida del lenguaje de programación Visual Basic, desarrollada por Microsoft, y solo es compatible de forma nativa con Internet Explorer.","d":1,"id":"q061","unit":"UF2405-UD3"},{"q":"¿Qué significa CSS?","o":["Hoja de estilo.","Cascada.","Hoja de estilo en cascada.","Ninguna de las anteriores."],"h":["Sus siglas en inglés son Cascading Style Sheets.","Se ocupa de las características gráficas de un documento HTML.","Permite separar el contenido del diseño."],"c":2,"e":"CSS significa Hoja de Estilo en Cascada (Cascading Style Sheets). Este tipo de lenguaje se ocupa de las características gráficas que se les puede aplicar a los elementos de un documento HTML.","d":1,"id":"q062","unit":"UF2405-UD3"},{"q":"¿Cuáles son los lenguajes más utilizados del lado del servidor?","o":["CGI, PERL, ASP.","PHP, DHTML, XML.","ASP, PHP, PERL.","ASP, PHP, JSP y Servlets."],"h":["Se procesan en el servidor antes de enviar la respuesta al cliente.","Generan contenido dinámico.","Incluyen tecnologías Java y de Microsoft."],"c":3,"e":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web del lado del servidor son principalmente: ASP, PHP, JSP y Servlets (además de HTML y JavaScript en ciertos contextos mixtos).","d":2,"id":"q063","unit":"UF2405-UD3"},{"q":"PHP es un lenguaje de:","o":["Uso libre y gratuito.","Uso libre y de pago.","Uso libre de pago o gratuito.","Uso libre."],"h":["Sus siglas significan HyperText Preprocessor.","Es de código abierto.","Se incrusta en el código HTML."],"c":0,"e":"PHP es un lenguaje muy conocido popularmente por ser un lenguaje de código abierto, esto quiere decir que es libre de uso y gratuito, y para el desarrollo de páginas web dinámicas.","d":1,"id":"q064","unit":"UF2405-UD3"},{"q":"UML es:","o":["Un lenguaje de programación estructurado.","Un conjunto de especificaciones que indican cómo construir unos diagramas que sirve para intercambiar información.","Una metodología de desarrollo orientada a objetos.","Un ciclo de vida de desarrollo del software."],"h":["Sus siglas significan Lenguaje de Modelado Unificado.","Es un estándar de modelado visual, no un proceso de desarrollo en sí mismo.","Lo gestiona el Object Management Group (OMG)."],"c":1,"e":"UML es un lenguaje de modelado visual estándar destinado a ser utilizado para el modelado de procesos de negocio y similares, análisis, diseño e implementación de sistemas basados en software. Es un conjunto de especificaciones para diagramas.","d":1,"id":"q065","unit":"UF2406-UD3"},{"q":"Los diagramas de comportamiento:","o":["Muestran el comportamiento dinámico de las clases del sistema.","Muestran cómo se desarrolla un determinado caso de uso.","Muestran el comportamiento dinámico de los objetos del sistema.","Ninguna de las anteriores."],"h":["Se contraponen a los diagramas de estructura.","Describen una serie de cambios en el sistema a lo largo del tiempo.","Ejemplos incluyen diagramas de actividad, de secuencia y de casos de uso."],"c":2,"e":"Los diagramas de comportamiento muestran el comportamiento dinámico de los objetos en un sistema, que puede ser descrito como una serie de cambios en el sistema a lo largo del tiempo.","d":2,"id":"q066","unit":"UF2406-UD3"},{"q":"El diagrama de clases:","o":["Es un diagrama que muestra la estructura del sistema diseñado en el nivel de las clases y las interfaces.","Es un diagrama que muestra los objetos del sistema.","Muestra el comportamiento de un sistema.","Se ajusta a la normativa ISO."],"h":["Es un diagrama de estructura.","Muestra características, limitaciones y relaciones (asociaciones, generalizaciones, dependencias).","Es el más utilizado en el diseño orientado a objetos."],"c":0,"e":"El diagrama de clases es un diagrama UML de estructura que muestra la estructura del sistema diseñado en el nivel de las clases y las interfaces, muestra sus características, estructura y relaciones.","d":1,"id":"q067","unit":"UF2406-UD3"},{"q":"Una clase abstracta:","o":["Es una clase de la que no pueden heredar otras.","Es una clase con solo un objeto asociado.","Es una clase de la que no se pueden crear objetos.","Ninguna es correcta."],"h":["Existe solo para que otras clases hereden de ella.","Su nombre suele representarse en cursiva en los diagramas.","No tiene instanciación directa."],"c":2,"e":"Una clase abstracta se define como una clase que no se puede instanciar (crear objetos) directamente. Existe para que otras clases hereden de ella y apoyen la reutilización de características.","d":2,"id":"q068","unit":"UF2406-UD3"},{"q":"Una operación:","o":["Especifica nombre, tipo, parámetro y restricciones.","Especifica nombre, tipo y parámetros.","Especifica un nombre.","Especifica parámetros in y parámetros out."],"h":["Es una característica del comportamiento de un clasificador.","Se invoca en una instancia del clasificador.","Puede tener efectos secundarios o ser una consulta."],"c":0,"e":"Una operación es una característica del comportamiento de un clasificador que especifica el nombre, tipo, parámetros y limitaciones (restricciones) para invocar un comportamiento asociado.","d":2,"id":"q069","unit":"UF2406-UD3"},{"q":"La visibilidad en UML:","o":["Puede ser pública, de paquete, protegida y privada.","Puede ser pública, protegida y privada.","Se usa solamente en clases.","Se indica en atributos y métodos."],"h":["Se representa con símbolos como +, ~, #, -.","Permite restringir el uso de un elemento llamado.","Aplica a clases, paquetes, generalizaciones, etc."],"c":0,"e":"UML cuenta con los siguientes tipos de visibilidad: pública (+), de paquete (~), protegida (#) y privada (-), que permiten restringir el acceso a los elementos.","d":1,"id":"q070","unit":"UF2406-UD3"},{"q":"Una asociación:","o":["Es una relación entre clasificadores.","Es una relación entre clases.","Es una relación entre objetos.","Es una relación entre casos de uso."],"h":["Muestra que los casos de los clasificadores pueden estar vinculados entre sí.","Puede ser lógica o física.","Se dibuja generalmente como una línea continua."],"c":0,"e":"La asociación es una relación entre clasificadores que se utilizan para mostrar que los casos de los clasificadores pueden ser ya sea vinculados entre sí o combinada lógica o físicamente en alguna agregación.","d":2,"id":"q071","unit":"UF2406-UD3"},{"q":"Un actor en un caso de uso:","o":["Es parte del sistema software modelado.","Representa un elemento externo al sistema.","Solamente se indica mediante un \"hombre de palo\".","Ninguna de las respuestas es correcta."],"h":["Interactúa con el escenario o sistema.","Puede ser un usuario humano, otro sistema o hardware.","Desempeña un rol específico frente al sistema."],"c":1,"e":"Un actor es un clasificador con comportamiento que especifica un papel desempeñado por una entidad externa que interactúa con el escenario (sistema).","d":1,"id":"q072","unit":"UF2406-UD3"},{"q":"Un diagrama de actividad:","o":["Representa la actividad de un actor en el sistema.","Es un diagrama estático.","Es un diagrama de comportamiento.","Modelan la organización a nivel medio."],"h":["Muestra flujo de control o flujo de objetos.","Hace énfasis en la secuencia y las condiciones del flujo.","Se asemeja a un diagrama de flujo tradicional."],"c":2,"e":"El Diagrama de actividad es un diagrama de comportamiento UML que muestra flujo de control o flujo de objetos con énfasis en la secuencia y las condiciones del flujo.","d":2,"id":"q073","unit":"UF2406-UD3"},{"q":"Un mensaje:","o":["Ha de tener una visibilidad pública o privada dependiendo del tipo de clasificador al que apunte.","Sirve para indicar la creación o finalización de un objeto.","Indica la terminación de dos o más líneas de vida.","Es un elemento que define un tipo específico de comunicación entre dos líneas de vida."],"h":["Específica el emisor y el receptor.","Puede ser síncrono, asíncrono, de creación o de respuesta.","Se muestra como una línea con una punta de flecha."],"c":3,"e":"Un mensaje es un elemento con un nombre que define un tipo específico de la comunicación entre líneas de vida de una interacción.","d":2,"id":"q074","unit":"UF2406-UD3"},{"q":"¿Qué nombre reciben las estructuras y datos proporcionados por un SGBD?","o":["Jerárquica.","Modelo de datos.","Base de datos en red.","Sistema de gestión de base de datos."],"h":["Es el conjunto de herramientas conceptuales para describir las relaciones.","Define la semántica y las condiciones de consistencia de los datos.","Existen modelos lógicos basados en objetos, en registros y físicos."],"c":1,"e":"Las estructuras de datos y el acceso proporcionados por un SGBD reciben el nombre de modelo de datos, siendo el relacional el más utilizado actualmente.","d":1,"id":"q075","unit":"UF2405-UD4"},{"q":"¿En cuántas etapas se divide el diseño de una base de datos?","o":["En dos, etapa de diseño conceptual y etapa diseño lógica.","En dos, etapa diseño conceptual y etapa diseño físico.","En tres, etapa conceptual, etapa física y etapa de diseño abstracto.","En tres, etapa conceptual, etapa lógica y etapa diseño físico."],"h":["La primera configura la estructura independientemente de la tecnología.","La segunda transforma el modelo Entidad-Relación a relacional.","La tercera se refiere a los aspectos físicos de implementación en memoria."],"c":3,"e":"El diseño de una base de datos se divide en tres etapas: diseño conceptual (modelo E-R), diseño lógico (modelo relacional) y diseño físico (implementación en memoria secundaria).","d":2,"id":"q076","unit":"UF2405-UD4"},{"q":"¿Qué es una entidad en el modelo Entidad-Relación?","o":["Son las características o propiedades que pueden definir un atributo.","Es la representación de un objeto en el mundo real, que se puede distinguir del resto.","Es la unión entre atributos.","Ninguna de las anteriores es correcta."],"h":["Puede ser algo tangible (como un alumno) o intangible (como una asignatura).","Se representa gráficamente con un rectángulo.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q077","unit":"UF2405-UD4"},{"q":"Un atributo se representa gráficamente con un...","o":["Rombo.","Elipse.","Línea.","Cuadrado."],"h":["Representa las características o propiedades de una entidad.","Se une mediante un guion al rectángulo de la entidad.","Su nombre se escribe en minúsculas dentro de la figura."],"c":1,"e":"En el diagrama Entidad-Relación, los atributos se representan físicamente mediante una elipse con su nombre en minúsculas, unida a la entidad correspondiente.","d":1,"id":"q078","unit":"UF2405-UD4"},{"q":"Para que una entidad sea distinguible del resto será necesario tener un atributo o varios que la identifiquen, estos atributos recibirán el nombre de...","o":["Clave ajena.","Clave foránea.","Clave ajena o foránea.","Clave primaria."],"h":["Garantiza la integridad de la entidad.","No puede contener valores nulos.","Identifica de forma única cada fila o tupla de la tabla."],"c":3,"e":"La clave primaria es el atributo (o conjunto de atributos) que identifica de forma única a cada ocurrencia de una entidad, diferenciándola del resto.","d":2,"id":"q079","unit":"UF2405-UD4"},{"q":"¿Qué significa la cardinalidad de una relación?","o":["Es el tipo de correspondencia que se establecerá entre las entidades de la relación, reflejando el número de ocurrencias.","Es el tipo de correspondencia entre los atributos de la relación.","Es el tipo de correspondencia que no refleja el número de ocurrencias.","Es el tipo de correspondencia que no se establecerá entre las entidades."],"h":["Define cuántas instancias de una entidad se relacionan con otra.","Puede ser 1:1, 1:N o M:N.","Se indica en los extremos de la línea de relación en el diagrama."],"c":0,"e":"La cardinalidad es el tipo de correspondencia que se establece entre las entidades de una relación, reflejando el número de ocurrencias de una entidad con las ocurrencias de la otra.","d":2,"id":"q080","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales del álgebra relacional permitirán la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, diseño conceptual y diseño físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección (filas), Proyección (columnas) y Concatenación o Unión (combinación de tablas).","d":2,"id":"q081","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados en un SGBD según las operaciones que realizan?","o":["Lenguajes de control de datos DCL.","Lenguajes de definición de datos DDL.","Lenguaje de manipulación de datos DML.","A, b y c son correctas."],"h":["Uno define la estructura (CREATE, ALTER).","Otro manipula los datos (SELECT, INSERT).","Otro controla los permisos y accesos (GRANT, REVOKE)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos), entre otros como TCL.","d":1,"id":"q082","unit":"UF2405-UD4"},{"q":"SQL es un lenguaje...","o":["Es un lenguaje no declarativo.","Es un lenguaje declarativo.","Es un lenguaje declarativo y no procedimental.","Es un lenguaje declarativo y procedimental."],"h":["El usuario describe QUÉ quiere obtener, no CÓMO obtenerlo.","No se basa en algoritmos paso a paso.","Está estandarizado por ANSI/ISO."],"c":2,"e":"SQL es un lenguaje declarativo y no procedimental, lo que significa que se basa en describir las condiciones y restricciones de los datos deseados, dejando al SGBD la tarea de determinar cómo ejecutar la consulta.","d":2,"id":"q083","unit":"UF2405-UD4"},{"q":"Las tecnologías más utilizadas para realizar aplicaciones web son:","o":["CGI, ASP, .NET y JSP.",".NET, CGI, JSP, PHP y ASP.",".NET, JSP y PHP.","CGI, JSP y .NET."],"h":["Incluyen lenguajes de script del lado del servidor.","Algunas son de código abierto y otras propietarias.","El texto menciona explícitamente CGI, ASP, .NET, JSP y PHP como el conjunto más utilizado."],"c":1,"e":"Las tecnologías más utilizadas para realizar aplicaciones web incluyen CGI, ASP, .NET, JSP y PHP, cubriendo tanto entornos Microsoft como Java y código abierto.","d":1,"id":"q084","unit":"UF2405-UD5"},{"q":"¿Cuáles son los elementos que forman una base de datos?","o":["El hardware y un software.","El hardware.","El hardware, un software y datos.","Ninguna de las anteriores."],"h":["Necesita dispositivos de almacenamiento físico.","Requiere un SGBD para gestionarla.","Contiene la información estructurada en sí misma."],"c":2,"e":"Una base de datos está compuesta por el hardware (dispositivos de almacenamiento), el software (SGBD) y los datos almacenados de forma estructurada.","d":1,"id":"q085","unit":"UF2405-UD5"},{"q":"¿De qué se ocupa el programador de aplicaciones en el contexto de una base de datos?","o":["Son aquellos que acceden a la información por medio de lenguajes de consulta SQL.","Son aquellos que a través de un lenguaje generan nuevos módulos u objetos capaces de manejar nuevos datos en el sistema.","Son aquellos que utilizan aplicaciones avanzadas para reconocer imágenes.","Son aquellos que interactúan con el SGBD por medio de aplicaciones permanentes."],"h":["Tiene un dominio completo del lenguaje de definición y manipulación.","Crea el software que interactúa con la base de datos.","Desarrolla la lógica de la aplicación."],"c":1,"e":"El programador de aplicaciones es la persona que, mediante un lenguaje de programación, genera módulos u objetos capaces de manejar y procesar los datos del sistema.","d":2,"id":"q086","unit":"UF2405-UD5"},{"q":"La sentencia para conceder permisos de acceso a un usuario es:","o":["GRANT.","SELECT.","REVOKE.","CREATE."],"h":["Pertenece al lenguaje DCL (Data Control Language).","Es el opuesto a denegar o retirar permisos.","Su nombre en inglés significa \"otorgar\"."],"c":0,"e":"La sentencia GRANT se utiliza en SQL para conceder privilegios o permisos de seguridad a un usuario sobre objetos de la base de datos.","d":1,"id":"q087","unit":"UF2405-UD5"},{"q":"¿Cuáles son las operaciones unarias del álgebra relacional?","o":["Unión y diferencia.","Unión, diferencia y producto cartesiano.","Selección y proyección.","Intersección, join y cociente."],"h":["Operan sobre una sola tabla a la vez.","Una filtra filas (tuplas).","La otra filtra columnas (atributos)."],"c":2,"e":"Las operaciones unarias son aquellas que se aplican a una única relación (tabla), siendo la Selección (filtra filas) y la Proyección (filtra columnas) las principales.","d":2,"id":"q088","unit":"UF2405-UD5"},{"q":"La operación de intersección lo que hace es que:","o":["A partir de dos tablas ya existentes dará como resultado una tabla nueva con filas de las dos tablas y columnas de una de ellas.","A partir de dos tablas existentes, se combinan por medio de una condición.","A partir de dos tablas existentes dará como resultado una nueva tabla con las filas que están en una pero no están en la otra.","A partir de dos tablas existentes, dará como resultado una tabla nueva con todas las filas de las dos tablas."],"h":["Es una operación derivada.","Devuelve solo los registros que son comunes a ambas relaciones.","Requiere que las tablas sean compatibles en unión."],"c":0,"e":"La intersección devuelve una tabla nueva que contiene únicamente las filas que existen simultáneamente en ambas tablas originales (y las columnas de una de ellas, al ser compatibles).","d":3,"id":"q089","unit":"UF2405-UD5"},{"q":"Para ejecutar una consulta y obtener datos de una base de datos se utiliza la sentencia:","o":["INSERT.","ALTER.","GRANT.","SELECT."],"h":["Pertenece al lenguaje DQL/DML.","Es la sentencia más compleja y amplia de SQL.","Puede ir acompañada de cláusulas como WHERE, GROUP BY y ORDER BY."],"c":3,"e":"La sentencia SELECT es la instrucción fundamental del lenguaje SQL para recuperar filas o registros de una o varias tablas de una base de datos.","d":1,"id":"q090","unit":"UF2405-UD5"},{"q":"¿Qué determina la cláusula SELECT en una consulta?","o":["Las filas que va a devolver un producto cartesiano.","Las filas que va a devolver una proyección.","Las columnas que va a devolver una consulta.","Las columnas que va a devolver una unión."],"h":["Define la \"lista de selección\".","Puede usar el asterisco (*) para indicar \"todas\".","Determina qué atributos específicos se mostrarán en el resultado."],"c":2,"e":"La cláusula SELECT determina específicamente las columnas (atributos) que van a ser devueltas como resultado de la consulta.","d":1,"id":"q091","unit":"UF2405-UD5"},{"q":"¿Qué tipos de procedimientos almacenados existen en SQL Server?","o":["Del sistema y definidos por el usuario.","Del sistema, definidos por el usuario y extendidos.","Del sistema, definidos por el usuario y remotos.","Del sistema, definidos por el usuario, extendidos y remotos."],"h":["Algunos vienen preinstalados con el SGBD (prefijo sp_).","Otros los crea el desarrollador para tareas específicas.","También existen los que se ejecutan como DLLs externas (xp_) y los que acceden a servidores vinculados."],"c":3,"e":"Existen cuatro tipos principales: procedimientos almacenados del sistema, definidos por el usuario, extendidos (que usan DLLs externas) y remotos (para bases de datos distribuidas).","d":3,"id":"q092","unit":"UF2405-UD5"},{"q":"Una transacción de base de datos es:","o":["Es una unidad de trabajo realizada por una o varias sentencias SQL relacionadas.","Está formada por una serie de instrucciones SQL que definirán un determinado proceso.","Es un programa externo y local.","Es un programa externo."],"h":["Debe cumplir las propiedades ACID.","Se trata de una unidad lógica indivisible.","O se ejecuta por completo o no se ejecuta nada (atomicidad)."],"c":0,"e":"Una transacción es una unidad lógica de trabajo compuesta por una o varias sentencias SQL que deben ejecutarse juntas para mantener la coherencia de los datos.","d":2,"id":"q093","unit":"UF2405-UD5"},{"q":"¿De qué está compuesta una base de datos a nivel lógico?","o":["Por tablas, columnas y tipos de datos.","Por tablas y columnas.","Por tablas.","Ninguna de las anteriores."],"h":["Las tablas son la estructura básica.","Las columnas definen los atributos.","Cada columna tiene un tipo de dato específico que valida la entrada."],"c":0,"e":"Una base de datos relacional está compuesta lógicamente por tablas (relaciones), que a su vez están formadas por columnas (atributos) con tipos de datos definidos.","d":1,"id":"q094","unit":"UF2405-UD6"},{"q":"ANSI recomendó que la estructura de los SGBD tuvieran tres niveles. ¿Cuáles son?","o":["Nivel intermedio, nivel pragmático y nivel interno.","Nivel conceptual, nivel externo y nivel interno o físico.","Esquema conceptual, esquema externo y esquema físico.","B y c son correctas."],"h":["Separa la visión del usuario de la implementación física.","El nivel externo son las vistas de usuario.","El nivel interno es el almacenamiento físico."],"c":3,"e":"ANSI recomendó la arquitectura de tres niveles: conceptual (lógica global), externo (vistas de usuario) e interno o físico (almacenamiento), lo que también se denomina mediante sus esquemas correspondientes.","d":2,"id":"q095","unit":"UF2405-UD6"},{"q":"¿Cuál es el modelo más utilizado y extendido por los desarrolladores para el diseño y análisis de datos?","o":["Entidad.","Entidad-relación.","Relación.","Modelo orientado a objeto."],"h":["Fue propuesto por Peter Chen en los 70.","Utiliza rectángulos, elipses y rombos.","Es la base para luego transformar al modelo relacional."],"c":1,"e":"El modelo Entidad-Relación (E-R) es el más aceptado y extendido para realizar el diseño conceptual y análisis de los datos antes de pasar al modelo relacional.","d":1,"id":"q096","unit":"UF2405-UD6"},{"q":"El lenguaje de definición de datos (DDL) es un lenguaje:","o":["Proporcionado por el SGBD para realizar consultas.","Proporcionado por el SGBD para realizar inserciones.","Proporcionado por el SGBD para realizar borrados.","Proporcionado por el SGBD para permitir que los usuarios creen básicamente estructuras de datos."],"h":["Incluye sentencias como CREATE, ALTER y DROP.","No manipula los datos en sí, sino su contenedor.","Define tablas, vistas, dominios y restricciones."],"c":3,"e":"El DDL (Data Definition Language) es proporcionado por el SGBD y se utiliza específicamente para crear, modificar y eliminar las estructuras de datos (tablas, vistas, etc.), no los datos en sí.","d":1,"id":"q097","unit":"UF2405-UD6"},{"q":"¿Cuáles son las sentencias que componen el lenguaje de definición de datos DDL?","o":["CREATE y ALTER.","CREATE, ALTER y DROP.","CREATE y DROP.","CREATE, ALTER, DROP y TRUNCATE."],"h":["Una crea objetos.","Otra los modifica.","Otras dos eliminan objetos o vacían su contenido por completo."],"c":3,"e":"Las sentencias fundamentales del DDL son CREATE (crear), ALTER (modificar), DROP (eliminar estructura y datos) y TRUNCATE (vaciar datos manteniendo la estructura).","d":1,"id":"q098","unit":"UF2405-UD6"},{"q":"¿Cuál es la modificación estándar que incorporó el estándar ODBC?","o":["CLI-95.","PSM-96.","OLB-98.","SQL 99 o SQL3."],"h":["Es un estándar de SQL/CLI.","Permite acceder desde una aplicación a una base de datos relacional mediante llamadas a funciones.","Sus siglas significan Call Level Interface."],"c":0,"e":"El estándar CLI-95 (Call Level Interface) incorporó y estandarizó las funcionalidades de ODBC para el acceso a bases de datos desde aplicaciones mediante llamadas a funciones.","d":3,"id":"q099","unit":"UF2405-UD6"},{"q":"La sentencia CREATE permitirá la creación de:","o":["Tablas, columnas y restricciones.","Tablas, dominios, restricciones y procedimientos.","Dominios y restricciones.","Tablas, dominios y procedimientos."],"h":["Es la sentencia fundamental de creación del DDL.","Puede crear estructuras de datos como tablas.","También puede crear objetos de lógica como procedimientos almacenados."],"c":1,"e":"La sentencia CREATE es versátil y permite la creación de diversos objetos de la base de datos, incluyendo tablas, vistas, dominios, restricciones y procedimientos almacenados.","d":2,"id":"q100","unit":"UF2405-UD6"},{"q":"¿Qué hace la restricción de integridad de columna por defecto DEFAULT?","o":["Asignar un valor a la columna en función del resultado de la expresión.","No se le asignará ningún valor a la columna.","Asignar el valor de una columna que hace referencia a otra tabla.","Asignar un valor por defecto a una columna asignándole un valor al crearla."],"h":["Se utiliza cuando no se proporciona un valor explícito en un INSERT.","Evita que la columna quede vacía si no se especifica lo contrario.","Se define en la creación de la tabla."],"c":3,"e":"La restricción DEFAULT asigna un valor predeterminado a una columna cuando se crea un nuevo registro y no se especifica un valor para esa columna en la instrucción de inserción.","d":1,"id":"q101","unit":"UF2405-UD6"},{"q":"¿Qué es una vista en una base de datos?","o":["Es un procedimiento almacenado.","Es una tabla derivada de otras tablas, se trata de una tabla virtual, no tiene ninguna correspondencia física.","Es una clase especial de procedimiento almacenado.","Es una tabla normal de una base de datos."],"h":["Se define mediante una sentencia SELECT.","No almacena datos por sí misma (salvo vistas materializadas).","Se utiliza para simplificar consultas o restringir el acceso a ciertos datos."],"c":1,"e":"Una vista es una tabla virtual o derivada que se basa en el resultado de una consulta SELECT. No tiene almacenamiento físico propio, sino que muestra datos de tablas base.","d":2,"id":"q102","unit":"UF2405-UD6"},{"q":"Se distinguen dos tipos de trigger o disparadores:","o":["Trigger DCL y UML.","Trigger DML y DCL.","Trigger DML y DDL.","Trigger DDL y DCL."],"h":["Uno se activa con operaciones de manipulación de datos (INSERT, UPDATE, DELETE).","El otro se activa con operaciones de definición de datos (CREATE, ALTER, DROP)."],"c":2,"e":"SQL distingue entre triggers DML (que responden a cambios en los datos) y triggers DDL (que responden a cambios en la estructura de la base de datos).","d":2,"id":"q103","unit":"UF2405-UD6"},{"q":"Un contenedor de AWT (Abstract Window Toolkit) en Java:","o":["Solo puede albergar componentes y no contenedores.","Es a su vez un componente.","Sirve de almacén de botones.","Se almacena en una clase JComponente."],"h":["La estructura básica de la librería gira en torno a componentes y contenedores.","Los eventos pueden tratarse tanto en contenedores como en componentes.","Ejemplos son Frame, Panel y Window."],"c":1,"e":"En la jerarquía de AWT, los contenedores albergan componentes, pero ellos mismos son considerados componentes, lo que permite anidar contenedores dentro de otros contenedores.","d":2,"id":"q104","unit":"UF2406-UD4"},{"q":"¿Qué es una entidad?","o":["Son las características o propiedades que pueden definir un atributo.","Es la representación de un objeto en el mundo real, que se puede distinguir del resto.","Es la unión entre atributos.","Ninguna de las anteriores es correcta."],"h":["Puede ser algo tangible (como un alumno) o intangible (como una asignatura).","Se representa gráficamente con un rectángulo en un diagrama E-R.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q105","unit":"UF2405-UD4"},{"q":"¿Qué es una relación?","o":["La unión entre distintas entidades.","La unión entre dos entidades.","La unión entre tres entidades.","La unión entre una, dos, tres hasta n-arias."],"h":["Se define como la unión o asociación entre entidades.","Se representa físicamente por medio de un rombo.","Junto al rombo se coloca el nombre de la relación en mayúsculas."],"c":0,"e":"Una relación se define como la unión o asociación entre distintas entidades, pudiendo ser binaria, ternaria o n-aria.","d":1,"id":"q106","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales permitirá la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, diseño conceptual y diseño físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección, Proyección y Concatenación o unión.","d":2,"id":"q107","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados según las operaciones que realizan?","o":["Lenguajes de control de datos DCL.","Lenguajes de definición de datos DDL.","Lenguaje de manipulación de datos DML.","A, b y c son correctas."],"h":["Uno define la estructura (CREATE, ALTER).","Otro manipula los datos (SELECT, INSERT).","Otro controla los permisos y accesos (GRANT, REVOKE)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos), entre otros.","d":1,"id":"q108","unit":"UF2405-UD4"},{"q":"Los factores directos de calidad...","o":["Los que el cliente aprecia de un vistazo.","Uno de ellos es la facilidad de uso.","Son los que se pueden medir directamente sobre el producto.","Ninguna de las anteriores es correcta."],"h":["Se contraponen a los factores indirectos.","Ejemplos incluyen tiempo de ejecución o ocupación de memoria.","Se miden sobre el producto desarrollado, no sobre la percepción del usuario."],"c":2,"e":"Los factores directos son aquellos factores que se pueden medir directamente sobre el producto desarrollado, como el tiempo de ejecución o la ocupación de memoria.","d":1,"id":"q109","unit":"UF2406-UD5"},{"q":"La calidad estructural del software...","o":["Se refiere a la infraestructura que lo soporta.","Se refiere a la forma en que cumple los requisitos funcionales.","Se refiere al modo en que este cumple con los requisitos no funcionales.","Sólo se mide a través de las pruebas."],"h":["Se evalúa analizando el código fuente y la arquitectura.","Incluye robustez y mantenimiento.","La calidad funcional se mide con pruebas, esta se mide con análisis estático."],"c":2,"e":"La calidad estructural se refiere al modo en que el software cumple con los requisitos no funcionales (como robustez o mantenibilidad) y cómo se ha producido correctamente a nivel de arquitectura y código.","d":2,"id":"q110","unit":"UF2406-UD5"},{"q":"La mala calidad de una infraestructura de sistema:","o":["Está correlacionada con el alto impacto que tienen las interrupciones debidas a datos dañados y otros factores.","No afecta al coste de mantenimiento.","Sólo se aplica a sistemas embebidos.","No se aplica en sistemas ERP y CRM."],"h":["Puede causar cortes de aplicación y brechas de seguridad.","Afecta gravemente a los centros de aplicaciones empresariales.","Genera sobrecostos y desperdicio de recursos."],"c":0,"e":"La mala calidad de la infraestructura está fuertemente correlacionada con alto impacto que tienen interrupciones en los negocios debido a datos dañados, cortes de aplicación, brechas de seguridad y problemas de rendimiento.","d":2,"id":"q111","unit":"UF2406-UD5"},{"q":"La fiabilidad:","o":["Sólo se aplica en entornos empresariales.","Es esencial en sistemas de alta velocidad de ejecución.","Es un atributo de resistencia y solidez estructural.","Todas las respuestas son incorrectas."],"h":["Mide el nivel de riesgo y probabilidad de fallos potenciales.","También mide los defectos inyectados por modificaciones.","Su meta es reducir el tiempo de inactividad de las aplicaciones."],"c":2,"e":"La fiabilidad es un atributo de resistencia y solidez estructural que mide el nivel de riesgo y la probabilidad de fallos potenciales de las aplicaciones.","d":2,"id":"q112","unit":"UF2406-UD5"},{"q":"La medición de la calidad del software:","o":["Consiste en cuantificar en qué medida un sistema posee características deseables.","Es realizada exclusivamente por los programadores.","Solamente se aplica en sistemas o proyectos de gran envergadura.","Es una medida de los atributos de código adecuados del sistema."],"h":["Se puede realizar a través de medios cualitativos o cuantitativos.","Para cada característica deseable debe haber atributos medibles.","Es un requisito previo para todas las disciplinas de la ingeniería."],"c":0,"e":"La medición de la calidad del software es cuantificar en qué medida un sistema o software posee características deseables, a través de medios cualitativos, cuantitativos o una mezcla de ambos.","d":1,"id":"q113","unit":"UF2406-UD5"},{"q":"El análisis estructural de calidad y la medición...","o":["Se realizan a través del análisis del código, la arquitectura, plataformas de software y esquemas de bases de datos.","Miden únicamente el esquema de la base de datos.","Se realizan siguiendo los principios de fiabilidad y exhaustividad.","Ninguna de las respuestas es correcta."],"h":["Se realiza en relación a los principios y normas que definen la arquitectura conceptual y lógica.","Es distinto del análisis básico de búsqueda de errores locales.","Evalúa atributos estáticos de calidad."],"c":0,"e":"El análisis estructural de calidad y la medición se realiza a través del análisis del código fuente, la arquitectura, plataforma de software y esquemas de bases de datos en relación a los principios y normas que definen la arquitectura.","d":3,"id":"q114","unit":"UF2406-UD5"},{"q":"La mantenibilidad:","o":["Está relacionada con el concepto de deuda técnica.","Ha de medirse solo en los sistemas empotrados.","Se debe cuidar solo si se prevé que el sistema va a fallar a menudo.","Una baja mantenibilidad siempre tiene su origen en la falta de tiempo."],"h":["Incluye conceptos de modularidad, comprensibilidad y reutilización.","Su baja calidad suele ser resultado de miles de violaciones menores de buenas prácticas.","Es una expresión de los costes derivados de la falta de mantenimiento."],"c":0,"e":"La mantenibilidad está estrechamente relacionada con el concepto de deuda técnica, que es una expresión de los costes derivados de la falta de mantenimiento.","d":2,"id":"q115","unit":"UF2406-UD5"},{"q":"¿Qué atributo NO es de los que deberían tener las métricas de software?","o":["Empíricas e intuitivas.","Simples y sencillas de calcular.","Subjetivas y objetivas.","Consistentes en el empleo de unidades y tamaños."],"h":["Deben producir un resultado no ambiguo.","Deben basarse en el modelo de análisis o diseño.","La subjetividad va en contra de la consistencia y objetividad requerida."],"c":2,"e":"Las métricas deben ser consistentes y objetivas (producir un resultado no ambiguo). La subjetividad no es un atributo deseable en una métrica de software.","d":2,"id":"q116","unit":"UF2406-UD5"},{"q":"Las normas ISO 9000:","o":["Determinan como se deben formar a los programadores en un entorno de calidad.","Indican los documentos de calidad que debe generar una organización.","Establecen los requisitos de un sistema de control de calidad.","Indican como deben hacerse las mediciones de calidad del software."],"h":["Son un grupo de estándares internacionales de administración y aseguramiento de calidad.","Son genéricas, no específicas para un producto.","Documentan qué elementos usar para mantener un sistema eficiente."],"c":2,"e":"La serie de normas ISO-9000 establece los requisitos básicos que debe de cumplir un sistema de control que garantice productos o servicios de calidad consistente.","d":1,"id":"q117","unit":"UF2406-UD5"},{"q":"El modelo de madurez del software CMM:","o":["Indica como cumple la normativa ISO una organización.","Detalla las tareas que se tienen que realizar conforme a la calidad.","Sirve de referencia para indicar el estado de I+D de una empresa.","Detalla cinco niveles inclusivos para determinar la madurez del proceso de desarrollo de una organización."],"h":["Sus siglas son Software Capability Maturity Model.","Los niveles son: Inicial, Repetible, Definido, Gestionado y Optimizado.","Para alcanzar un nivel, se deben haber logrado y mantenido todos los anteriores."],"c":3,"e":"En el Modelo de Madurez de la Capacidad del Software (SW-CMM) se detallan áreas clave del proceso agrupadas en cinco niveles inclusivos para determinar el estado de la madurez del proceso de desarrollo.","d":2,"id":"q118","unit":"UF2406-UD5"},{"q":"Sobre las pruebas de integración:","o":["Sólo se usan pruebas de caja blanca.","Un resguardo simula un subprograma subordinado.","Un controlador simula un subprograma subordinado.","Sólo se usan pruebas de caja negra."],"h":["Es una técnica sistemática para construir la estructura del programa.","Detecta errores asociados con la interacción entre módulos.","El controlador simula el módulo superior, no el subordinado."],"c":1,"e":"Los resguardos sirven para reemplazar módulos que están subordinados (es decir, son llamados) al componente que hay que probar durante las pruebas de integración.","d":2,"id":"q119","unit":"UF2406-UD6"},{"q":"Sobre las pruebas de validación:","o":["Sirven para detectar errores de compilación.","La prueba beta se lleva a cabo por clientes en el lugar de desarrollo.","La prueba alfa se lleva a cabo por un cliente en el lugar de desarrollo.","Se prueban exhaustivamente cada clase antes de integrarla."],"h":["Se consigue cuando el software funciona según las expectativas razonables del cliente.","La prueba beta es en el lugar de trabajo del cliente, sin el desarrollador.","La prueba alfa es en el lugar de desarrollo, con el desarrollador como observador."],"c":2,"e":"La prueba alfa se lleva a cabo por un cliente, en el lugar de desarrollo, usando el software de forma natural con el desarrollador como observador del usuario.","d":1,"id":"q120","unit":"UF2406-UD6"},{"q":"Sobre la prueba del camino básico:","o":["Utiliza la complejidad ciclomática.","Es un método de caja negra.","Se han de ejecutar cada ruta del programa dos veces.","Se han de probar la mitad de los nodos predicado al menos."],"h":["Es una técnica de prueba de caja blanca propuesta por Tom McCabe.","Permite obtener una medida de la complejidad lógica de un programa.","Garantiza que se ejecuta por lo menos una vez cada sentencia."],"c":0,"e":"La prueba del camino básico utiliza la complejidad ciclomática, que proporciona una medición cuantitativa de la complejidad lógica y define el número de caminos independientes del conjunto básico.","d":2,"id":"q121","unit":"UF2406-UD6"},{"q":"Sobre las pruebas de bucles:","o":["Se prueba el límite superior del bucle.","Los bucles simples se prueban una vez.","Con los bucles anidados se usa una estrategia diferente que con los bucles simples.","Se prueba el límite inferior del bucle."],"h":["Se centra exclusivamente en la validez de las construcciones de bucles.","Extender el enfoque de bucles simples a anidados aumentaría las pruebas geométricamente.","Se comienza por el bucle más interior manteniendo los externos en valores mínimos."],"c":2,"e":"Con los bucles anidados se usa una estrategia diferente (comenzando por el más interior y manteniendo los externos en valores mínimos) para evitar un número impracticable de pruebas.","d":2,"id":"q122","unit":"UF2406-UD6"},{"q":"La depuración de programas es el proceso por el que:","o":["Se identifican y corrigen errores de programación en dicho programa.","Se identifican fallos en dicho programa.","Se identifican fallos de compilación en dicho programa.","Ninguna respuesta es válida."],"h":["También se le conoce como debugging.","Implica descubrir errores e identificar qué zonas del programa los producen.","Se utiliza un depurador para ejecutar el programa línea a línea o paso a paso."],"c":0,"e":"La depuración de programas es el proceso por el cual se identifican y corrigen errores de programación, descubriendo qué zonas del programa los producen.","d":1,"id":"q123","unit":"UF2406-UD6"},{"q":"Si se tienen varias pruebas JUnit:","o":["Se pueden combinar en un conjunto de pruebas.","Siempre han de ejecutarse manualmente una a una.","JUNIT no permite más de una prueba a la vez.","Siempre se ejecutan en el mismo orden."],"h":["Se utiliza la anotación @RunWith(Suite.class).","Permite ejecutar todas las clases de prueba en esa suite en el orden especificado.","Facilita la organización de pruebas complejas."],"c":0,"e":"Si se tienen varias clases de prueba, se pueden combinar en un conjunto de pruebas (Suite). La ejecución de un conjunto de pruebas ejecutará todas las clases de prueba en esa suite en el orden especificado.","d":2,"id":"q124","unit":"UF2406-UD6"},{"q":"En la ejecución de un caso de pruebas:","o":["Nunca se deben de automatizar su ejecución.","Hay dos métodos, manual y automatizado.","Se puede obviar el formato de JUnit.","Se tienen que indicar si es una prueba de integración."],"h":["Dependiendo de la naturaleza de la prueba, se suele usar una combinación de ambos.","La automatización es útil para pruebas de regresión.","La manual permite detectar errores no previstos por los scripts."],"c":1,"e":"Hay dos métodos utilizados en la ejecución de casos de prueba: manuales y automatizados. Dependiendo de la naturaleza de la prueba, una combinación de ambos suele ser el mejor método.","d":1,"id":"q125","unit":"UF2406-UD6"},{"q":"Idealmente el software:","o":["Debe pasar al menos el 50% de las pruebas.","Debe de satisfacer la mitad de los requisitos.","Debe satisfacer todos los requisitos.","Debe de liberarse cuanto antes para que el usuario detecte los errores lo antes posible."],"h":["Desde el diseño, cada requisito debe abordarse en cada documento único.","La matriz de trazabilidad ayuda a verificar esto.","Si hay celdas vacías en la matriz, un requisito no se ha abordado correctamente."],"c":2,"e":"Idealmente, el software debe satisfacer por completo el conjunto de requisitos. Desde el diseño, cada requisito debe abordarse en cada documento único en el proceso de software.","d":1,"id":"q126","unit":"UF2406-UD6"},{"q":"El estándar IEEE 829-2008:","o":["Especifica como realizar las pruebas de software.","Especifica como realizar pruebas de caja blanca.","Especifica como realizar pruebas de caja negra.","Especifica como debe ser la documentación de pruebas."],"h":["También conocido como el Estándar para la Documentación del software de pruebas.","Especifica la forma de un conjunto de documentos para su uso en etapas definidas.","Incluye plan de pruebas, casos de prueba e informes de resultados."],"c":3,"e":"El IEEE 829-2008 es un documento estándar que especifica la forma de un conjunto de documentos para su uso en etapas definidas de pruebas de software, estableciendo una estructura determinada para la documentación.","d":2,"id":"q127","unit":"UF2406-UD6"},{"q":"Enunciado: Los factores directos de calidad...","o":["Los que el cliente aprecia de un vistazo.","Uno de ellos es la facilidad de uso.","Son los que se pueden medir directamente sobre el producto.","Ninguna de las anteriores es correcta."],"h":["Se contraponen a los factores indirectos.","Ejemplos incluyen el tiempo de ejecución u ocupación de memoria.","No dependen de la apreciación subjetiva del usuario final."],"c":2,"e":"Los factores directos son aquellos que se pueden medir directamente sobre el producto desarrollado, como el tiempo de ejecución, tiempo de respuesta u ocupación de memoria.","d":1,"id":"q128","unit":"UF2406-UD5"},{"q":"Enunciado: La calidad estructural del software...","o":["Se refiere a la infraestructura que lo soporta.","Se refiere a la forma en que cumple los requisitos funcionales.","Se refiere al modo en que este cumple con los requisitos no funcionales.","Sólo se mide a través de las pruebas."],"h":["Se evalúa analizando el código fuente y la arquitectura.","Se relaciona con requisitos no funcionales como la robustez o mantenibilidad.","Se contrapone a la calidad funcional, que se mide con pruebas."],"c":2,"e":"La calidad estructural se refiere al modo en que el software cumple con los requisitos no funcionales y al grado en que el software se ha producido correctamente a nivel de arquitectura y código.","d":2,"id":"q129","unit":"UF2406-UD5"},{"q":"Enunciado: La mala calidad de una infraestructura de sistema:","o":["Está correlacionada con el alto impacto que tienen las interrupciones debidas a datos dañados y otros factores.","No afecta al coste de mantenimiento.","Sólo se aplica a sistemas embebidos.","No se aplica en sistemas ERP y CRM."],"h":["Afecta gravemente a los centros de aplicaciones empresariales.","Provoca sobrecostos y desperdicio de recursos (hasta un 45% del tiempo de desarrollo).","Está fuertemente ligada a brechas de seguridad y cortes de aplicación."],"c":0,"e":"Estudios demuestran que la mala calidad de la infraestructura está fuertemente correlacionada con el alto impacto de las interrupciones en los negocios debido a datos dañados, cortes de aplicación y problemas de rendimiento.","d":2,"id":"q130","unit":"UF2406-UD5"},{"q":"Enunciado: La fiabilidad:","o":["Sólo se aplica en entornos empresariales.","Es esencial en sistemas de alta velocidad de ejecución.","Es un atributo de resistencia y solidez estructural.","Todas las respuestas son incorrectas."],"h":["Mide el nivel de riesgo y la probabilidad de fallos potenciales.","También mide los defectos inyectados debido a las modificaciones.","Su meta es reducir y prevenir el tiempo de inactividad de las aplicaciones."],"c":2,"e":"La fiabilidad es un atributo de resistencia y solidez estructural que mide el nivel de riesgo y la probabilidad de fallos potenciales de las aplicaciones.","d":2,"id":"q131","unit":"UF2406-UD5"},{"q":"Enunciado: La medición de la calidad del software:","o":["Consiste en cuantificar en qué medida un sistema posee características deseables.","Es realizada exclusivamente por los programadores.","Solamente se aplica en sistemas o proyectos de gran envergadura.","Es una medida de los atributos de código adecuados del sistema."],"h":["Se puede realizar a través de medios cualitativos, cuantitativos o una mezcla de ambos.","Para cada característica deseable debe haber atributos medibles.","Es un requisito previo para todas las disciplinas de la ingeniería."],"c":0,"e":"La medición de la calidad del software es cuantificar en qué medida un sistema o software posee características deseables, a través de medios cualitativos, cuantitativos o una mezcla de ambos.","d":1,"id":"q132","unit":"UF2406-UD5"},{"q":"Enunciado: El análisis estructural de calidad y la medición...","o":["Se realizan a través del análisis del código, la arquitectura, plataformas de software y esquemas de bases de datos.","Miden únicamente el esquema de la base de datos.","Se realizan siguiendo los principios de fiabilidad y exhaustividad.","Ninguna de las respuestas es correcta."],"h":["Se realiza en relación a los principios y normas que definen la arquitectura conceptual y lógica.","Es distinto del análisis básico de búsqueda de errores locales.","Evalúa atributos estáticos de calidad."],"c":0,"e":"El análisis estructural de calidad y la medición se realiza a través del análisis del código fuente, la arquitectura, plataforma de software y esquemas de bases de datos en relación a los principios y normas establecidos.","d":3,"id":"q133","unit":"UF2406-UD5"},{"q":"Enunciado: La mantenibilidad:","o":["Está relacionada con el concepto de deuda técnica.","Ha de medirse solo en los sistemas empotrados.","Se debe cuidar solo si se prevé que el sistema va a fallar a menudo.","Una baja mantenibilidad siempre tiene su origen en la falta de tiempo."],"h":["Incluye conceptos de modularidad, comprensibilidad y reutilización.","Es una expresión de los costes derivados de la falta de mantenimiento.","Suele ser resultado de miles de violaciones menores de buenas prácticas."],"c":0,"e":"La mantenibilidad está estrechamente relacionada con el concepto de deuda técnica, que es una expresión de los costes derivados de la falta de mantenimiento.","d":2,"id":"q134","unit":"UF2406-UD5"},{"q":"Enunciado: ¿Qué atributo NO es de los que deberían tener las métricas de software?","o":["Empíricas e intuitivas.","Simples y sencillas de calcular.","Subjetivas y objetivas.","Consistentes en el empleo de unidades y tamaños."],"h":["Deben producir un resultado no ambiguo.","Deben basarse en el modelo de análisis o diseño.","La subjetividad va en contra de la consistencia y objetividad requerida."],"c":2,"e":"Las métricas deben ser consistentes y objetivas (producir un resultado no ambiguo). La subjetividad no es un atributo deseable en una métrica de software.","d":2,"id":"q135","unit":"UF2406-UD5"},{"q":"Enunciado: Las normas ISO 9000:","o":["Determinan cómo se deben formar a los programadores en un entorno de calidad.","Indican los documentos de calidad que debe generar una organización.","Establecen los requisitos de un sistema de control de calidad.","Indican cómo deben hacerse las mediciones de calidad del software."],"h":["Son un grupo de estándares internacionales de administración.","Son genéricas, no específicas para un producto.","Documentan qué elementos usar para mantener un sistema eficiente de calidad en la empresa."],"c":2,"e":"La serie de normas ISO-9000 establece los requisitos básicos que debe de cumplir un sistema de control que garantice productos o servicios de calidad consistente.","d":1,"id":"q136","unit":"UF2406-UD5"},{"q":"Enunciado: El modelo de madurez del software CMM:","o":["Indica cómo cumple la normativa ISO una organización.","Detalla las tareas que se tienen que realizar conforme a la calidad.","Sirve de referencia para indicar el estado de I+D de una empresa.","Detalla cinco niveles inclusivos para determinar la madurez del proceso de desarrollo de una organización."],"h":["Sus siglas son Software Capability Maturity Model.","Los niveles son: Inicial, Repetible, Definido, Gestionado y Optimizado.","Para alcanzar un nivel, se deben haber logrado y mantenido todos los anteriores."],"c":3,"e":"En el Modelo de Madurez de la Capacidad del Software (SW-CMM) se detallan áreas clave del proceso agrupadas en cinco niveles inclusivos para determinar el estado de la madurez del proceso de desarrollo.","d":2,"id":"q137","unit":"UF2406-UD5"},{"q":"Enunciado: Sobre las pruebas de integración:","o":["Sólo se usan pruebas de caja blanca.","Un resguardo simula un subprograma subordinado.","Un controlador simula un subprograma subordinado.","Sólo se usan pruebas de caja negra."],"h":["Es una técnica sistemática para construir la estructura del programa.","Detecta errores asociados con la interacción entre módulos.","El controlador simula el módulo superior, no el subordinado."],"c":1,"e":"Los resguardos (stubs) sirven para reemplazar módulos que están subordinados (es decir, son llamados) al componente que hay que probar durante las pruebas de integración.","d":2,"id":"q138","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre las pruebas de validación:","o":["Sirven para detectar errores de compilación.","La prueba beta se lleva a cabo por clientes en el lugar de desarrollo.","La prueba alfa se lleva a cabo por un cliente en el lugar de desarrollo.","Se prueban exhaustivamente cada clase antes de integrarla."],"h":["Se consigue cuando el software funciona según las expectativas razonables del cliente.","La prueba beta es en el lugar de trabajo del cliente, sin el desarrollador.","La prueba alfa es en el lugar de desarrollo, con el desarrollador como observador."],"c":2,"e":"La prueba alfa se lleva a cabo por un cliente, en el lugar de desarrollo, usando el software de forma natural con el desarrollador como observador del usuario y registrando los errores.","d":1,"id":"q139","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre la prueba del camino básico:","o":["Utiliza la complejidad ciclomática.","Es un método de caja negra.","Se han de ejecutar cada ruta del programa dos veces.","Se han de probar la mitad de los nodos predicado al menos."],"h":["Es una técnica de prueba de caja blanca propuesta por Tom McCabe.","Permite obtener una medida de la complejidad lógica de un programa.","Garantiza que se ejecuta por lo menos una vez cada sentencia del programa."],"c":0,"e":"La prueba del camino básico utiliza la complejidad ciclomática, que proporciona una medición cuantitativa de la complejidad lógica y define el número de caminos independientes del conjunto básico.","d":2,"id":"q140","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre las pruebas de bucles:","o":["Se prueba el límite superior del bucle.","Los bucles simples se prueban una vez.","Con los bucles anidados se usa una estrategia diferente que con los bucles simples.","Se prueba el límite inferior del bucle."],"h":["Se centra exclusivamente en la validez de las construcciones de bucles.","Extender el enfoque de bucles simples a anidados aumentaría las pruebas geométricamente.","Se comienza por el bucle más interior manteniendo los externos en valores mínimos."],"c":2,"e":"Con los bucles anidados se usa una estrategia diferente (comenzando por el más interior y manteniendo los externos en sus valores mínimos) para evitar un número impracticable de pruebas.","d":2,"id":"q141","unit":"UF2406-UD6"},{"q":"Enunciado: La depuración de programas es el proceso por el que:","o":["Se identifican y corrigen errores de programación en dicho programa.","Se identifican fallos en dicho programa.","Se identifican fallos de compilación en dicho programa.","Ninguna respuesta es válida."],"h":["También se le conoce como debugging.","Implica descubrir errores e identificar qué zonas del programa los producen.","Se utiliza un depurador para ejecutar el programa línea a línea o paso a paso."],"c":0,"e":"La depuración de programas es el proceso por el cual se identifican y corrigen errores de programación, descubriendo qué zonas del programa los producen.","d":1,"id":"q142","unit":"UF2406-UD6"},{"q":"Enunciado: Si se tienen varias pruebas JUnit:","o":["Se pueden combinar en un conjunto de pruebas.","Siempre han de ejecutarse manualmente una a una.","JUnit no permite más de una prueba a la vez.","Siempre se ejecutan en el mismo orden."],"h":["Se utiliza la anotación @RunWith(Suite.class).","Permite ejecutar todas las clases de prueba en esa suite en el orden especificado.","Facilita la organización de pruebas complejas."],"c":0,"e":"Si se tienen varias clases de prueba, se pueden combinar en un conjunto de pruebas (Suite). La ejecución de un conjunto de pruebas ejecutará todas las clases de prueba en esa suite en el orden especificado.","d":2,"id":"q143","unit":"UF2406-UD6"},{"q":"Enunciado: En la ejecución de un caso de pruebas:","o":["Nunca se deben de automatizar su ejecución.","Hay dos métodos, manual y automatizado.","Se puede obviar el formato de JUnit.","Se tienen que indicar si es una prueba de integración."],"h":["Dependiendo de la naturaleza de la prueba, se suele usar una combinación de ambos.","La automatización es útil para pruebas de regresión.","La prueba manual permite detectar errores no previstos por los scripts."],"c":1,"e":"Hay dos métodos utilizados en la ejecución de casos de prueba: manuales y automatizados. Dependiendo de la naturaleza de la prueba, una combinación de ambos suele ser el mejor método.","d":1,"id":"q144","unit":"UF2406-UD6"},{"q":"Enunciado: Un script de prueba en las pruebas de software es:","o":["Un documento que detalla un enfoque sistemático.","Un conjunto de instrucciones que se van a ejecutar en el sistema sometido a prueba.","Un programa que solo se ejecuta manualmente.","Una herramienta de gestión de configuración."],"h":["Puede ser manual o automatizado.","En la automatización, es un corto programa escrito en un lenguaje de programación.","Su objetivo es comprobar que el sistema funciona como se esperaba."],"c":1,"e":"Un script de prueba es un conjunto de instrucciones (o un corto programa) que se ejecuta en el sistema sometido a prueba para comprobar que su funcionalidad es la esperada.","d":1,"id":"q145","unit":"UF2406-UD6"},{"q":"Enunciado: Idealmente el software:","o":["Debe pasar al menos el 50% de las pruebas.","Debe de satisfacer la mitad de los requisitos.","Debe satisfacer todos los requisitos.","Debe de liberarse cuanto antes para que el usuario detecte los errores lo antes posible."],"h":["Desde el diseño, cada requisito debe abordarse en cada documento único.","La matriz de trazabilidad ayuda a verificar esto.","Si hay celdas vacías en la matriz, un requisito no se ha abordado correctamente."],"c":2,"e":"Idealmente, el software debe satisfacer por completo el conjunto de requisitos. Desde el diseño, cada requisito debe abordarse en cada documento único en el proceso de software.","d":1,"id":"q146","unit":"UF2406-UD6"},{"q":"Enunciado: El estándar IEEE 829-2008:","o":["Especifica cómo realizar las pruebas de software.","Especifica cómo realizar pruebas de caja blanca.","Especifica cómo realizar pruebas de caja negra.","Especifica cómo debe ser la documentación de pruebas."],"h":["También conocido como el Estándar para la Documentación del software de pruebas.","Especifica la forma de un conjunto de documentos para su uso en etapas definidas.","Incluye plan de pruebas, casos de prueba e informes de resultados."],"c":3,"e":"El IEEE 829-2008 es un documento estándar que especifica la forma de un conjunto de documentos para su uso en etapas definidas de pruebas de software, estableciendo una estructura determinada para la documentación.","d":2,"id":"q147","unit":"UF2406-UD6"},{"q":"Enunciado: Un programa perfectamente compilado:","o":["Generalmente no va a ocasionar ningún problema.","NUNCA puede tener un error ya que se ha compilado perfectamente sin errores.","Puede generar otros errores cuando se ejecuta.","Ninguna de las anteriores es correcta."],"h":["Puede no tener errores de sintaxis.","Puede generar errores en tiempo de ejecución.","A estos errores se les conoce como excepciones."],"c":2,"e":"Un programa perfectamente compilado en el que no existen errores de sintaxis, puede generar otros tipos de errores que pueden aparecer en tiempo de ejecución. A estos errores se les conoce como excepciones.","d":1,"id":"q148","unit":"UF2406-UD7"},{"q":"Enunciado: Una excepción es:","o":["Una instrucción de Java.","Una clase de Java que hereda de Error.","Un evento que se produce durante la ejecución de un programa que interrumpe su flujo normal de instrucciones.","Una clase de Java incorporada al paquete IOException."],"h":["El término es abreviatura de \"caso excepcional\".","Cuando ocurre, el método crea un objeto y lo entrega al sistema de tiempo de ejecución.","Contiene información sobre el error, incluyendo su tipo y el estado del programa."],"c":2,"e":"Una excepción es un evento que se produce durante la ejecución de un programa, que interrumpe el flujo normal de las instrucciones del programa.","d":1,"id":"q149","unit":"UF2406-UD7"},{"q":"Enunciado: Las tres clases de excepciones que hay son:","o":["Las excepciones comprobadas, las no comprobadas y los errores.","Los errores y las excepciones propiamente dichas.","Las Throwable y las IOException.","Solo hay una clase de excepciones en Java."],"h":["Una es la que el programador debe verificar (checked).","Otra son condiciones externas que la aplicación no puede anticipar (Error).","La tercera son condiciones internas, como errores lógicos (RuntimeException)."],"c":0,"e":"Las tres clases de excepciones que hay en Java son excepciones comprobadas, errores y excepciones en tiempo de ejecución (no comprobadas).","d":2,"id":"q150","unit":"UF2406-UD7"},{"q":"Enunciado: Las excepciones se capturan...","o":["Con la sentencia throw.","Mediante un bloque finally{...}.","Mediante un bloque try{...} catch{...}.","Con la sentencia throws."],"h":["Se utiliza una estructura de control específica.","El bloque que la contiene es \"try\".","El bloque que la maneja es \"catch\"."],"c":2,"e":"Para poder capturar excepciones, emplearemos la estructura de captura de excepciones try-catch-finally. El bloque catch contiene el código que se ejecuta cuando se invoca el controlador de excepciones.","d":1,"id":"q151","unit":"UF2406-UD7"},{"q":"Enunciado: Las excepciones se lanzan...","o":["Con la sentencia throw.","Mediante un bloque finally{...}.","Mediante un bloque try{...} catch{...}.","Con la sentencia throws."],"h":["Se utiliza una palabra clave específica en Java.","Esta palabra clave es \"throw\".","No debe confundirse con \"throws\", que se usa en la firma del método para declarar que puede lanzar una excepción."],"c":0,"e":"El hecho de que se produzca la creación de un objeto de excepción y entregarla al sistema de tiempo de ejecución se llama lanzar una excepción, y se realiza con la sentencia throw.","d":1,"id":"q152","unit":"UF2406-UD7"},{"q":"Enunciado: El bloque finally...","o":["Es una herramienta clave para la prevención de pérdida de recursos.","Es obligatorio incluirlo.","Se coloca antes del try.","Ninguna de las respuestas es correcta."],"h":["Siempre se ejecuta al salir del bloque try.","Es útil para código de limpieza.","Permite cerrar archivos o liberar recursos aunque se produzca una excepción."],"c":0,"e":"El bloque finally es una herramienta clave para la prevención de pérdidas de recursos. Siempre hay que cerrar un archivo o de lo contrario se pueden ocupar recursos y bloquear estos.","d":2,"id":"q153","unit":"UF2406-UD7"},{"q":"Enunciado: La principal ventaja de las excepciones es:","o":["Separa el código normal del código de detección y recuperación de errores.","Que el código es código espagueti.","Un método debe recuperarse de los errores que genere.","Solo se usa en lenguaje C."],"h":["Evita el \"código espagueti\".","Organiza el trabajo de manera más eficaz.","Permite escribir el flujo principal del código y trabajar con los casos excepcionales en otras partes."],"c":0,"e":"La principal ventaja de las excepciones es separar el código de manejo de errores del código \"normal\", evitando que la detección de errores, la presentación de la información y el proceso de datos conduzcan a un \"código espagueti\" confuso.","d":2,"id":"q154","unit":"UF2406-UD7"},{"q":"Enunciado: Un método puede re-lanzar una excepción...","o":["No, nunca.","De hecho siempre deben re-lanzarse las excepciones.","Y así la puede capturar otro método que esté en la parte superior de la pila.","Solamente las que están por debajo en la jerarquía de IOException."],"h":["Permite que la excepción suba en la pila de llamadas.","Un método superior en la pila puede atraparla.","Esto evita que los métodos intermedios tengan que manejar errores que no les incumben."],"c":2,"e":"Un método puede re-lanzar una excepción lanzada dentro de él, lo que permite que un método que esté más arriba en la pila de llamadas pueda atraparla y manejarla.","d":2,"id":"q155","unit":"UF2406-UD7"},{"q":"Enunciado: ¿Se puede incluir información relevante en un objeto de excepción?","o":["No es recomendable trabajar así.","Solamente las excepciones que se van a re-lanzar.","Sí, una excepción puede incluir información en el objeto asociado.","Las excepciones solo se pueden capturar, y no se usan para transmitir información."],"h":["Una excepción es realmente un objeto con todas sus características.","El programador puede incluir información sobre el error.","Se puede obtener dicha información solicitándola al objeto en el catch."],"c":2,"e":"Debido a que una excepción es realmente un objeto, el programador puede incluir toda la información que desee en ese objeto (como un mensaje o un código de error) y obtenerla en el bloque catch.","d":2,"id":"q156","unit":"UF2406-UD7"},{"q":"Enunciado: La información que se incluya en un objeto excepción puede ser:","o":["No se puede incluir información en un objeto excepción.","Solamente cadenas de texto.","Solamente un código de error numérico.","No solamente cadenas, sino de cualquier tipo válido."],"h":["No se limita a cadenas de texto.","Se pueden agregar métodos necesarios a la clase que implementa la excepción.","Por ejemplo, se puede almacenar y recuperar un valor de temperatura o un objeto específico."],"c":3,"e":"Se puede añadir más información que simplemente una cadena; basta con agregar los métodos necesarios a la clase que implementa la excepción para almacenar y recuperar cualquier tipo de dato válido.","d":3,"id":"q157","unit":"UF2406-UD7"},{"q":"¿En cuántas etapas se divide el diseño de una base de datos?","o":["En dos: conceptual y lógica.","En dos: conceptual y física.","En tres: conceptual, lógica y física.","En cuatro: análisis, diseño, implementación y pruebas."],"h":["La primera es independiente de la tecnología.","La segunda transforma el modelo E-R a relacional.","La tercera se refiere a la implementación en memoria secundaria."],"c":2,"e":"El diseño de una base de datos se divide en tres etapas: diseño conceptual, diseño lógico y diseño físico.","d":1,"id":"q158","unit":"UF2405-UD4"},{"q":"¿Qué es una entidad en el modelo Entidad-Relación?","o":["Son las características que definen un atributo.","Es la representación de un objeto en el mundo real, distinguible del resto.","Es la unión entre atributos.","Ninguna de las anteriores."],"h":["Puede ser tangible (alumno) o intangible (asignatura).","Se representa gráficamente con un rectángulo.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q159","unit":"UF2405-UD4"},{"q":"Para que una entidad sea distinguible del resto será necesario tener un atributo o varios que la identifiquen, estos atributos recibirán el nombre de...","o":["Clave ajena.","Clave foránea.","Clave candidata.","Clave primaria."],"h":["Garantiza la integridad de la entidad.","No puede contener valores nulos.","Identifica de forma única cada tupla o fila de la tabla."],"c":3,"e":"La clave primaria es el atributo (o conjunto de atributos) que identifica de forma única a cada ocurrencia de una entidad, diferenciándola del resto.","d":2,"id":"q160","unit":"UF2405-UD4"},{"q":"¿Qué significa la cardinalidad de una relación?","o":["Es el tipo de correspondencia que se establecerá entre las entidades, reflejando el número de ocurrencias.","Es la correspondencia entre atributos.","No refleja el número de ocurrencias.","Es el tipo de correspondencia que no se establecerá."],"h":["Define cuántas instancias de una entidad se relacionan con otra.","Puede ser 1:1, 1:N o M:N.","Se indica en los extremos de la línea de relación en el diagrama."],"c":0,"e":"La cardinalidad es el tipo de correspondencia que se establecerá entre las entidades de la relación, reflejando el número de ocurrencias de una entidad con las ocurrencias de la otra entidad con la que existe una asociación.","d":2,"id":"q161","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales del álgebra relacional permitirán la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, conceptual y físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección, Proyección y Concatenación o unión.","d":2,"id":"q162","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados según las operaciones que realizan en un SGBD?","o":["Solo DCL.","Solo DDL.","Solo DML.","DCL, DDL y DML."],"h":["Uno define la estructura (CREATE).","Otro manipula los datos (SELECT).","Otro controla los permisos y accesos (GRANT)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican principalmente en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos).","d":1,"id":"q163","unit":"UF2405-UD4"},{"q":"SQL es un lenguaje...","o":["No declarativo.","Declarativo.","Declarativo y no procedimental.","Declarativo y procedimental."],"h":["El usuario describe QUÉ quiere obtener, no CÓMO obtenerlo.","No se basa en algoritmos paso a paso.","Está estandarizado por ANSI/ISO."],"c":2,"e":"SQL es un lenguaje declarativo y no procedimental, lo que significa que se basa en describir las condiciones y restricciones de los datos deseados, dejando al SGBD la tarea de determinar cómo ejecutar la consulta.","d":2,"id":"q164","unit":"UF2405-UD4"},{"q":"¿Qué es el lenguaje de manipulación de datos (DML)?","o":["Creación de estructuras de datos.","Consulta y modificación de datos.","Control de acceso a la base de datos.","Definición de datos."],"h":["Incluye sentencias como SELECT, INSERT, UPDATE, DELETE.","Permite a los usuarios interactuar con la información almacenada.","No se usa para crear tablas, sino para manejar su contenido."],"c":1,"e":"El DML (Data Manipulation Language) es el lenguaje mediante el cual uno o varios usuarios pueden realizar operaciones de consulta, modificación y eliminación de los datos contenidos en una base de datos.","d":1,"id":"q165","unit":"UF2405-UD7"},{"q":"Las sentencias que forman el lenguaje DML son:","o":["CREATE, ALTER, DROP.","GRANT, REVOKE.","SELECT, INSERT, UPDATE, DELETE.","COMMIT, ROLLBACK."],"h":["Son las operaciones básicas sobre los registros.","Permiten leer, añadir, cambiar y borrar información.","No definen la estructura, solo la manipulan."],"c":2,"e":"Los elementos que conforman el lenguaje DML son las sentencias SELECT (consulta), INSERT (inserción), UPDATE (modificación) y DELETE (eliminación).","d":1,"id":"q166","unit":"UF2405-UD7"},{"q":"¿Qué sentencia se utiliza para insertar datos en una tabla?","o":["UPDATE.","DELETE.","INSERT.","DROP."],"h":["Añade nuevas filas a una tabla existente.","Utiliza la cláusula VALUES para especificar los datos.","Es la operación opuesta a borrar."],"c":2,"e":"La sentencia INSERT se utiliza para introducir datos en una o varias filas de una tabla de una base de datos.","d":1,"id":"q167","unit":"UF2405-UD7"},{"q":"La sentencia UPDATE se utiliza para...","o":["Insertar una fila.","Modificar y actualizar datos de una o varias filas de una tabla.","Eliminar una tabla.","Crear una vista."],"h":["Cambia el valor de uno o varios atributos.","Suele ir acompañada de la cláusula WHERE para filtrar qué filas se modifican.","No añade filas nuevas, solo altera las existentes."],"c":1,"e":"La sentencia UPDATE se utiliza para modificar o actualizar datos de una o varias filas de una única tabla de una base de datos.","d":1,"id":"q168","unit":"UF2405-UD7"},{"q":"Para eliminar toda la definición de una tabla (estructura y datos) se utiliza la sentencia:","o":["DELETE.","TRUNCATE.","DROP.","ALTER."],"h":["Elimina el objeto por completo de la base de datos.","No solo borra las filas, sino también la estructura.","Es una operación del DDL, no del DML."],"c":2,"e":"La sentencia DROP elimina por completo la tabla, desapareciendo de la base de datos tanto su estructura como el contenido de la misma.","d":2,"id":"q169","unit":"UF2405-UD6"},{"q":"¿Qué tipo de combinaciones de tablas existen en SQL para agregar conjuntos de datos?","o":["JOIN y UNION.","Solo JOIN.","COMMIT y UNION.","Solo UNION."],"h":["Una combina columnas de varias tablas horizontalmente (JOIN).","Otra combina filas de múltiples consultas verticalmente (UNION).","Son fundamentales para consultas complejas."],"c":0,"e":"Los tipos principales de combinaciones de tablas para agregar conjuntos de datos en una consulta son JOIN (combinación de columnas) y UNION (combinación de filas).","d":2,"id":"q170","unit":"UF2405-UD7"},{"q":"La sentencia UNION puede llevar las siguientes cláusulas:","o":["WHERE, GROUP BY y HAVING.","ORDER BY, WHERE y GROUP BY.","ORDER BY y HAVING.","WHERE, GROUP BY, HAVING y ORDER BY."],"h":["Filtra resultados (WHERE, HAVING).","Agrupa datos (GROUP BY).","Ordena el resultado final (ORDER BY). Todas son opcionales pero compatibles."],"c":3,"e":"Las cláusulas WHERE, GROUP BY, HAVING y ORDER BY son cláusulas opcionales que pueden aparecer dentro de las sentencias que se combinan con UNION.","d":3,"id":"q171","unit":"UF2405-UD7"},{"q":"¿Qué es una excepción en Java?","o":["Una instrucción de compilación.","Un evento que interrumpe el flujo normal de instrucciones durante la ejecución.","Un error de sintaxis detectado antes de compilar.","Una clase que hereda de Object directamente."],"h":["Ocurre en tiempo de ejecución.","Puede ser capturada y manejada para evitar que el programa termine abruptamente.","Deriva de la clase Throwable."],"c":1,"e":"Una excepción es un evento que se produce durante la ejecución de un programa, que interrumpe el flujo normal de las instrucciones del programa.","d":1,"id":"q172","unit":"UF2406-UD7"},{"q":"Las tres clases de excepciones que hay en Java son:","o":["Comprobadas, no comprobadas (tiempo de ejecución) y errores.","Sintácticas, lógicas y de ejecución.","De entrada, de salida y de red.","Solo existe la clase Exception."],"h":["El programador debe verificar las \"comprobadas\" (checked).","Las \"no comprobadas\" suelen ser errores de programación (RuntimeException).","Los \"errores\" (Error) son problemas graves de la JVM."],"c":0,"e":"Las tres clases de excepciones en Java son: excepciones comprobadas, excepciones en tiempo de ejecución (no comprobadas) y errores.","d":2,"id":"q173","unit":"UF2406-UD7"},{"q":"Las excepciones se capturan...","o":["Con la sentencia throw.","Mediante un bloque finally.","Mediante una estructura try-catch.","Con la sentencia throws."],"h":["Se intenta ejecutar código en un bloque de prueba.","Si falla, se atrapa en otro bloque específico.","El bloque que atrapa empieza por la palabra \"catch\"."],"c":2,"e":"Para poder capturar excepciones, se emplea la estructura de captura de excepciones try-catch-finally. El bloque catch contiene el código que se ejecuta cuando se invoca el controlador de excepciones.","d":1,"id":"q174","unit":"UF2406-UD7"},{"q":"Las excepciones se lanzan...","o":["Con la sentencia throw.","Mediante un bloque finally.","Mediante un bloque try.","Con la sentencia throws (en la firma del método)."],"h":["Es la acción de generar el objeto excepción manualmente.","Se usa una palabra clave específica seguida del objeto.","No debe confundirse con \"throws\", que solo declara que un método puede lanzarla."],"c":0,"e":"El hecho de que se produzca la creación de un objeto de excepción y entregarla al sistema de tiempo de ejecución se llama lanzar una excepción, y se realiza con la sentencia throw.","d":1,"id":"q175","unit":"UF2406-UD7"},{"q":"El bloque finally...","o":["Es una herramienta clave para la prevención de pérdida de recursos.","Es obligatorio incluirlo siempre.","Se coloca antes del try.","Solo se ejecuta si hay una excepción."],"h":["Se ejecuta siempre, haya o no excepción.","Es ideal para cerrar archivos, conexiones o liberar memoria.","Evita fugas de recursos bloqueados."],"c":0,"e":"El bloque finally es una herramienta clave para la prevención de pérdidas de recursos. Siempre hay que cerrar un archivo o liberar recursos, y finally asegura que este código se ejecute independientemente de si ocurrió una excepción.","d":2,"id":"q176","unit":"UF2406-UD7"},{"q":"Si el software es una primera versión sobre la que se va a seguir trabajando...","o":["No hace falta documentación de requisitos.","La documentación de diseño se puede eliminar.","La documentación de requisitos es muy útil como guía para el cambio.","No es necesario documentar nada."],"h":["El software evoluciona con el tiempo.","Saber qué se pidió originalmente ayuda a no romper funcionalidades existentes.","Facilita la gestión del cambio y la verificación."],"c":2,"e":"Si el software es una primera versión sobre la que más tarde se va a seguir trabajando, la documentación de los requisitos es muy útil en la gestión del cambio de software y verificar que no se ha deteriorado cuando se modifica.","d":2,"id":"q177","unit":"UF2406-UD8"},{"q":"La programación explicativa...","o":["No existe tal concepto.","Es un paradigma de programación estructurada.","Es el resultado de la aplicación práctica de la escritura de programación autoexplicativa en contextos reales.","Solo se practica en Java."],"h":["Propone separar código fuente y documentación, pero vinculados.","Busca que el código se entienda por sí mismo.","Donald Knuth abogó por ideas similares (programación literaria)."],"c":2,"e":"La programación explicativa es el resultado de la aplicación práctica de la escritura de programación autoexplicativa en contextos de programación real, proponiendo a menudo que el código fuente y la documentación se almacenen por separado pero vinculados dinámicamente.","d":3,"id":"q178","unit":"UF2406-UD8"},{"q":"Cuando se documenta el código...","o":["Se puede asumir que el usuario tendrá conocimientos avanzados.","No hay que incluir imágenes.","No se debe de asumir nada que el usuario deba saber.","Todas las respuestas son incorrectas."],"h":["La documentación debe ser clara para todos los niveles.","No dar por sentado conocimientos previos.","Explicar el \"por qué\", no solo el \"qué\"."],"c":2,"e":"Un principio importante al documentar es no asumir nada que el usuario deba saber. La documentación debe ser escrita de manera que cualquier persona con conocimientos básicos pueda leerla y aprender a utilizar correctamente el sistema.","d":2,"id":"q179","unit":"UF2406-UD8"},{"q":"Los estándares de documentación:","o":["Convienen utilizarlos siempre.","No es necesario que se usen, son orientativos.","No existe ninguno para Java.","Ninguna de las respuestas es correcta."],"h":["Ayudan a mantener la coherencia en el proyecto.","Facilitan que otros desarrolladores entiendan el código rápidamente.","Javadoc es un ejemplo de estándar ampliamente aceptado."],"c":0,"e":"Conviene seguir las pautas de documentación corporativa y estándares, ya que ayudan a asegurar que la información importante no se excluye y permiten una lectura más fácil y uniforme por parte de los usuarios del sistema.","d":1,"id":"q180","unit":"UF2406-UD8"},{"q":"Se ha de documentar el código...","o":["Para facilitar su mantenimiento y reutilización.","Principalmente por motivos estéticos.","Porque lo indican los estándares ISO únicamente.","Solamente en organizaciones muy grandes."],"h":["Ayuda a otros programadores (o a ti mismo en el futuro).","Explica qué hace el código y por qué.","Es una necesidad práctica, no un lujo."],"c":0,"e":"Se ha de documentar el código porque facilitaremos su mantenimiento y reutilización. Es una necesidad que se aprecia en su debida magnitud cuando hay errores que reparar o hay que extender el programa con nuevas capacidades.","d":1,"id":"q181","unit":"UF2406-UD8"},{"q":"La documentación de Javadoc:","o":["Se basa en etiquetas que empiezan por #.","Si no se incluye, la clase no compila.","En ella existen etiquetas de bloque y etiquetas en texto.","Se usa solo para documentar excepciones."],"h":["Usa comentarios especiales con formato /** ... */.","Tiene etiquetas como @param, @return.","La herramienta genera archivos HTML navegables."],"c":2,"e":"En los comentarios de documentación de Javadoc existen dos tipos generales de etiquetas: etiquetas de bloque (que comienzan con @) y etiquetas en texto (que se definen entre llaves {@etiqueta}).","d":2,"id":"q182","unit":"UF2406-UD8"},{"q":"Para indicar el valor de retorno de un método en Javadoc...","o":["Se usa la etiqueta @param.","Se usa la etiqueta @version.","Se usa la etiqueta @return.","Se usa la etiqueta @throws."],"h":["Describe qué devuelve el método.","No se usa en métodos void.","Empieza con la letra 'r'."],"c":2,"e":"La etiqueta @return se utiliza en Javadoc para dejar explícito qué tipo o clase de valor devuelve un método y sus posibles rangos de valores. Se puede omitir en métodos que devuelven void.","d":1,"id":"q183","unit":"UF2406-UD8"},{"q":"Las descripciones de los métodos en Javadoc deben empezar...","o":["Por una frase nominal.","Con la etiqueta @methodDescription.","Con la etiqueta @throw.","Por una frase verbal."],"h":["Describe una acción.","Ejemplo: \"Devuelve la etiqueta\" en lugar de \"Este método obtiene...\".","Es una convención de estilo para la tercera persona descriptiva."],"c":3,"e":"Las descripciones de los métodos deben comenzar con una frase verbal (tercera persona descriptiva), ya que un método implementa una operación. Por ejemplo: \"Devuelve la etiqueta de este botón\".","d":2,"id":"q184","unit":"UF2406-UD8"},{"q":"¿Cuál es la principal característica que diferencia al modelo de ciclo de vida en espiral de otros modelos tradicionales como el cascada?","o":["La ausencia total de documentación hasta la entrega final.","La entrega de un producto final completo sin usar prototipos.","La evaluación explícita y continua de riesgos en cada ciclo.","La división inflexible en etapas secuenciales sin retorno."],"h":["Fue propuesto por Barry Boehm en 1985.","Combina elementos del modelo en cascada y de la construcción de prototipos.","Su nombre proviene de la forma gráfica en la que se repiten las iteraciones de desarrollo."],"c":2,"e":"El modelo en espiral se centra fuertemente en la gestión de riesgos. En cada vuelta de la espiral se evalúan los riesgos potenciales (técnicos y de gestión) y se eligen alternativas para mitigarlos antes de avanzar a la siguiente fase, lo que lo hace ideal para proyectos grandes y complejos.","d":2,"id":"q185","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"En el contexto de las bases de datos relacionales y el lenguaje SQL, ¿cuál de las siguientes sentencias pertenece al Lenguaje de Manipulación de Datos (DML) y no al de Definición de Datos (DDL)?","o":["CREATE","DROP","UPDATE","ALTER"],"h":["El DML se usa para consultar y modificar los datos dentro de las tablas.","El DDL se usa para crear o modificar la estructura (esquema) de la base de datos.","La sentencia buscada sirve para modificar registros ya existentes."],"c":2,"e":"UPDATE es una sentencia DML utilizada para modificar datos en tablas ya existentes. Por el contrario, CREATE, ALTER y DROP son sentencias DDL utilizadas para definir, modificar o eliminar la estructura de los objetos de la base de datos (como tablas o vistas).","d":1,"id":"q186","unit":"UF2405-UD5","tipo":"ampliado","nv":"Fácil"},{"q":"Al conectar una aplicación Java con una base de datos, se utilizan controladores JDBC. ¿Cómo se denomina al tipo de driver JDBC que traduce las llamadas JDBC directamente al protocolo nativo de la base de datos, sin usar ODBC ni APIs nativas intermedias?","o":["Puente JDBC-ODBC","Java parcialmente nativo","Java nativo – NET","Java nativo JDBC – Independiente"],"h":["Es conocido comúnmente como el driver de \"Tipo 4\".","Está escrito completamente en Java, lo que le da total independencia de plataforma.","Ofrece gran rendimiento pero requiere un driver distinto para cada fabricante de base de datos."],"c":3,"e":"El driver \"Java nativo JDBC – Independiente\" se comunica directamente con el servidor de base de datos utilizando su protocolo nativo. Al no usar ODBC ni bibliotecas nativas, elimina la configuración del cliente, aunque su desventaja es que no es portable entre distintos fabricantes de SGBD.","d":3,"id":"q187","unit":"UF2405-UD5","tipo":"ampliado","nv":"Difícil"},{"q":"En un diagrama de clases UML, ¿cómo se representa gráficamente la relación de herencia (generalización) entre una subclase y una superclase?","o":["Mediante una línea continua con un triángulo relleno apuntando a la subclase.","Mediante una línea discontinua con una flecha abierta.","Mediante una línea continua con un rombo hueco en el extremo.","Mediante una línea continua con un triángulo hueco apuntando a la superclase."],"h":["La flecha siempre apunta desde lo más específico (clase hija) hacia lo más general (clase madre).","La forma de la punta de la flecha es un triángulo.","El triángulo no está coloreado por dentro (es hueco)."],"c":3,"e":"En UML, la generalización o herencia se dibuja como una línea sólida con un triángulo hueco en la punta. La punta del triángulo siempre toca a la superclase, y la línea sale de la subclase, indicando que la subclase hereda los atributos y métodos de la superclase.","d":1,"id":"q188","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"En el tratamiento de excepciones en Java mediante la estructura try-catch-finally, ¿cuál es la función principal y característica del bloque finally?","o":["Se ejecuta siempre al salir del bloque try, independientemente de si hubo excepción o no.","Se utiliza para declarar las excepciones que el método va a lanzar a quien lo llame.","Se ejecuta únicamente si no se produce ninguna excepción en el try.","Se ejecuta solo si se captura una excepción en el bloque catch."],"h":["Es la herramienta clave para la prevención de pérdidas de recursos (como cerrar archivos).","Se coloca al final de la estructura de control de excepciones.","Su ejecución es incondicional al finalizar el bloque try."],"c":0,"e":"El bloque finally siempre se ejecuta cuando se sale del bloque try, ya sea porque el código finalizó correctamente, porque se lanzó una excepción, o porque se ejecutó una sentencia return o break. Es el lugar idóneo para poner código de limpieza.","d":2,"id":"q189","unit":"UF2406-UD7","tipo":"ampliado","nv":"Intermedio"},{"q":"En las pruebas de caja blanca, la prueba del camino básico utiliza la complejidad ciclomática V(G) para determinar el número de caminos independientes que deben ser probados. Si un grafo de flujo de un programa tiene 10 aristas (A) y 8 nodos (N), ¿cuál es su complejidad ciclomática usando la fórmula de McCabe V(G) = A - N + 2?","o":["18","4","2","20"],"h":["La fórmula a aplicar es exactamente V(G) = A - N + 2.","Sustituye en la fórmula los valores dados: A = 10 y N = 8.","La operación matemática resultante es 10 - 8 + 2."],"c":1,"e":"Aplicando la fórmula de McCabe para la complejidad ciclomática basada en aristas y nodos del grafo de flujo: V(G) = A - N + 2. Sustituyendo los valores del enunciado: V(G) = 10 - 8 + 2 = 4. Esto significa que el programa tiene 4 caminos independientes que deben ser ejercitados mediante casos de prueba para garantizar que todas las sentencias se ejecutan al menos una vez.","d":3,"id":"q190","unit":"UF2406-UD6","tipo":"ampliado","nv":"Supremo"},{"q":"¿Cuál es el principal inconveniente del modelo de ciclo de vida en cascada en el desarrollo de software?","o":["Es el modelo más rápido para entregar un producto final al cliente.","Requiere detallar todos los requisitos al comienzo del proyecto, lo que es poco realista.","Es demasiado flexible y permite cambios constantes sin control.","No genera documentación, lo que dificulta el mantenimiento."],"h":["Fue propuesto inicialmente por Royce en 1970.","Es un proceso secuencial y rígido donde una fase debe terminar para empezar la siguiente.","El cliente no ve resultados del producto hasta que está completamente finalizado."],"c":1,"e":"El mayor inconveniente del modelo en cascada es su rigidez. Asume que todos los requisitos pueden y deben estar perfectamente definidos al inicio, lo que rara vez ocurre en la vida real. Si surgen cambios o errores no detectados en fases tempranas, volver atrás es muy costoso y difícil.","d":1,"id":"q191","unit":"UF2406-UD1","tipo":"ampliado","nv":"Fácil"},{"q":"En un diagrama de clases UML, ¿cómo se representa gráficamente el nombre de una clase abstracta para distinguirla de una clase concreta?","o":["Escribiendo el nombre en negrita y subrayado.","Añadiendo el estereotipo <<final>> sobre el nombre.","Escribiendo el nombre en letra cursiva (itálica).","Encerrando el nombre dentro de un rombo."],"h":["Una clase abstracta no se puede instanciar directamente.","Existe para que otras clases (subclases) hereden sus características.","Es una convención de notación estándar en la especificación UML."],"c":2,"e":"Según la especificación UML, el nombre de una clase abstracta (o de cualquier clasificador abstracto) debe escribirse en letra cursiva. Esto indica visualmente al lector del diagrama que no se pueden crear objetos directos de esa clase, sino de sus descendientes.","d":2,"id":"q192","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En la programación de interfaces gráficas (GUI) en Java, cuando se registra un ActionListener para un botón, ¿qué método de dicha interfaz es obligatorio implementar para gestionar la acción de pulsación?","o":["onPress()","buttonClicked(ActionEvent e)","actionPerformed(ActionEvent e)","handleEvent(Object e)"],"h":["Es el único método abstracto que define la interfaz ActionListener.","Recibe como parámetro un objeto de tipo ActionEvent.","Se registra en el componente mediante el método addActionListener()."],"c":2,"e":"La interfaz ActionListener en Java posee un único método llamado actionPerformed(ActionEvent e). Este método contiene la lógica (el código) que se ejecutará automáticamente cuando el usuario realice la acción asociada, como hacer clic en el botón.","d":3,"id":"q193","unit":"UF2406-UD4","tipo":"ampliado","nv":"Difícil"},{"q":"Según el método de prueba del camino básico propuesto por Tom McCabe, si el grafo de flujo de un programa tiene 12 aristas (A) y 9 nodos (N), ¿cuál es su complejidad ciclomática V(G)?","o":["108","5","3","21"],"h":["La fórmula básica es V(G) = A - N + 2.","Sustituye los valores: A = 12 y N = 9.","El resultado indica el número de caminos independientes que deben probarse."],"c":1,"e":"Aplicando la fórmula de McCabe para la complejidad ciclomática basada en aristas y nodos del grafo de flujo: V(G) = A - N + 2. Sustituyendo los valores del enunciado: V(G) = 12 - 9 + 2 = 5. Esto significa que el programa tiene 5 caminos independientes que deben ser ejercitados mediante casos de prueba.","d":3,"id":"q194","unit":"UF2406-UD6","tipo":"ampliado","nv":"Difícil"},{"q":"Según el modelo de calidad de software ISO 9126, ¿cuál de los siguientes conjuntos de atributos corresponde EXCLUSIVAMENTE a la subcaracterística de \"Mantenibilidad\"?","o":["Madurez, tolerancia a fallos, recuperabilidad.","Analizabilidad, facilidad para el cambio, estabilidad, testeabilidad.","Adaptabilidad, instalabilidad, conformidad, reemplazo.","Entendimiento, aprendizaje, operabilidad, atractivo."],"h":["Se relaciona directamente con el esfuerzo necesario para realizar modificaciones en el software.","Incluye la capacidad de diagnosticar deficiencias o causas de fallos.","No debe confundirse con \"Portabilidad\" (Opción C) ni con \"Fiabilidad\" (Opción A)."],"c":1,"e":"La opción B enumera las subcaracterísticas correctas de la Mantenibilidad según ISO 9126. La opción A corresponde a la Fiabilidad, la opción C a la Portabilidad y la opción D a la Usabilidad. La mantenibilidad se centra en cuán fácil es corregir, adaptar o mejorar el código.","d":3,"id":"q195","unit":"UF2406-UD5","tipo":"ampliado","nv":"Supremo"},{"q":"En Java, respecto al bloque finally dentro de una estructura de manejo de excepciones (try-catch-finally), ¿cuál de las siguientes afirmaciones es verdadera?","o":["Es un bloque obligatorio; el compilador dará error si no se incluye.","Solo se ejecuta si no se produce ninguna excepción en el bloque try.","Se ejecuta siempre al salir del bloque try, independientemente de si hubo excepción o no.","Su única función es lanzar (throw) la excepción al método superior."],"h":["Es el lugar ideal para poner código de limpieza, como cerrar archivos o conexiones a bases de datos.","Se ejecuta incluso si dentro del try o del catch hay una sentencia return.","Es opcional, no es obligatorio incluirlo en la estructura."],"c":2,"e":"El bloque finally está diseñado para garantizar la ejecución de un fragmento de código sin importar cómo termine el bloque try (ya sea con éxito o lanzando una excepción). Esto lo convierte en la herramienta clave para la prevención de pérdidas de recursos.","d":2,"id":"q196","unit":"UF2406-UD7","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de secuencia de UML, ¿qué representa el símbolo formado por un rectángulo (cabeza) del que desciende una línea vertical (que puede ser discontinua)?","o":["Un estado invariante.","Un mensaje perdido.","Un fragmento combinado.","Una línea de vida (lifeline)."],"h":["Representa la existencia de un participante a lo largo del tiempo.","El rectángulo superior contiene el nombre de la clase o del objeto.","Los mensajes se dibujan como flechas horizontales que parten o llegan a esta línea."],"c":3,"e":"La línea de vida representa el comportamiento de un elemento (objeto o actor) a lo largo de su existencia durante la interacción. El rectángulo forma la \"cabeza\" y la línea vertical representa el tiempo de vida del participante en el escenario.","d":2,"id":"q197","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál es la principal desventaja o requisito crítico del algoritmo de recolección de basura \"Copying Collector\" (Recolector de copias) en la gestión de memoria?","o":["Requiere escanear la memoria completa antes de poder liberar cualquier bloque.","Provoca una altísima fragmentación externa en la memoria virtual.","Necesita temporalmente un almacenamiento extra de memoria para que coexistan la copia antigua y la nueva.","No puede combinarse bajo ninguna circunstancia con el algoritmo Mark-Sweep."],"h":["Su nombre en inglés indica que \"copia\" los bloques.","Mueve los bloques de memoria de un lugar a otro para compactar.","Durante el movimiento, el objeto original y el nuevo deben existir simultáneamente."],"c":2,"e":"El algoritmo copying collector mueve bloques de memoria ya alojados a lo largo de la memoria completa y ajusta las referencias. Su principal desventaja es que necesita de forma temporal un almacenamiento extra de memoria para que coexistan la copia antigua y la copia nueva del bloque mientras se realiza el movimiento.","d":3,"id":"q198","unit":"UF2404-UD7","tipo":"ampliado","nv":"Difícil"},{"q":"En el framework de pruebas JUnit para Java, ¿qué anotación se utiliza para marcar un método que debe ejecutarse antes de cada prueba individual con el fin de preparar el entorno (por ejemplo, inicializar variables)?","o":["@Test","@After","@Before","@BeforeClass"],"h":["Se ejecuta múltiples veces (una por cada test).","Su nombre en inglés significa \"Antes\".","No debe ser un método estático (a diferencia de su variante \"Class\")."],"c":2,"e":"La anotación @Before marca un método que se ejecuta antes de cada prueba para preparar el entorno. Se diferencia de @BeforeClass, que se ejecuta una sola vez antes de que comiencen todas las pruebas de la clase.","d":1,"id":"q199","unit":"UF2406-UD6","tipo":"ampliado","nv":"Fácil"},{"q":"Según el modelo de calidad de software ISO 9126, ¿cuál de las siguientes subcaracterísticas pertenece al factor de \"Mantenibilidad\" y se define específicamente como los atributos que miden el esfuerzo necesario para validar el software modificado?","o":["Facilidad para el cambio.","Testeabilidad.","Estabilidad.","Analizabilidad."],"h":["Está directamente relacionada con las pruebas (testing).","Es una subcaracterística de la mantenibilidad, no de la funcionalidad.","Su objetivo es asegurar que las modificaciones no han roto el sistema."],"c":1,"e":"Dentro de la \"Mantenibilidad\" en ISO 9126, la Testeabilidad mide el esfuerzo necesario para validar el software modificado. La Analizabilidad mide el esfuerzo para diagnosticar fallos, y la Estabilidad mide el riesgo de efectos no esperados.","d":3,"id":"q200","unit":"UF2406-UD5","tipo":"ampliado","nv":"Supremo"},{"q":"En el proceso de normalización de bases de datos relacionales, ¿qué establece fundamentalmente la Primera Forma Normal (1FN)?","o":["Eliminar las dependencias transitivas entre atributos no clave.","Asegurar que todos los atributos dependan de la clave primaria completa.","Eliminar los grupos repetitivos y asegurar que los valores de los atributos sean atómicos.","Garantizar que no existan claves foráneas con valores nulos."],"h":["Es la primera etapa del proceso de normalización.","Busca que los datos no se puedan dividir en partes más pequeñas.","Evita que haya múltiples valores en una sola celda o columna."],"c":2,"e":"La Primera Forma Normal (1FN) establece que las columnas repetidas (grupos repetitivos) deben eliminarse y situarse en tablas separadas, y que los dominios o valores de los atributos deben ser atómicos (indivisibles).","d":2,"id":"q201","unit":"UF2405-UD4","tipo":"ampliado","nv":"Intermedio"},{"q":"Según el modelo de calidad de software ISO 9126, ¿cuál de las siguientes subcaracterísticas de la \"Mantenibilidad\" mide el esfuerzo necesario para diagnosticar deficiencias o causas de fallas, o para identificar las partes que deben ser modificadas?","o":["Estabilidad.","Analizabilidad.","Facilidad de prueba (Testeabilidad).","Facilidad para el cambio."],"h":["Está directamente relacionada con el \"diagnóstico\" y el \"análisis\" del problema.","No mide la facilidad para modificar el código (eso es otra subcaracterística), sino para entender dónde está el fallo.","Es la primera subcaracterística que se suele listar dentro del bloque de Mantenibilidad en la norma."],"c":1,"e":"La Analizabilidad se define en ISO 9126 como el conjunto de atributos que miden el esfuerzo necesario para el diagnóstico de deficiencias o causas de fallas, o para identificar las partes que deben ser modificadas. La estabilidad mide el riesgo de efectos no esperados, y la facilidad para el cambio mide el esfuerzo para realizar la modificación en sí.","d":3,"id":"q202","unit":"UF2406-UD5","tipo":"ampliado","nv":"Difícil"},{"q":"¿Qué algoritmo de recolección de basura mueve los bloques de memoria ya alojados a lo largo de la memoria completa y ajusta las referencias a la nueva localización, requiriendo temporalmente un almacenamiento extra?","o":["Incremental Collection.","Conservative Collection.","Copying Collector (Recolector de copias).","Mark-Sweep (Marcado y Barrido)."],"h":["Su nombre en inglés indica que \"copia\" los bloques de un lugar a otro.","Su principal ventaja es que soluciona la fragmentación externa y mejora la localidad de referencia.","Su mayor desventaja es que necesita que coexistan la copia antigua y la nueva temporalmente."],"c":2,"e":"El algoritmo Copying Collector mueve bloques de memoria y ajusta las referencias. Es muy potente para evitar la fragmentación, pero requiere de forma temporal un almacenamiento extra de memoria para que coexistan la copia antigua y la copia nueva del bloque mientras se realiza el movimiento.","d":2,"id":"q203","unit":"UF2404-UD7","tipo":"ampliado","nv":"Intermedio"},{"q":"En el patrón de diseño Modelo-Vista-Controlador (MVC) aplicado a Servlets y JSP (Model 2), ¿qué componente es el responsable de leer los parámetros de la petición HTTP, invocar la lógica de negocio, almacenar los resultados en un Bean y redirigir la petición mediante un RequestDispatcher?","o":["El Contenedor Web (Tomcat).","El Controlador (Servlet).","La Vista (JSP).","El Modelo (JavaBean)."],"h":["En la arquitectura Java EE, este componente actúa como intermediario entre el cliente y la presentación.","Recibe la petición HTTP del cliente (métodos doGet o doPost).","No genera el HTML directamente, sino que delega la presentación a otro componente usando forward()."],"c":1,"e":"El Controlador (normalmente implementado como un Servlet) maneja la petición inicial, procesa los datos (o invoca la lógica de negocio), configura los beans (Modelo) y pasa los resultados a las páginas JSP (Vista) usando RequestDispatcher.forward(). La Vista (JSP) solo se encarga de mostrar los datos.","d":3,"id":"q204","unit":"UF2405-UD3","tipo":"ampliado","nv":"Supremo"},{"q":"En el diagrama de clases del sistema de Videoclub (caso práctico de la UF2406), la clase Alquiler mantiene una relación con las clases Cliente y Pelicula. ¿Cómo se define la cardinalidad o multiplicidad desde la perspectiva de una instancia concreta de Alquiler hacia Cliente?","o":["0 a N (Un alquiler puede no tener cliente asociado).","1 a N (Un alquiler puede ser firmado por muchos clientes a la vez).","1 a 1 (Un alquiler concreto es realizado por un solo cliente).","N a M (Muchos alquileres corresponden a muchos clientes)."],"h":["Un Alquiler no \"es un\" cliente (no es herencia).","Aunque un Cliente puede hacer muchos Alquileres a lo largo del tiempo (1 a N desde Cliente), la pregunta se hace desde la perspectiva del Alquiler.","En el diagrama de clases definitivo del caso práctico, se establecen relaciones de asociación simples."],"c":2,"e":"En el caso práctico del Videoclub, un Alquiler mantiene una relación de asociación. Desde el punto de vista de la instancia del Alquiler, este corresponde a un solo Cliente (relación 1 a 1 desde Alquiler hacia Cliente, y 1 a 1 desde Alquiler hacia Película).","d":2,"id":"q205","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de clases UML, ¿qué símbolo se utiliza para indicar que un atributo o método tiene visibilidad \"protegida\" (protected)?","o":["-","#","+","~"],"h":["No es el símbolo que indica acceso público (+).","No es el símbolo que indica acceso privado (-).","Es el símbolo de la visibilidad que alcanza a la propia clase y a las clases que heredan de ella (generalización)."],"c":1,"e":"En UML la visibilidad protegida se representa con #: el elemento es visible para la propia clase y para sus subclases (elementos con relación de generalización). La de paquete se representa con ~.","d":1,"id":"q206","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"En la programación de interfaces gráficas en Java, ¿qué interfaz debe implementar una clase para gestionar el evento de pulsar un botón (ActionEvent)?","o":["MouseListener","ActionListener","KeyListener","WindowListener"],"h":["Se usa específicamente para acciones como hacer clic en un botón o presionar Enter en un campo de texto.","Requiere implementar obligatoriamente el método actionPerformed.","Se registra en el componente utilizando el método addActionListener."],"c":1,"e":"La interfaz ActionListener es la encargada de recibir y procesar los eventos de acción en Java. Cuando se produce una acción en el botón, el sistema llama al método actionPerformed(ActionEvent e) del oyente registrado.","d":1,"id":"q207","unit":"UF2406-UD4","tipo":"ampliado","nv":"Fácil"},{"q":"Respecto al bloque finally en el manejo de excepciones de Java, ¿cuál de las siguientes afirmaciones es FALSA?","o":["Se ejecuta siempre al salir del bloque try, independientemente de si hubo excepción o no.","Es el lugar ideal y una buena práctica para poner código de limpieza, como cerrar archivos o conexiones.","No se ejecutará si la JVM (Máquina Virtual de Java) sale abruptamente o se interrumpe el hilo.","Es un bloque estrictamente obligatorio; el compilador de Java dará un error si no se incluye inmediatamente después de un try."],"h":["Piensa en la sintaxis básica: ¿puede existir un try acompañado solamente de un catch?","Su propósito principal es la prevención de pérdidas de recursos.","La palabra \"finally\" significa \"finalmente\", indicando que es el paso final, pero no es sintácticamente forzoso."],"c":3,"e":"El bloque finally es opcional. Un bloque try debe ir seguido de al menos un bloque catch o de un bloque finally, pero no es obligatorio que siempre exista un finally. Las demás afirmaciones (A, B y D) son verdaderas según la especificación de Java.","d":3,"id":"q208","unit":"UF2406-UD7","tipo":"ampliado","nv":"Difícil"},{"q":"En las pruebas de caja blanca, la complejidad ciclomática de McCabe, denotada como V(G), se puede calcular utilizando el número de nodos (N) y el número de aristas (A) de un grafo de flujo. ¿Cuál es la fórmula matemática correcta?","o":["V(G) = A + N + 2","V(G) = A - N + 2","V(G) = A * N","V(G) = N - A + 1"],"h":["Se resta el número de nodos al número de aristas.","Siempre se suma 2 al resultado de esa resta.","Este valor define el número máximo de caminos independientes del conjunto básico que deben probarse."],"c":1,"e":"La fórmula de la complejidad ciclomática de McCabe es V(G) = A - N + 2, donde A es el número de aristas y N es el número de nodos del grafo de flujo. Esto proporciona un límite superior para el número de pruebas necesarias para asegurar que se ejecuta cada sentencia al menos una vez.","d":3,"id":"q209","unit":"UF2406-UD6","tipo":"ampliado","nv":"Supremo"},{"q":"Al generar documentación automática con Javadoc en Java, ¿qué etiqueta de bloque se utiliza específicamente para describir los parámetros de un método o constructor?","o":["@param","@return","@throws","@author"],"h":["Va seguida inmediatamente del nombre del parámetro y una descripción de su función.","Es aplicable tanto a constructores como a métodos.","No debe confundirse con la etiqueta que describe el valor que devuelve el método."],"c":0,"e":"La etiqueta @param se utiliza en los comentarios de documentación de Javadoc para describir cada uno de los parámetros que recibe un método o un constructor, indicando su nombre y su propósito.","d":2,"id":"q210","unit":"UF2406-UD8","tipo":"ampliado","nv":"Intermedio"},{"q":"En el modelo de eventos de Java para interfaces gráficas (GUI), cuando un usuario hace clic en un botón, se genera un evento. ¿Qué método de la interfaz ActionListener es obligatorio implementar para gestionar esta acción y qué tipo de objeto recibe como parámetro?","o":["buttonClicked(ButtonEvent)","mouseClicked(MouseEvent)","actionPerformed(ActionEvent)","keyPressed(KeyEvent)"],"h":["La interfaz se llama ActionListener, por lo que el método suele empezar por \"action\".","El evento específico de un botón o acción genérica en Java es ActionEvent.","Es el método que el sistema llama automáticamente cuando se dispara el evento registrado con addActionListener."],"c":2,"e":"Los objetos que implementan la interfaz ActionListener están obligados a implementar el método actionPerformed(ActionEvent evt). Este método recibe un objeto ActionEvent que contiene información sobre el evento exacto que ocurrió (como qué botón se pulsó), permitiendo al programador ejecutar la lógica de negocio correspondiente.","d":3,"id":"q211","unit":"UF2406-UD4","tipo":"ampliado","nv":"Supremo"},{"q":"En el diagrama de clases del sistema Videoclub, ¿qué clase es la responsable de mantener la persistencia de los datos (listas de películas, clientes y alquileres) y proporcionar métodos como buscarPelicula() e insertarAlquiler()?","o":["Videoclub (o Almacén)","Cliente","Película","Alquiler"],"h":["No es una clase que represente un objeto físico tangible ni un usuario final.","Actúa como un contenedor o gestor global de las otras entidades del sistema.","En los documentos de apoyo se le denomina indistintamente \"Videoclub\" o \"Almacén\"."],"c":0,"e":"La clase Videoclub (también referenciada como Almacén en algunos diagramas) es la encargada de la persistencia. Mantiene las listas de objetos (listaPeliculas, listaClientes, listaAlquileres) y gestiona las operaciones de búsqueda e inserción sobre estas colecciones, actuando como el núcleo de almacenamiento de la aplicación.","d":2,"id":"q212","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"\"El ingeniero usa una computadora\", es una manera de interactuar entre objetos por:","o":["Adicción.","Composición.","Asociación.","Objetos."],"h":["Es una relación débil de tipo \"usa-un\" (uses-a).","Los objetos involucrados tienen ciclos de vida totalmente independientes.","La destrucción de uno de los objetos no implica la destrucción del otro."],"c":2,"e":"En UML, la asociación representa una relación semántica entre clasificadores donde las instancias pueden estar vinculadas. En este caso, un ingeniero \"usa\" una computadora, pero ambos existen de manera independiente; si el ingeniero deja de usar la computadora o esta se rompe, el ingeniero sigue existiendo. No hay dependencia de existencia.","d":1,"id":"q213","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"¿Qué expresión relativa a Composición es falsa?","o":["Tanto los objetos como la clase contenedora, tienen el mismo tiempo de vida.","Si cualquier objeto muere, se lleva consigo a todos los demás.","Tanto los objetos como la clase contenedora, tienen diferentes tiempo de vida.","Es una relación demasiado dependiente entre objetos."],"h":["La composición implica obligatoriamente un ciclo de vida compartido.","La afirmación falsa describe en realidad a la Agregación compartida, no a la Composición.","En la composición, la parte no puede existir de forma independiente del todo."],"c":2,"e":"La opción C es falsa porque describe la Agregación (compartida), donde las partes pueden existir independientemente del todo (diferente tiempo de vida). En la Composición, los objetos (las partes) y la clase contenedora (el todo) tienen el mismo tiempo de vida. Si el contenedor se destruye, las partes también se destruyen automáticamente.","d":3,"id":"q214","unit":"UF2406-UD3","tipo":"ampliado","nv":"Difícil"},{"q":"Las clases y métodos abstractos se definen con la palabra clave abstract, pueden llevar el modificador abstract:","o":["Los constructores.","Los métodos estáticos.","Los métodos interactivos.","Los métodos privados."],"h":["Los constructores no pueden ser abstractos porque siempre deben instanciar algo concreto.","Los métodos estáticos pertenecen a la clase en sí y no se pueden sobrescribir dinámicamente en una subclase.","Los métodos privados no son visibles para las subclases, por lo que estas no podrían implementarlos."],"c":2,"e":"Un método abstract debe ser implementado por las subclases, por lo que no puede ser constructor, static ni private (no se heredan o no son visibles). «Métodos interactivos» no es un modificador de Java: la respuesta D es la única que no queda descartada por eliminación.","d":3,"id":"q215","unit":"UF2406-UD3","tipo":"ampliado","nv":"Supremo"},{"q":"En un diagrama de clases UML, ¿qué significa una multiplicidad de \"0..*\" en el extremo de una asociación?","o":["Exactamente cero instancias.","Cero o más instancias.","Una o más instancias.","Exactamente una instancia."],"h":["El primer número indica el límite inferior (mínimo).","El asterisco (*) indica un límite superior ilimitado (infinito).","Es la forma más común de representar una colección o lista en el lado \"muchos\" de una relación (por ejemplo, un cliente puede tener cero o muchos pedidos)."],"c":1,"e":"La notación \"0..*\" en UML especifica que el número de instancias asociadas puede ser desde cero (ninguna) hasta un número ilimitado. Por ejemplo, una biblioteca puede tener cero o muchos libros de un mismo título.","d":2,"id":"q216","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Por qué se considera que los componentes de Swing son de \"peso ligero\" (lightweight) en comparación con los de AWT?","o":["Porque no dependen de una ventana nativa del sistema operativo para cada componente.","Porque ocupan menos espacio en el disco duro.","Porque solo se pueden usar en sistemas operativos Windows.","Porque no permiten la interacción con el usuario."],"h":["AWT usa código nativo (heavyweight), lo que limita la portabilidad.","Swing se dibuja directamente dentro de la ventana contenedora usando métodos gráficos de Java.","Esto hace a Swing más portable, flexible y con menor consumo de recursos del sistema operativo."],"c":0,"e":"Los componentes AWT (\"peso pesado\") requieren que el sistema operativo cree una ventana nativa (peer) para cada componente, lo que consume más recursos. Swing (\"peso ligero\") dibuja los componentes directamente usando Java, sin depender de ventanas nativas del SO para cada elemento, siendo más eficiente y multiplataforma.","d":1,"id":"q217","unit":"UF2406-UD4","tipo":"ampliado","nv":"Fácil"},{"q":"Se ha de documentar el código principalmente para:","o":["Para facilitar su mantenimiento y reutilización.","Solamente en las organizaciones muy grandes como Oracle o Sun.","Principalmente por motivos estéticos.","Porque se indica en los estándares ISO."],"h":["El código por sí solo es insuficiente para entender su operación prevista a largo plazo.","Ayuda a otros desarrolladores (o a ti mismo en el futuro) a modificar, corregir errores o adaptar el programa a nuevos escenarios.","Es una necesidad práctica, no solo un acto de \"buen hacer\" para dejar la obra rematada estéticamente."],"c":0,"e":"Documentar el código añade información suficiente para explicar qué hace y por qué lo hace. Esto facilita enormemente su mantenimiento y reutilización, evitando que el programa se vuelva incomprensible cuando surja la necesidad de ampliarlo o repararlo.","d":1,"id":"q218","unit":"UF2406-UD8","tipo":"ampliado","nv":"Fácil"},{"q":"Respecto a la documentación generada con Javadoc, es cierto que:","o":["Se usa exclusivamente para documentar las excepciones que lanza un método.","En ella existen etiquetas de bloque y etiquetas en texto.","Si no se incluye la clase no compila correctamente.","Se basa en el uso de etiquetas que empiezan por #."],"h":["Las etiquetas de bloque comienzan con el símbolo @ y se colocan después de la descripción principal.","Las etiquetas en texto se definen entre llaves, como {@etiqueta}, y pueden aparecer en cualquier punto de la descripción.","Javadoc es una herramienta de generación de documentación, no un requisito para que el compilador de Java valide la sintaxis del código."],"c":1,"e":"Javadoc utiliza dos tipos generales de etiquetas: las etiquetas de bloque (que comienzan con @ y van después de la descripción principal) y las etiquetas en texto (que se definen entre llaves, como {@link}, y pueden ir en cualquier punto de la descripción o de otra etiqueta).","d":3,"id":"q219","unit":"UF2406-UD8","tipo":"ampliado","nv":"Difícil"},{"q":"Para indicar el valor de retorno de un método en la documentación de Javadoc, se utiliza la etiqueta:","o":["@return","@version","@param","@throws"],"h":["Esta etiqueta se puede omitir en los métodos que devuelven void.","Debe aparecer en todos los métodos que devuelven algo, dejando explícito qué tipo o clase de valor devuelve.","No debe confundirse con @param, que se utiliza para describir los parámetros de entrada del método."],"c":0,"e":"La etiqueta @return se utiliza en Javadoc para describir el valor que devuelve un método. Debe incluir una descripción clara del tipo o clase de valor devuelto y, si es necesario, sus posibles rangos o condiciones.","d":1,"id":"q220","unit":"UF2406-UD8","tipo":"ampliado","nv":"Fácil"},{"q":"En un diagrama de clases UML, ¿qué diferencia fundamental existe entre una relación de Agregación (compartida) y una relación de Composición?","o":["La agregación solo permite relaciones 1 a 1, mientras que la composición permite relaciones 1 a N.","En la composición, el ciclo de vida de la parte depende del todo (se destruye con él), mientras que en la agregación la parte puede existir independientemente.","La agregación se representa con un rombo negro y la composición con un rombo blanco.","La composición se utiliza exclusivamente para interfaces, mientras que la agregación se usa para clases abstractas."],"h":["Piensa en el ejemplo de un \"Coche\" y sus \"Ruedas\" versus un \"Departamento\" y sus \"Empleados\".","Una de las relaciones se representa gráficamente con un rombo relleno (negro) y la otra con un rombo hueco (blanco).","La clave está en la dependencia del ciclo de vida: si el \"todo\" desaparece, ¿qué pasa con la \"parte\"?"],"c":1,"e":"La Composición (rombo negro) es una relación \"fuerte\" de todo-parte donde la parte no puede existir sin el todo (si se elimina el coche, se eliminan sus ruedas específicas en ese contexto). La Agregación (rombo blanco) es una relación \"débil\" donde la parte puede existir independientemente del todo (si se disuelve un departamento, los empleados siguen existiendo en la empresa).","d":2,"id":"q221","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"¿En qué consiste la técnica de diseño de casos de prueba conocida como Análisis de Valores Límite (AVL)?","o":["Consiste en ejecutar el programa con todos los posibles valores de entrada para garantizar una cobertura exhaustiva del 100%.","Consiste en dividir el campo de entrada en clases de datos válidos e inválidos para reducir el número total de pruebas.","Consiste en seleccionar los casos de prueba en los \"extremos\" o límites de las clases de equivalencia, ya que los errores suelen acumularse en las fronteras.","Consiste en probar exclusivamente las condiciones lógicas (verdadero/falso) de los bucles anidados."],"h":["Es una técnica que complementa a la \"Partición Equivalente\".","Si un campo acepta valores del 1 al 100, esta técnica te diría que pruebes el 0, 1, 2, 99, 100 y 101.","Se basa en la observación empírica de que los programadores suelen fallar en las condiciones de borde (como usar < en lugar de <=)."],"c":2,"e":"El Análisis de Valores Límite (AVL) se centra en probar los bordes de las clases de equivalencia. Dado que los errores tienden a aparecer en los límites de los rangos de entrada, seleccionar valores justo en el límite, y justo por encima y por debajo, es una técnica muy eficaz para descubrir defectos sin tener que hacer una prueba exhaustiva.","d":1,"id":"q222","unit":"UF2406-UD6","tipo":"ampliado","nv":"Fácil"},{"q":"En el desarrollo de páginas JSP (Java Server Pages), el contenedor web pone a disposición del desarrollador una serie de variables predefinidas (objetos implícitos) sin necesidad de declararlas. ¿Cuál de los siguientes objetos implícitos se utiliza para almacenar y recuperar atributos que deben persistir a lo largo de toda la sesión de un usuario específico?","o":["request (HttpServletRequest)","pageContext (PageContext)","session (HttpSession)","application (ServletContext)"],"h":["El objeto request solo dura lo que dura una única petición HTTP.","El objeto application es compartido por todos los usuarios de la aplicación web.","El objeto buscado está asociado a la interfaz HttpSession y permite mantener el estado (como un carrito de la compra) entre varias peticiones de un mismo usuario."],"c":2,"e":"El objeto implícito session (de tipo HttpSession) permite almacenar información específica de un usuario a lo largo de múltiples peticiones. Mientras que request es efímero (una sola petición) y application es global (todos los usuarios), session mantiene el estado individual del usuario mientras su sesión esté activa.","d":3,"id":"q223","unit":"UF2405-UD3","tipo":"ampliado","nv":"Difícil"},{"q":"Al documentar el código fuente en Java utilizando Javadoc, necesitas especificar que un método puede lanzar una excepción comprobada (checked exception) bajo ciertas condiciones. ¿Qué etiqueta de bloque debes utilizar para documentar esta posibilidad y en qué sección del comentario Javadoc debe colocarse?","o":["Etiqueta @error, colocada en la zona de etiquetas.","Etiqueta @exception o @throws, colocada en la zona de etiquetas (después de la descripción principal).","Etiqueta @throws, colocada obligatoriamente antes de la descripción principal del método.","Etiqueta @catch, colocada en la zona de descripción principal."],"h":["Javadoc divide los comentarios en una \"zona de descripción\" y una \"zona de etiquetas\" (que comienzan con @).","Existen dos etiquetas sinónimas para indicar excepciones lanzadas: una más antigua y otra más moderna/estándar.","Las etiquetas de bloque siempre van después de la descripción principal del método o clase."],"c":1,"e":"Las etiquetas @throws y @exception son sinónimas en Javadoc y se utilizan para documentar las excepciones que un método puede lanzar. Como son etiquetas de bloque, deben colocarse en la \"zona de etiquetas\", es decir, después de la descripción principal del método, precedidas del símbolo @, seguidas del nombre de la excepción y una breve descripción de la condición que la provoca.","d":3,"id":"q224","unit":"UF2406-UD8","tipo":"ampliado","nv":"Supremo"},{"q":"Según el modelo de calidad de software ISO 9126, ¿cuál de las siguientes subcaracterísticas de la \"Usabilidad\" mide el esfuerzo del usuario en aprender la aplicación (control, operación, entrada, salida)?","o":["Operatividad.","Aprendizaje.","Atractivo.","Entendimiento."],"h":["Se refiere directamente a la curva de aprendizaje del usuario final con el nuevo sistema.","No debe confundirse con \"Entendimiento\", que mide el esfuerzo para reconocer el concepto lógico del software.","Está relacionada con la facilidad para dominar el control y la operación práctica del sistema."],"c":1,"e":"La subcaracterística de \"Aprendizaje\" en ISO 9126 mide específicamente el esfuerzo necesario para que el usuario aprenda a utilizar la aplicación, incluyendo el control, la operación y la entrada/salida de datos. Es un factor clave para que el software sea adoptado con éxito.","d":2,"id":"q225","unit":"UF2406-UD5","tipo":"ampliado","nv":"Intermedio"},{"q":"En el diseño de casos de prueba, el Análisis de Valores Límite (AVL) se centra en probar los casos en los \"extremos\" de las clases de equivalencia. Si una condición de entrada especifica un rango delimitado por los valores 'a' y 'b', ¿qué valores se deben diseñar para los casos de prueba?","o":["Los valores 'a', 'b' y un valor aleatorio dentro del rango.","Todos los valores enteros posibles entre 'a' y 'b'.","Los valores 'a' y 'b', y los valores justo por debajo y justo por encima de 'a' y 'b'.","Solo los valores exactos 'a' y 'b'."],"h":["Los errores de programación tienden a acumularse en los límites del campo de entrada (por ejemplo, usar < en lugar de <=).","No basta con probar el límite exacto; hay que probar la frontera inmediata para verificar la condición.","Se prueban 4 valores adicionales a los límites exactos (a-1, a+1, b-1, b+1)."],"c":2,"e":"Las directrices del AVL indican que, para un rango [a, b], se deben diseñar casos de prueba para los valores exactos 'a' y 'b', así como para los valores inmediatamente inferiores y superiores a estos límites, ya que es donde suelen producirse los errores de lógica en las condiciones.","d":1,"id":"q226","unit":"UF2406-UD6","tipo":"ampliado","nv":"Fácil"},{"q":"En la estructura de manejo de excepciones try-catch-finally de Java, ¿cuál es la función principal y característica del bloque finally?","o":["Omitir la ejecución del código si ocurre un error de sintaxis en el bloque try.","Lanzar una nueva excepción personalizada al sistema de ejecución.","Capturar la excepción lanzada en el bloque try.","Ejecutarse siempre al salir del bloque try, independientemente de si se lanzó una excepción o no."],"h":["Es el lugar ideal para escribir código de limpieza (como cerrar archivos, bases de datos o conexiones de red).","Su ejecución es incondicional al finalizar el bloque try, incluso si hay una sentencia return.","No es un bloque obligatorio, pero su uso es considerado una buena práctica de programación."],"c":3,"e":"El bloque finally siempre se ejecuta cuando se sale del bloque try, ya sea porque el código finalizó correctamente, porque se lanzó una excepción, o porque se ejecutó una sentencia de retorno. Es el lugar idóneo para prevenir pérdidas de recursos del sistema.","d":1,"id":"q227","unit":"UF2406-UD7","tipo":"ampliado","nv":"Fácil"},{"q":"Según el Manifiesto para el desarrollo de software ágil, ¿cuál de los siguientes pares de valores representa correctamente una de las valoraciones principales, donde se valora más el elemento de la izquierda que el de la derecha?","o":["Procesos y herramientas sobre individuos e interacciones.","Documentación exhaustiva sobre software que funciona.","Respuesta ante el cambio sobre seguir un plan.","Negociación del contrato sobre colaboración con el cliente."],"h":["El manifiesto valora la adaptabilidad y la flexibilidad por encima de la rigidez.","Aunque los elementos de la derecha tienen valor, se valoran más los de la izquierda.","La planificación no debe ser estricta, sino flexible y abierta a los cambios que surjan durante el proyecto."],"c":2,"e":"El Manifiesto Ágil establece cuatro valores fundamentales. Uno de ellos es \"Respuesta ante el cambio sobre seguir un plan\". Esto significa que la habilidad de responder a los cambios (en requisitos, tecnología, equipo, etc.) determina el éxito del proyecto, por lo que la planificación debe adaptarse continuamente.","d":2,"id":"q228","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de casos de uso, ¿qué elemento representa a una entidad externa (persona, sistema o hardware) que interactúa con el sistema bajo desarrollo?","o":["Una clase de control.","Un paquete.","Un rombo.","Un actor."],"h":["Se representa gráficamente como un \"hombre de palo\" o un rectángulo con el estereotipo <<actor>>.","No forma parte interna del sistema, sino que se sitúa fuera de sus límites (frontera del sistema).","Interactúa con el sistema mediante asociaciones directas a los casos de uso."],"c":3,"e":"Un actor es un clasificador con comportamiento que especifica un papel desempeñado por una entidad externa que interactúa con el escenario (el sistema). Puede ser un usuario humano, otro sistema o un dispositivo de hardware que utiliza los servicios de la asignatura modelada.","d":2,"id":"q229","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de casos de uso de UML, ¿qué representa la relación de inclusión (<<include>>) entre dos casos de uso?","o":["Un comportamiento que se inserta obligatoriamente en el comportamiento del caso de uso base.","Un comportamiento opcional que extiende el caso de uso base bajo ciertas condiciones.","Una relación de herencia o generalización entre el caso de uso base y el incluido.","Una dependencia de un actor externo hacia el sistema para iniciar el proceso."],"h":["La palabra clave de esta relación es que el comportamiento es \"obligatorio\", no opcional.","Se utiliza frecuentemente para extraer y reutilizar partes comunes de comportamientos de dos o más casos de uso.","El caso de uso incluido no suele tener sentido ni ejecutarse por sí mismo sin la invocación del caso de uso base."],"c":0,"e":"La relación de inclusión (<<include>>) indica que el comportamiento del caso de uso incluido se inserta en el comportamiento del caso de uso base. A diferencia de la extensión (<<extend>>), que es opcional y condicional, la inclusión es una operación obligatoria que siempre se ejecuta cuando se ejecuta el caso de uso base.","d":2,"id":"q230","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál de las siguientes afirmaciones sobre las excepciones en tiempo de ejecución (RuntimeException) en Java es correcta?","o":["No están sujetas a la captura o especificación obligatoria por parte del compilador.","Deben ser capturadas obligatoriamente con un bloque try-catch.","Son condiciones externas a la aplicación que el programa no puede anticipar.","El compilador exige que se especifiquen en la cláusula throws del método."],"h":["Suelen indicar errores de programación, como errores lógicos o uso incorrecto de una API.","Ejemplos típicos incluyen NullPointerException o IndexOutOfBoundsException.","El compilador no obliga a manejarlas, a diferencia de las excepciones \"comprobadas\" (checked)."],"c":0,"e":"Las excepciones en tiempo de ejecución (RuntimeException y sus subclases) representan problemas internos del programa. El compilador de Java no requiere que el programador las capture o las especifique en la firma del método, dejando esa responsabilidad al criterio del desarrollador para mantener la claridad del código.","d":2,"id":"q231","unit":"UF2406-UD7","tipo":"ampliado","nv":"Intermedio"},{"q":"Según el método de prueba del camino básico propuesto por Tom McCabe, ¿qué mide la complejidad ciclomática V(G) de un programa?","o":["El número de variables globales y locales declaradas.","El número de caminos independientes del conjunto básico de un programa.","El número total de líneas de código fuente del programa.","La cantidad de memoria RAM necesaria para ejecutar el programa."],"h":["Se puede calcular con la fórmula V(G) = A - N + 2 (Aristas - Nodos + 2).","Define un límite superior para el número de pruebas que se deben realizar.","Garantiza que cada sentencia del programa se ejecute al menos una vez."],"c":1,"e":"La complejidad ciclomática proporciona una medida cuantitativa de la complejidad lógica de un programa. El valor calculado define el número de caminos independientes del conjunto básico, lo que sirve como guía para definir los casos de prueba y asegurar una cobertura adecuada del flujo de control.","d":3,"id":"q232","unit":"UF2406-UD6","tipo":"ampliado","nv":"Difícil"},{"q":"En la gestión de memoria de la KVM, ¿qué algoritmo de recolección de basura mueve bloques de memoria ya alojados a lo largo de la memoria y ajusta las referencias, requiriendo temporalmente un almacenamiento extra?","o":["Conservative collection.","Simple reference counting.","Mark-Sweep collection.","Copying collector."],"h":["Su nombre en inglés indica que \"copia\" los bloques de un lugar a otro.","Soluciona problemas de fragmentación externa y mejora la localización de referencias.","Requiere que coexistan la copia antigua y la nueva del bloque durante el movimiento."],"c":3,"e":"El algoritmo Copying Collector mueve bloques de memoria ya alojados a lo largo de la memoria completa y ajusta las referencias a la nueva localización. Su principal desventaja es que necesita de forma temporal un almacenamiento extra de memoria para que coexistan la copia antigua y la copia nueva del bloque mientras se realiza el movimiento.","d":3,"id":"q233","unit":"UF2404-UD7","tipo":"ampliado","nv":"Supremo"},{"q":"Al generar documentación automática con Javadoc, ¿qué etiqueta de bloque se utiliza para indicar que un método, clase o campo está obsoleto y no debe utilizarse, sugiriendo a menudo una alternativa?","o":["@version","@exception","@deprecated","@see"],"h":["Indica que el elemento ha quedado obsoleto por alguna razón.","Se puede utilizar en todos los apartados de la documentación (clases, métodos, atributos).","En el texto de la etiqueta se suele indicar qué se debe utilizar en su lugar."],"c":2,"e":"La etiqueta @deprecated se utiliza en Javadoc para marcar elementos obsoletos. Indica que no debe utilizarse, explicando en el texto las causas de ello y, si se ha realizado una sustitución, qué elemento nuevo se debe utilizar en su lugar.","d":1,"id":"q234","unit":"UF2406-UD8","tipo":"ampliado","nv":"Fácil"},{"q":"En el diseño de casos de prueba, ¿en qué consiste la técnica de partición equivalente?","o":["Examinar la estructura de control interna del programa para obtener los casos de prueba.","Probar todos los posibles valores de entrada de forma exhaustiva.","Ejecutar el programa paso a paso utilizando un depurador para verificar el estado de las variables.","Dividir el campo de entrada de un programa en clases de datos de las que se pueden derivar casos de prueba para descubrir clases de errores."],"h":["Es un método de prueba de caja negra.","Reduce el número total de casos de prueba que hay que desarrollar.","Un caso de prueba ideal descubre de forma inmediata una clase de errores genérica."],"c":3,"e":"La partición equivalente es un método que divide el campo de entrada en clases de equivalencia (válidas o no válidas). Se asume que si un caso de prueba de una clase descubre un error, los demás casos de esa misma clase también lo descubrirán, lo que permite reducir drásticamente el número de pruebas necesarias.","d":2,"id":"q235","unit":"UF2406-UD6","tipo":"ampliado","nv":"Intermedio"},{"q":"Según las buenas prácticas de documentación y estándares de codificación, ¿cuál de las siguientes afirmaciones es verdadera respecto a los comentarios en el código?","o":["Los comentarios deben colocarse siempre al final de cada línea de código para no interrumpir la lectura.","No es necesario actualizar los comentarios cuando se modifica el algoritmo, ya que el código se explica por sí solo.","Es conveniente que los comentarios expliquen por qué se hace algo, especialmente en fragmentos no evidentes, y deben actualizarse si el programa se modifica.","Los comentarios deben repetir exactamente lo que hace el código línea por línea."],"h":["No hay que repetir lo obvio, sino explicar la lógica o las limitaciones.","Los comentarios desactualizados pueden llevar a confusión y errores futuros.","Se recomienda poner comentarios al principio de ficheros, funciones, clases y delante de variables."],"c":2,"e":"Documentar el código implica añadir información suficiente para explicar lo que hace y por qué. No se debe repetir lo que el código ya dice explícitamente, sino explicar la intención. Además, es crucial actualizar los comentarios al mismo tiempo que se modifica el código para evitar que queden obsoletos y generen confusión.","d":1,"id":"q236","unit":"UF2406-UD8","tipo":"ampliado","nv":"Fácil"},{"q":"En la metodología Extreme Programming (XP), ¿en qué consiste la práctica de \"Programación en parejas\" (Pair programming)?","o":["Dos programadores escriben el mismo código en dos ordenadores diferentes simultáneamente.","Un programador senior supervisa el trabajo de un junior una vez a la semana.","Un programador escribe el código mientras el otro revisa cada línea en tiempo real, intercambiando roles frecuentemente.","Dos programadores trabajan en módulos separados y los integran al final del sprint."],"h":["Uno actúa como \"conductor\" (driver) y el otro como \"observador\" o \"navegante\".","Los roles se intercambian con frecuencia (por ejemplo, cada 30 minutos).","Mejora la calidad del diseño, reduce la tasa de errores y facilita la transferencia de conocimiento."],"c":2,"e":"La programación en parejas es una técnica donde dos programadores trabajan juntos en el mismo ordenador. Uno teclea el código (driver) mientras el otro revisa cada línea (observer/navigator), considerando la dirección del trabajo y posibles mejoras, intercambiando roles frecuentemente.","d":1,"id":"q237","unit":"UF2406-UD1","tipo":"ampliado","nv":"Fácil"},{"q":"¿Cuál es la principal diferencia entre los componentes AWT y los componentes Swing en Java?","o":["AWT utiliza código nativo del sistema operativo (peso pesado), mientras que Swing está escrito completamente en Java y se dibuja directamente (peso ligero).","Swing utiliza código nativo del sistema operativo para cada componente, mientras que AWT está escrito completamente en Java.","No existe ninguna diferencia, son nombres distintos para la misma librería.","AWT es más moderno y tiene más funcionalidades que Swing."],"h":["Los componentes AWT dependen de la plataforma donde se ejecutan.","Swing ofrece mayor portabilidad y personalización de la apariencia.","AWT se conoce como de \"peso pesado\" y Swing como de \"peso ligero\"."],"c":0,"e":"AWT (Abstract Window Toolkit) utiliza código nativo del sistema operativo para renderizar sus componentes, lo que limita su portabilidad y apariencia. Swing, en cambio, está escrito completamente en Java y dibuja sus propios componentes, siendo más flexible, portable y consumiendo menos recursos del sistema operativo (peso ligero).","d":2,"id":"q238","unit":"UF2406-UD4","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál es el objetivo principal de llevar a cabo las pruebas de regresión durante el mantenimiento o la evolución de un sistema software?","o":["Verificar que el software cumple con los requisitos funcionales iniciales establecidos por el cliente.","Asegurar que las modificaciones recientes no han introducido nuevos errores en las funcionalidades que ya funcionaban correctamente.","Validar que la interfaz de usuario es intuitiva, accesible y fácil de usar para el usuario final.","Comprobar que el sistema soporta cargas de trabajo anormales o volúmenes de datos elevados sin colapsar."],"h":["Se realizan específicamente después de aplicar cambios, correcciones de errores o actualizaciones en el código.","Su nombre proviene de la idea de \"regresar\" o volver a probar lo que ya estaba probado y funcionando.","Evitan el efecto secundario de \"romper\" una funcionalidad antigua al arreglar o añadir una nueva."],"c":1,"e":"Las pruebas de regresión se ejecutan para garantizar que los cambios recientes en el código (ya sean correcciones de bugs, nuevas funcionalidades o cambios de configuración) no han afectado negativamente a las partes del sistema que ya habían sido validadas y funcionaban correctamente.","d":2,"id":"q239","unit":"UF2406-UD6","tipo":"ampliado","nv":"Intermedio"},{"q":"En el Lenguaje Unificado de Modelado (UML), ¿qué tipo de diagrama se utiliza para mostrar la arquitectura física del sistema, representando la distribución de artefactos de software (como ejecutables, bibliotecas o archivos de configuración) en nodos de hardware (como servidores, estaciones de trabajo o dispositivos)?","o":["Diagrama de despliegue.","Diagrama de componentes.","Diagrama de paquetes.","Diagrama de objetos."],"h":["Muestra el \"dónde\" se ejecuta el software, no el \"cómo\" está estructurado lógicamente.","Sus elementos principales son los \"nodos\" (dispositivos de hardware o entornos de ejecución) y los \"artefactos\".","Es fundamental para planificar la instalación, la topología de red y el entorno de producción de una aplicación."],"c":0,"e":"El diagrama de despliegue es un diagrama de estructura en UML que muestra la arquitectura del sistema en cuanto al despliegue (distribución) de artefactos de software en los destinos de despliegue (nodos de hardware o entornos de ejecución de software).","d":3,"id":"q240","unit":"UF2406-UD3","tipo":"ampliado","nv":"Difícil"},{"q":"¿Cuál de las siguientes sentencias SQL pertenece al Lenguaje de Definición de Datos (DDL) y se utiliza para eliminar completamente una tabla, haciendo desaparecer de la base de datos tanto su estructura como el contenido de la misma?","o":["DROP","DELETE","TRUNCATE","REMOVE"],"h":["Elimina el objeto de la base de datos por completo, no solo sus filas.","Es la contraparte directa de la sentencia CREATE.","A diferencia de TRUNCATE, esta sentencia elimina también la definición de la tabla del diccionario de datos."],"c":0,"e":"La sentencia DROP TABLE elimina por completo la tabla, desapareciendo de la base de datos tanto su estructura (columnas, restricciones) como el contenido de la misma. DELETE y TRUNCATE solo eliminan las filas, pero mantienen la estructura de la tabla intacta.","d":1,"id":"q241","unit":"UF2405-UD6","tipo":"ampliado","nv":"Fácil"},{"q":"¿Cuál de las siguientes es una ventaja principal de utilizar un cliente ligero (Thin Client) en una arquitectura de aplicaciones web?","o":["Requiere hardware de alto rendimiento en cada estación de trabajo del usuario.","Mayor rendimiento en el procesamiento local de la lógica de negocio compleja.","Información centralizada, menor coste de hardware y menor coste en administración.","Instalación compleja y mantenimiento descentralizado en cada equipo."],"h":["El cliente ligero solo se encarga de la interfaz de usuario, no de la lógica.","La lógica de negocio y los datos residen centralizados en el servidor.","Facilita las actualizaciones (solo se hace en el servidor) y reduce los requisitos del equipo del usuario."],"c":2,"e":"Los clientes ligeros centralizan la lógica y los datos en el servidor, lo que reduce el coste de hardware en el lado del cliente, simplifica enormemente el mantenimiento y las actualizaciones, y mejora la seguridad al no distribuir la lógica de negocio en los equipos locales.","d":1,"id":"q242","unit":"UF2405-UD1","tipo":"ampliado","nv":"Fácil"},{"q":"En el modelo Entidad-Relación, ¿cómo se forma la clave primaria de una entidad débil?","o":["Únicamente con sus atributos discriminantes.","Mediante la unión de la clave primaria de la entidad fuerte asociada y los atributos discriminantes de la entidad débil.","Generando un identificador único automático (autoincremental) independiente.","No tiene clave primaria, por definición no puede identificarse."],"h":["Una entidad débil no tiene clave primaria propia por sí misma.","Depende de una entidad fuerte mediante una relación (normalmente muchos a uno).","Necesita un discriminador (clave parcial) para distinguirse de otras entidades débiles relacionadas con la misma entidad fuerte."],"c":1,"e":"Una entidad débil no tiene clave primaria propia. Su clave primaria se forma mediante la unión de la clave primaria de la entidad fuerte (con la que se relaciona) y sus propios atributos discriminantes (clave parcial), garantizando así su identificación única.","d":2,"id":"q243","unit":"UF2405-UD4","tipo":"ampliado","nv":"Intermedio"},{"q":"Según el modelo de ciclo de vida en espiral de Barry Boehm, ¿cuál de las siguientes afirmaciones describe con mayor precisión su diferencia fundamental respecto al modelo de desarrollo incremental?","o":["El modelo en espiral incluye una tarea explícita de evaluación de riesgos en cada ciclo, gestionando la incertidumbre desde el inicio.","El modelo en espiral asume que no hay incertidumbre en los requisitos iniciales, mientras que el incremental la gestiona.","El modelo en espiral no permite la realimentación del cliente, a diferencia del modelo incremental.","El modelo en espiral es más adecuado para proyectos pequeños con requisitos fijos y estables."],"h":["Fue propuesto por Barry Boehm en 1985/1988 específicamente para abordar proyectos complejos.","Combina elementos del modelo de prototipos y del modelo en cascada.","Su principal fortaleza y diferencia distintiva es el análisis de riesgos explícito en cada iteración de la espiral."],"c":0,"e":"La distinción más destacada entre el modelo en espiral y el incremental es que en el incremental se parte de que no hay incertidumbre en los requisitos iniciales (se divide un problema conocido). En cambio, el modelo en espiral es consciente de que se comienza con un alto grado de incertidumbre y gestiona esta incertidumbre mediante una tarea explícita de evaluación de riesgos en cada ciclo.","d":3,"id":"q244","unit":"UF2406-UD1","tipo":"ampliado","nv":"Supremo"},{"q":"En una página Java Server Pages (JSP), ¿cuál de los siguientes objetos implícitos se utiliza para almacenar datos que deben persistir a lo largo de toda la sesión de un usuario específico (por ejemplo, un carrito de la compra)?","o":["pageContext","application","session","request"],"h":["Representa una conversación continua entre el cliente y el servidor.","Permite mantener el estado individual del usuario entre múltiples peticiones HTTP.","Se obtiene y gestiona mediante la interfaz HttpSession."],"c":2,"e":"El objeto implícito session (de tipo HttpSession) permite almacenar información específica de un usuario a lo largo de múltiples peticiones. A diferencia de request (que es efímero, dura una sola petición) o application (que es global para todos los usuarios), session mantiene el estado individual mientras la sesión esté activa.","d":2,"id":"q245","unit":"UF2405-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En JSP, ¿qué directiva se utiliza para insertar el contenido de otro archivo (HTML, JSP) en el servlet en el momento de la traducción de JSP a servlet?","o":["<%@ include ... %>","<jsp:include ... />","<%@ taglib ... %>","<%@ page ... %>"],"h":["Es una directiva, no una acción (por lo tanto, no usa la sintaxis <jsp:...>).","Su atributo principal para especificar el archivo es file.","La inclusión se realiza en tiempo de traducción (antes de compilar), no en tiempo de ejecución."],"c":0,"e":"La directiva <%@ include file=\"URL\" %> añade el contenido del archivo especificado antes de comenzar la fase de traducción al servlet. Esto permite la reutilización de código estático o fragmentos JSP (como cabeceras o menús) de manera eficiente.","d":1,"id":"q246","unit":"UF2405-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"Si un cliente tiene las cookies deshabilitadas en su navegador, ¿qué mecanismo utiliza el contenedor de servlets por detrás para garantizar que el seguimiento de sesión (Session Tracking) siga funcionando correctamente?","o":["Reescritura de URLs (URL-rewriting).","Uso de la directiva <%@ page session=\"false\" %>.","Almacenamiento exclusivo en el objeto application.","Campos ocultos en formularios (hidden form fields)."],"h":["El servidor añade el ID de sesión directamente a la URL de los enlaces.","Para garantizar que funcione, el desarrollador debe usar el método response.encodeURL().","El formato resultante en la URL suele ser algo como ;jsessionid=1234."],"c":0,"e":"Cuando las cookies están deshabilitadas, el mecanismo de control de sesión recurre a la reescritura de URLs. El contenedor añade el ID de sesión a todas las URLs que refieren al sitio web propio, permitiendo al servidor identificar al usuario y mantener su estado a través de las peticiones.","d":2,"id":"q247","unit":"UF2405-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En el contexto de JSP 2.0 y JSTL, ¿cuál es la sintaxis correcta para evaluar una expresión y acceder a datos (como atributos de un bean) sin necesidad de usar scriptlets de Java (<%= ... %>)?","o":["#{ expression }","${ expression }","<% expression %>","@{ expression }"],"h":["Se introduce con el símbolo de dólar seguido de llaves.","Puede usarse como valor de atributo en acciones o directamente dentro del texto de una plantilla HTML.","Fue introducido originalmente con JSTL y luego extendido para usarse en cualquier parte de la página JSP 2.0."],"c":1,"e":"La sintaxis ${ expression } es la base de Expression Language (EL). Está diseñada para simplificar drásticamente el acceso a datos (como atributos de beans, parámetros de petición o atributos de sesión) y evitar el uso de scriptlets de Java, haciendo las páginas JSP mucho más legibles, concisas y fáciles de mantener.","d":3,"id":"q248","unit":"UF2405-UD3","tipo":"ampliado","nv":"Supremo"},{"q":"¿Cuál de las siguientes NO es una ventaja del ciclo de vida en espiral?","o":["Permite la gestión de riesgos en cada iteración.","Es difícil evaluar los riesgos.","Combina lo mejor del modelo en cascada y de la construcción de prototipos.","Es adecuado para proyectos grandes, caros y complejos."],"h":["Busca la opción que describe un problema, limitación o dificultad.","El análisis de riesgos es la principal fortaleza del modelo, pero requiere mucha experiencia.","La redacción \"Es difícil evaluar...\" indica un inconveniente, no un beneficio."],"c":1,"e":"Que sea \"difícil evaluar los riesgos\" es un inconveniente, ya que el análisis de riesgos exige un alto nivel de experiencia y habilidad por parte del equipo de desarrollo. No es una ventaja, sino un desafío del modelo.","d":2,"id":"q249","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál de los siguientes NO es un objetivo de una herramienta CASE (Computer-Aided Software Engineering)?","o":["Facilitar la reutilización de componentes de software.","Eliminar la necesidad de esfuerzo de programación.","Mejorar la calidad y consistencia de la documentación.","Facilitar la creación de prototipos."],"h":["Las herramientas CASE asisten y apoyan al ingeniero, pero no lo reemplazan.","La programación y la toma de decisiones lógicas siguen siendo tareas humanas fundamentales.","Sus objetivos reales son aumentar la productividad y la calidad, no eliminar el esfuerzo por completo."],"c":1,"e":"Las herramientas CASE apoyan y automatizan tareas del desarrollo, pero no eliminan la necesidad de esfuerzo de programación. Sus objetivos reales son facilitar prototipos, mejorar la documentación, aumentar la productividad y facilitar la reutilización.","d":2,"id":"q250","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"Sobre los prototipos en ingeniería del software:","o":["Reducen el coste de la fase de mantenimiento a cero.","Sustituyen por completo la necesidad de realizar una fase de análisis de requisitos.","Su objetivo es entregar el producto final al cliente lo antes posible.","Su propósito es que los usuarios finales puedan evaluar las propuestas de los desarrolladores."],"h":["Es un modelo preliminar, un \"borrador\" o maqueta del sistema.","Busca obtener retroalimentación (feedback) temprana del cliente.","Ayuda a clarificar y refinar requisitos que no estaban claros inicialmente."],"c":3,"e":"Los prototipos son modelos preliminares del sistema que permiten a los usuarios finales visualizar, evaluar y proporcionar retroalimentación sobre las propuestas de los desarrolladores antes de la implementación final, reduciendo así el riesgo de malentendidos en los requisitos.","d":2,"id":"q251","unit":"UF2406-UD1","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Qué proceso, efectuado durante la primera fase del ciclo de vida, comprende la evaluación del esfuerzo necesario, de la duración del proyecto y de los recursos necesarios para llevarlo a cabo?","o":["Planificación.","Programación.","Estimación.","Presupuestación."],"h":["Se realiza al inicio del proyecto para prever los costes y tiempos.","No es lo mismo que la planificación, que organiza cuándo se hará; esto calcula cuánto costará en esfuerzo y recursos.","Es un proceso inherentemente incierto que mejora a medida que avanza el proyecto."],"c":2,"e":"La estimación es el proceso fundamental de evaluar el esfuerzo (generalmente en horas-persona), la duración (calendario) y los recursos (humanos, técnicos, económicos) necesarios para completar un proyecto de software con éxito.","d":1,"id":"q252","unit":"UF2406-UD2","tipo":"ampliado","nv":"Fácil"},{"q":"¿Qué modelos relacionan un conjunto de variables dependientes (por ejemplo, esfuerzo y calendario del proyecto) con una o más variables independientes denominadas factores de costo (por ejemplo, el uso de herramientas CASE o la capacidad de los analistas)?","o":["Modelos analógicos.","Modelos paramétricos.","Modelos heurísticos.","Modelos de juicio de expertos."],"h":["Utilizan fórmulas matemáticas y estadísticas derivadas de datos históricos.","COCOMO es el ejemplo más famoso de este tipo de modelo.","Las variables independientes se conocen como \"multiplicadores de esfuerzo\" o factores de costo."],"c":1,"e":"Los modelos paramétricos utilizan ecuaciones matemáticas que relacionan variables dependientes (como el esfuerzo o el calendario) con factores de costo independientes (como la experiencia del equipo, la complejidad o las herramientas utilizadas), basándose en datos históricos de proyectos anteriores.","d":2,"id":"q253","unit":"UF2406-UD2","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál de los siguientes métodos de estimación es uno de los más comunes y utilizados a día de hoy en la gestión de proyectos de software?","o":["Gantt.","SLIM.","Delphi.","PERT."],"h":["Sus siglas significan Software Lifecycle Management.","Está basado en el modelo de Putnam y la ley de Rayleigh-Norden.","Es una herramienta y metodología de estimación dinámica muy extendida en la industria."],"c":1,"e":"SLIM (Software Lifecycle Management) es un método y herramienta de estimación basado en el modelo de Putnam, muy utilizado en la industria para estimar esfuerzo, calendario y dotación de personal a lo largo del ciclo de vida del software.","d":1,"id":"q254","unit":"UF2406-UD2","tipo":"ampliado","nv":"Fácil"},{"q":"La medida más común de la exactitud promedio de estimación es la MRE o magnitud del error relativo medio. ¿Cómo se define la fórmula del MRE de cada estimación?","o":["MRE = (esfuerzo real - esfuerzo estimado) / esfuerzo real.","MRE = esfuerzo real / esfuerzo estimado.","MRE = (esfuerzo real + esfuerzo estimado) / 2.","MRE = (esfuerzo estimado - esfuerzo real) / esfuerzo estimado."],"h":["Compara la diferencia entre lo que se planificó y lo que realmente ocurrió.","El denominador de la fracción es el valor \"real\" o verdadero, para normalizar el error.","Un MRE cercano a 0 indica una estimación muy precisa."],"c":0,"e":"La fórmula del MRE (Magnitude of Relative Error) calcula el error relativo dividiendo la diferencia entre el esfuerzo real y el estimado por el esfuerzo real. Esto permite evaluar la precisión de la estimación de forma estandarizada, independientemente del tamaño del proyecto.","d":3,"id":"q255","unit":"UF2406-UD2","tipo":"ampliado","nv":"Difícil"},{"q":"Dentro del método de estimación COCOMO (Constructive Cost Model), ¿qué tres modos de desarrollo se contemplan?","o":["Orgánico, semiacoplado y empotrado.","Pequeño, mediano y grande.","Ágil, cascada y espiral.","Interno, externo y mixto."],"h":["El modo \"orgánico\" se refiere a proyectos pequeños y equipos con mucha experiencia.","El modo \"empotrado\" se refiere a proyectos que deben desarrollarse dentro de un conjunto de restricciones (técnicas, de hardware) muy rígidas.","El modo intermedio se llama \"semiacoplado\" (o semidetached)."],"c":0,"e":"COCOMO clásico define tres modos de desarrollo: Orgánico (proyectos pequeños, requisitos flexibles, equipo experimentado), Semiacoplado (proyectos de tamaño y complejidad intermedios) y Empotrado (proyectos que deben desarrollarse dentro de restricciones técnicas u operativas muy rígidas).","d":2,"id":"q256","unit":"UF2406-UD2","tipo":"ampliado","nv":"Intermedio"},{"q":"En el contexto de los modelos de estimación (como COCOMO II), el atributo RUSE se refiere a:","o":["El índice de reutilización del producto.","La usabilidad del software desarrollado.","El riesgo de uso de nuevas tecnologías.","El uso de recursos del sistema en tiempo de ejecución."],"h":["Proviene de la palabra en inglés \"Reuse\".","Cuanto mayor es este valor, menor suele ser el esfuerzo de desarrollo nuevo requerido.","Es un factor multiplicador que ajusta la estimación basándose en componentes ya existentes."],"c":0,"e":"El atributo RUSE (Reuse) mide el porcentaje de código o componentes de software que se reutilizan en el proyecto. Un alto índice de reutilización reduce el esfuerzo de desarrollo necesario, ajustando a la baja la estimación total del proyecto.","d":3,"id":"q257","unit":"UF2406-UD2","tipo":"ampliado","nv":"Difícil"},{"q":"En el contexto de los métodos de estimación por puntos de función, ¿en qué se basa fundamentalmente el método Mark II?","o":["Se basa exclusivamente en la opinión de expertos mediante la técnica Delphi.","Se basa en líneas de código fuente (KLOC).","Se basa en contar transacciones lógicas del usuario: entradas, salidas y objetos (entidades de datos).","Se basa en el análisis de la complejidad ciclomática del código."],"h":["Es una evolución del análisis de puntos de función tradicional (Albrecht).","Se centra en las transacciones lógicas que cruzan el límite de la aplicación.","Es especialmente útil para sistemas de información empresarial y transaccionales."],"c":2,"e":"El método MkII (Symons) identifica las necesidades funcionales del usuario y las clasifica en entradas, salidas y objetos; el tamaño funcional resulta de contar y ponderar esas transacciones lógicas. No se basa en líneas de código ni en juicio de expertos.","d":3,"id":"q258","unit":"UF2406-UD2","tipo":"ampliado","nv":"Supremo"},{"q":"En el modelo de estimación de Putnam, se distinguen dos clases de productividad. ¿Cuáles son?","o":["Productividad convencional y productividad del proceso.","Productividad de código y productividad de diseño.","Productividad individual y productividad de equipo.","Productividad estática y productividad dinámica."],"h":["Una se refiere a la capacidad bruta del equipo de desarrollo.","La otra se refiere a cómo las herramientas, el entorno y la metodología mejoran esa capacidad base.","El modelo de Putnam (SLIM) utiliza estos factores para ajustar la curva de Rayleigh."],"c":0,"e":"Putnam distingue entre la productividad convencional (la capacidad inherente del equipo de desarrollo) y la productividad del proceso (la mejora en la eficiencia lograda mediante el uso de herramientas avanzadas, metodologías maduras y un buen entorno de desarrollo).","d":2,"id":"q259","unit":"UF2406-UD2","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Cuál de las siguientes es una ventaja del método de estimación funcional COSMIC (Common Software Measurement International Consortium)?","o":["Es fácil de aprender, mejora la precisión de la estimación y es excelente para controlar la calidad de los requisitos.","Reduce la precisión de la estimación en fases tempranas.","Es difícil de aprender y aplicar.","Solo sirve para proyectos de software embebido."],"h":["Es un estándar ISO (ISO/IEC 19761).","Está diseñado para ser aplicable a cualquier tipo de software (web, embebido, BI, etc.).","Su simplicidad relativa lo hace muy adoptable en la industria."],"c":0,"e":"El método COSMIC tiene múltiples ventajas: es relativamente fácil de aprender y aplicar, mejora significativamente la precisión de las estimaciones de tamaño funcional en comparación con métodos más antiguos, y es una herramienta excelente para medir y controlar la calidad y el alcance de los requisitos del software.","d":1,"id":"q260","unit":"UF2406-UD2","tipo":"ampliado","nv":"Fácil"},{"q":"En la gestión y estimación de proyectos de software, las siglas RBS (Resource Breakdown Structure) se refieren a:","o":["Un documento legal de requisitos del sistema.","Un diagrama de tipo árbol jerárquico que representa los recursos humanos y materiales de un proyecto.","Un sistema de control de versiones de código fuente.","Una base de datos de riesgos del proyecto."],"h":["\"Breakdown Structure\" significa estructura de desglose (como la WBS, pero de recursos).","Ayuda a organizar y categorizar todos los recursos necesarios para la estimación.","Incluye tanto personal (desarrolladores, analistas) como equipos (servidores, licencias de software)."],"c":1,"e":"La RBS (Resource Breakdown Structure) es una estructura jerárquica en forma de árbol que organiza y representa todos los recursos (humanos, materiales, equipos y software) necesarios para llevar a cabo el proyecto, facilitando su asignación y estimación de costes.","d":2,"id":"q261","unit":"UF2406-UD2","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Qué es UML (Lenguaje Unificado de Modelado)?","o":["Un conjunto de especificaciones que indican cómo construir unos diagramas que sirvan para intercambiar información.","Un lenguaje de programación orientado a objetos de última generación.","Una herramienta CASE exclusiva para el diseño de bases de datos relacionales.","Un sistema operativo diseñado para servidores de aplicaciones."],"h":["No es un lenguaje de programación, sino un lenguaje de modelado visual.","Su objetivo principal es la estandarización y la comunicación entre desarrolladores y clientes.","Se basa en la creación de diagramas visuales para representar el sistema."],"c":0,"e":"UML es un lenguaje de modelado visual estandarizado que proporciona un conjunto de especificaciones para construir diagramas, permitiendo modelar, visualizar, construir y documentar los artefactos de un sistema de software de manera uniforme.","d":1,"id":"q262","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"En UML, ¿qué muestran los diagramas de comportamiento?","o":["El comportamiento dinámico de los objetos del sistema.","El despliegue físico del hardware y los servidores.","La jerarquía de paquetes y módulos del software.","La estructura estática de las bases de datos del sistema."],"h":["Se oponen a los diagramas estructurales (que son estáticos).","Incluyen diagramas como el de secuencia, actividad, estados y casos de uso.","Muestran cómo cambia el sistema o cómo interactúan sus partes a lo largo del tiempo."],"c":0,"e":"Los diagramas de comportamiento modelan la dinámica del sistema. Muestran cómo interactúan los objetos entre sí y cómo cambia el estado del sistema a lo largo del tiempo en respuesta a eventos o acciones.","d":2,"id":"q263","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"¿Qué representa el diagrama de clases en UML?","o":["Muestra el flujo de datos entre procesos de negocio.","Es un diagrama que muestra la estructura del sistema diseñado en el nivel de las clases y las interfaces.","Describe exclusivamente los casos de uso del usuario final.","Representa la topología de la red física de la empresa."],"h":["Es el diagrama estructural más importante en la Programación Orientada a Objetos.","Muestra atributos (datos) y operaciones (métodos).","Define las relaciones (herencia, asociación, composición) entre las entidades."],"c":1,"e":"El diagrama de clases es un diagrama estructural estático que muestra las clases del sistema, sus atributos, operaciones y las relaciones (asociaciones, generalizaciones, dependencias, etc.) entre los objetos.","d":1,"id":"q264","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"En el contexto de UML y la Programación Orientada a Objetos, ¿qué es una clase abstracta?","o":["Una clase que representa una base de datos externa.","Una clase que hereda de múltiples superclases simultáneamente.","Una clase de la que no se pueden crear objetos (instancias).","Una clase que solo contiene atributos públicos."],"h":["En UML, su nombre se escribe obligatoriamente en letra cursiva.","Sirve como plantilla o molde genérico para otras clases.","Debe ser heredada por una subclase concreta para poder ser utilizada."],"c":2,"e":"Una clase abstracta es una clase que no puede ser instanciada (no se pueden crear objetos directos de ella). Su propósito es servir como base para que otras clases hereden de ella y implementen o sobrescriban su comportamiento.","d":2,"id":"q265","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de clases UML, ¿qué especifica una operación?","o":["Únicamente el nombre de la variable de instancia.","La relación de herencia con otra clase.","La visibilidad del paquete al que pertenece.","Nombre, tipo de retorno y parámetros."],"h":["Equivale a lo que en programación llamamos un \"método\" o \"función\".","Se escribe en el tercer compartimento (el inferior) del rectángulo de la clase.","Incluye la firma completa de la acción que puede realizar el objeto."],"c":3,"e":"En UML, una operación (equivalente a un método en programación) se define especificando su nombre, el tipo de dato que devuelve (tipo de retorno) y los parámetros que recibe, junto con su nivel de visibilidad.","d":1,"id":"q266","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"¿Cuáles son los niveles de visibilidad definidos en UML para atributos y operaciones?","o":["Estática, dinámica, abstracta y final.","Pública, de paquete, protegida y privada.","Lectura, escritura, ejecución y borrado.","Interna, externa, global y local."],"h":["Se representan gráficamente con los símbolos: +, ~, #, -.","Controlan el principio de encapsulamiento del objeto.","El nivel \"protegido\" permite el acceso a las subclases que heredan de la clase."],"c":1,"e":"UML define cuatro niveles de visibilidad estándar: pública (+), protegida (#), privada (-) y de paquete (~). Estos determinan qué otros elementos del sistema pueden acceder o modificar un atributo u operación.","d":2,"id":"q267","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En UML, ¿qué es una asociación?","o":["Un error de compilación en el código.","Un diagrama de despliegue de hardware.","Un tipo de variable global compartida.","Una relación semántica entre clasificadores."],"h":["Se representa gráficamente con una línea sólida que conecta dos clases.","Indica que los objetos de una clase \"conocen\" o se relacionan con los de otra.","Es la relación estructural más básica y común en los diagramas de clases."],"c":3,"e":"En UML, una asociación es una relación estructural (semántica) entre clasificadores (como clases o interfaces) que describe las conexiones y colaboraciones entre sus instancias (objetos).","d":1,"id":"q268","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"En un diagrama de casos de uso, ¿qué representa un actor?","o":["Un elemento externo al sistema que interactúa con él.","Una base de datos relacional del núcleo del software.","Un método interno del sistema que procesa datos.","Una clase abstracta del sistema."],"h":["Se dibuja como un \"muñeco de palo\" o con el estereotipo <<actor>>.","Puede ser una persona, otro sistema informático o un dispositivo de hardware.","Se coloca fuera del rectángulo que delimita la frontera del sistema."],"c":0,"e":"Un actor es una entidad externa (persona, sistema externo o dispositivo) que interactúa con el sistema modelado, ya sea iniciando casos de uso o recibiendo resultados de ellos. No forma parte interna del sistema.","d":1,"id":"q269","unit":"UF2406-UD3","tipo":"ampliado","nv":"Fácil"},{"q":"¿Qué tipo de diagrama es el diagrama de actividad en UML?","o":["Un diagrama de comportamiento.","Un diagrama de componentes.","Un diagrama de despliegue.","Un diagrama estructural."],"h":["Visualmente se parece mucho a un diagrama de flujo de proceso tradicional.","Utiliza rombos para representar decisiones y barras gruesas para sincronización.","Muestra el flujo de control de una operación, un caso de uso o un proceso de negocio."],"c":0,"e":"El diagrama de actividad es un diagrama de comportamiento que modela el flujo de control y de datos entre actividades, mostrando la secuencia de acciones y decisiones en un proceso o algoritmo.","d":2,"id":"q270","unit":"UF2406-UD3","tipo":"ampliado","nv":"Intermedio"},{"q":"En un diagrama de secuencia de UML, ¿qué es un mensaje?","o":["Un elemento que define un tipo específico de comunicación entre dos líneas de vida.","Una variable global compartida entre todos los objetos.","Un error de sintaxis en el código fuente.","Un comentario textual añadido para el programador."],"h":["Se representa con una flecha que va de una línea vertical a otra.","Puede ser síncrono (línea con punta de flecha llena) o asíncrono (línea con punta abierta).","Representa la invocación de una operación o el envío de una señal entre objetos."],"c":0,"e":"En los diagramas de secuencia, un mensaje representa la comunicación entre objetos (líneas de vida). Define la interacción específica, como la invocación de un método, ordenada cronológicamente de arriba hacia abajo a lo largo del tiempo.","d":3,"id":"q271","unit":"UF2406-UD3","tipo":"ampliado","nv":"Difícil"},{"q":"En el contexto de la programación de interfaces gráficas en Java, ¿qué es un evento?","o":["Ocurre cuando el programador llama al método ActionPerformed.","Se produce exclusivamente al pulsar un botón.","Nos informa de las notificaciones que tenemos pendientes.","Es todo hecho que ocurre mientras se ejecuta una aplicación."],"h":["Puede ser generado por el usuario (clic, pulsación de tecla) o por el sistema (temporizador, cierre de ventana).","Es la base del modelo de programación guiada por eventos.","El sistema lo detecta y lo notifica a los oyentes (listeners) registrados."],"c":3,"e":"Un evento es cualquier hecho o suceso que ocurre durante la ejecución de una aplicación, ya sea provocado por el usuario (como hacer clic en un botón) o por el sistema (como el paso del tiempo en un temporizador), y que puede ser capturado y gestionado por el programa.","d":1,"id":"q272","unit":"UF2406-UD4","tipo":"ampliado","nv":"Fácil"},{"q":"Las casillas de verificación (CheckBox) en una interfaz gráfica:","o":["Han de mostrar listas de texto con fechas y horas.","Junto con las listas desplegables permiten al usuario escoger múltiples elementos a la vez.","Permiten al usuario escoger un solo elemento a la vez, junto con los radioButton.","Muestran una lista de tres columnas."],"h":["A diferencia de los botones de radio, no son mutuamente excluyentes.","El usuario puede marcar varias casillas simultáneamente.","Son ideales para opciones que no se excluyen entre sí (por ejemplo, \"acepto términos\" y \"quiero recibir newsletter\")."],"c":1,"e":"Las casillas de verificación (CheckBox) permiten al usuario seleccionar múltiples opciones de forma independiente. A diferencia de los botones de radio (radioButton), que son mutuamente excluyentes, las casillas de verificación pueden estar marcadas varias al mismo tiempo.","d":2,"id":"q273","unit":"UF2406-UD4","tipo":"ampliado","nv":"Intermedio"},{"q":"Los componentes de la GUI (Interfaz Gráfica de Usuario) de Java:","o":["Se almacenan por eventos.","Se almacenan en clases privadas.","Un ejemplo de ellos es JCanvas.","Son manejados por el modelo de eventos de Java."],"h":["Interactúan con el usuario a través de eventos (clics, pulsaciones de teclas, etc.).","Se registran oyentes (listeners) para responder a las acciones del usuario.","Ejemplos típicos son JButton, JTextField, JLabel, etc."],"c":3,"e":"Los componentes de la GUI en Java (como botones, campos de texto, etiquetas) son gestionados por el modelo de eventos de Java. Cuando el usuario interactúa con ellos, se generan eventos que son capturados por los oyentes (listeners) registrados para ejecutar la lógica correspondiente.","d":1,"id":"q274","unit":"UF2406-UD4","tipo":"ampliado","nv":"Fácil"},{"q":"Cuando se produce un evento en una aplicación Java:","o":["Se llama automáticamente al método principal del programa.","El programador debe detectarlos con un esquema if.","Se generan tres objetos asociados: el oyente, el evento y la interrupción.","Se recibe un parámetro en el programa principal."],"h":["El evento es el objeto que contiene la información de lo que ocurrió.","El oyente (listener) es el objeto registrado para recibir la notificación.","La interrupción (o fuente) es el componente que originó el evento."],"c":2,"e":"Cuando se produce un evento en Java, se generan tres objetos asociados: el objeto evento (que contiene la información del suceso), el oyente (listener) que está registrado para manejarlo, y la fuente o interrupción (el componente que originó el evento). Nota: en el manual los elementos de un evento son la fuente (source), el objeto evento y el oyente (listener); la opción C es la única razonable, pero «interrupción» no es un término del manual.","d":3,"id":"q275","unit":"UF2406-UD4","tipo":"ampliado","nv":"Difícil"},{"q":"Respecto al etiquetado de órdenes en una interfaz de usuario:","o":["Debe darse órdenes para que el sistema recuerde las acciones.","Debe darse la posibilidad que el sistema recuerde las últimas órdenes.","Debe haber órdenes para al menos la mitad de los elementos del menú.","No hay que plantearse la forma de estas."],"h":["Facilita la repetición de tareas frecuentes sin tener que navegar de nuevo por los menús.","Mejora la eficiencia del usuario experto.","Es una buena práctica de usabilidad en el diseño de interfaces."],"c":1,"e":"En el diseño de interfaces, es una buena práctica que el sistema recuerde las últimas órdenes ejecutadas por el usuario, facilitando así la repetición de tareas frecuentes y mejorando la eficiencia, especialmente para usuarios expertos.","d":3,"id":"q276","unit":"UF2406-UD4","tipo":"ampliado","nv":"Difícil"},{"q":"Respecto al IDE (Entorno de Desarrollo Integrado) de programación:","o":["Siempre se trabajará mediante asistentes.","Fuerza al programador a preocuparse por su código.","Los programadores expertos son los que más lo usan.","Proporciona al diseñador una manera fácil de crear aplicaciones."],"h":["Integra herramientas como editor, compilador, depurador y diseñador visual en una sola interfaz.","Facilita el desarrollo rápido de aplicaciones (RAD - Rapid Application Development).","Ejemplos conocidos son Eclipse, NetBeans, IntelliJ IDEA o Visual Studio."],"c":3,"e":"Un IDE (Entorno de Desarrollo Integrado) proporciona al desarrollador/diseñador una manera fácil y eficiente de crear aplicaciones, integrando todas las herramientas necesarias (editor, compilador, depurador, diseñador visual) en una única interfaz unificada.","d":1,"id":"q277","unit":"UF2406-UD1","tipo":"ampliado","nv":"Fácil"},{"q":"Si el software es una primera versión:","o":["No hace falta documentación de requisitos.","La documentación de diseño se puede eliminar.","La documentación de requisitos es muy útil como guía.","Ninguna de las anteriores es correcta."],"h":["Aunque sea la primera versión, el software probablemente evolucionará en el futuro.","La documentación de requisitos sirve como referencia para desarrollos posteriores.","Eliminar documentación siempre es una mala práctica, incluso en versiones iniciales."],"c":2,"e":"Si el software es una primera versión sobre la que más tarde se va a seguir trabajando, la documentación de los requisitos es muy útil como guía para futuros desarrollos, mantenimientos y ampliaciones del sistema.","d":1,"id":"q278","unit":"UF2406-UD8","tipo":"ampliado","nv":"Fácil"},{"q":"El documento de diseño de la base de datos:","o":["No se suele utilizar muy a menudo.","Contiene el diseño conceptual, lógico y físico además de los elementos de diseño de la base de datos.","Es el documento más importante de la fase de pruebas.","Indica el diseño conceptual y físico de la base de datos."],"h":["Abarca las tres etapas completas del diseño de bases de datos.","Incluye elementos como tablas, relaciones, restricciones y procedimientos.","Es un documento fundamental para el desarrollo y mantenimiento del sistema."],"c":1,"e":"El documento de diseño de la base de datos contiene el diseño conceptual, lógico y físico, además de todos los elementos de diseño de la base de datos (tablas, relaciones, restricciones, procedimientos almacenados, etc.).","d":2,"id":"q279","unit":"UF2406-UD8","tipo":"ampliado","nv":"Intermedio"},{"q":"Cuando se documenta:","o":["Se puede asumir que la persona usuaria tendrá unos conocimientos avanzados de informática.","No hay que incluir imágenes en una documentación seria y formal.","No se debe de asumir nada que la persona usuaria deba saber.","Todas las respuestas son incorrectas."],"h":["La documentación debe ser accesible para diferentes niveles de conocimiento.","Las imágenes y diagramas son herramientas válidas y recomendadas en documentación formal.","Asumir conocimientos previos puede hacer que la documentación sea inútil para parte de la audiencia."],"c":2,"e":"Un principio fundamental de la documentación técnica es no asumir nada que la persona usuaria deba saber. La documentación debe ser completa, clara y accesible para el público objetivo, sin dar por sentado conocimientos previos.","d":2,"id":"q280","unit":"UF2406-UD8","tipo":"ampliado","nv":"Intermedio"}];
